__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = "Страж, слышал? Удаленный художественный выставочный зал на окраине города скоро закроется, именно в мой день рождения.\nЭтот зал — извращение в мире искусства, половина его тела — примитивные эксперименты футуризма, другая половина — хлам двух столетий назад. В его узком брюхе находятся только странные вещи, которых никто не осмеливается трогать на аукционах: портреты, ругающиеся грязными словами, механические птицы, которые никогда не перестают летать, морские рельефы, от которых хочется вырвать глаза, статуи, сделанные из слез, призрачные рукописи, автоматически пишущие стихи, черепа человеческих существ, которые напевают детские песни, когда их целуют...\nМне так трудно описать, как я люблю этот зал! Пятьдесят лет назад он тихо родился в этом уголке, о котором никто не заботился. Пятьдесят лет спустя он тихо угасает в том же месте.\nС тех пор как я была ребенком, мне говорили, что этот день — проклятие, как и я сама. Я думаю, Колесо Судьбы действительно заранее предопределена, но что с того? Этот зал создал уникальный мир, так много безумных идей были сложены в этом маленьком пространстве, какая же это прелестная картина! С момента своего рождения он создавал свои выставки. В этот день его завершения его духовные друзья и старые знакомые также попрощаются с ним.\nХранитель, ты увидел мир в моих глазах по ссылке, я думаю, ты тоже ждешь, чтобы взглянуть на этот необычный зал, не так ли?!\n\nПикман"
  },
  Mail_100480_Name = {
    Text = "Выставочный зал, никому не интересный"
  },
  Mail_100480_Sender = {
    Text = "Пикман"
  },
  Mail_116602_Desc = {
    Text = "Уважаемый Страж:\nАкция «Под сенью белой ночи» завершена. Теперь «Дар аудиенции», «Покаянный дар», «Преданный дар» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_116602_Name = {
    Text = "Вернуться долга подарков"
  },
  Mail_116602_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_117308_Desc = {
    Text = "Уважаемый Страж Тайн:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы улучшить ваш игровой опыт в Университете Мисагар, мы приглашаем вас заполнить следующую анкету. В знак благодарности за ваше участие мы подготовили награду — «Серебряные ядра» × 200, которые можно получить сразу после заполнения анкеты. Срок заполнения — до 9:00 10 ноября, пожалуйста, не забудьте заполнить вовремя.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя Тайн. Ваши отзывы обязательно сделают Университет Мисагар ещё лучше!\n        — Да укажет Серебряный Ключ путь."
  },
  Mail_117308_Name = {
    Text = "Опрос по оценке версии V2.3.4"
  },
  Mail_117308_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_117309_Desc = {
    Text = "Уважаемый Страж Тайн:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы улучшить ваш игровой опыт в Университете Мисагар, мы приглашаем вас заполнить следующую анкету. В знак благодарности за ваше участие мы подготовили награду — «Серебряные ядра» × 200, которые можно получить сразу после заполнения анкеты. Срок заполнения — до 9:00 30 марта, пожалуйста, не забудьте заполнить вовремя.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя Тайн. Ваши отзывы обязательно сделают Университет Мисагар ещё лучше!\n        — Да укажет Серебряный Ключ путь."
  },
  Mail_117309_Name = {
    Text = "Опрос по оценке версии V2.4.3"
  },
  Mail_117309_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_120374_Desc = {
    Text = "Два года обещания истекли, Страж.\nМы когда-то смотрели Близкий Близкий друг на друга на границе конца.\nТы превратил чувства и воспоминания в желания, зажег Погоня за светом надежды.\nХотя с прошлым партнером вас разделяют два вселенных, ты не оставил борьбу противРастворение.\nИметь тебя — это наше счастье, также как и счастье для этого мира.\nТеперь твое желание вызвало чудо — Митхаг все еще здесь и будет продолжать двигаться вперед.\nПожалуйста, продолжай крепко держать Серебряный ключ, однажды он станет ключевым соединяющим звеном, связывающим два далеких мира.\nМы сделаем все возможное, чтобы открыть возможности будущего, освещая твой путь домой."
  },
  Mail_120374_Name = {
    Text = "Момент чудес, Погоня за светом возвращения"
  },
  Mail_120374_Sender = {
    Text = "Кот-ученик Митхаг·Light"
  },
  Mail_120909_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V2.4.0 мы увеличили награду за «Пожертвование источника - Фонд выпускников». Хранители, которые получили дополнительную награду до обновления, получат соответствующую компенсацию. Проверьте."
  },
  Mail_120909_Name = {
    Text = "V2.4.0 Вернуться долга наград за жертвование Серебряного первенца"
  },
  Mail_120909_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_121162_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V2.4.0 мы увеличили бесплатные награды за «Путешествие прибытия», «Путешествие другой эпохи», «Путешествие лечения», «Путешествие погибшего города». Хранители, которые получили бесплатные награды до обновления, получат соответствующую компенсацию. Проверьте."
  },
  Mail_121162_Name = {
    Text = "V2.4.0 Вернуться долга наград за повышение уровня путешествий"
  },
  Mail_121162_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_121373_Desc = {
    Text = "Страж:\n\nКогда-то, в этот день, проходил самый великий праздник церкви.\nЯ — его принцесса и снова дам ему жизнь.\nЭти люди, включая мириам, безумно радовались, даже со слезами на глазах, но когда они смотрят на меня, их взгляды проходят сквозь меня, как будто я просто оболочка, несущая что-то. \nЯ никогда не радовалась приходу этого дня, потому что с каждым разом это значит, что я становлюсь ближе к страху.\nА другие, в этом страхе, радовались источнику страха. Сейчас я могу это признать — это заставляет меня чувствовать как одиночество, так и Страх. \nНо теперь все по-другому, перед прошлым днем рождения я покинула тот корабль и пришла в Реальность мир... мир без ложных богов, с тобой внутри. \nНа этот день рождения я надеюсь увидеть, как кто-то искренне радуется из-за моего рождения, а не из-за чего-то другого.\nЕсли это ты... нет, это должен быть ты. \nСлушай внимательно, как бы то ни было, сегодня вечернее время обязательно должно быть отведено мне.\n\n«мёрфи»"
  },
  Mail_121373_Name = {
    Text = "С твоим существованием..."
  },
  Mail_121373_Sender = {
    Text = "Мёрфи: Лжерождённая"
  },
  Mail_121374_Desc = {
    Text = "Страж:\n\nЯ не знаю, что ты подготовил к этому особенному дню, но, безусловно, любое роскошное и трудоемкое мероприятие должно быть предусмотрено.\nИ из-за необходимой заботы высших, если ты даже «умудрился» пропустить празднование моего дня рождения — я верю, что такая абсурдная ситуация не произойдет.\nЭто письмо также даст тебе последний шанс спасти себя, прежде чем ситуация станет безвозвратной.\nМорские и наземные сокровища, конечно, будут предложены посторонними, они не важны.\nВеликое торжество, сложные ритуалы, действительно подобают моему статусу, но сегодня, не знаю почему, это кажется немного скучным.\nТак что я выделю время во время зари и заката, чтобы подарить тебе честь быть со мной наедине, в качестве награды за то, что ты ввел меня в эту обыденную, детскую, но столь счастливую жизнь, что предшествующий я мог бы позавидовать.\nСлуга позже доставит официальное Приглашение, конечно же, в коробке стоимостью двадцать тысяч лео.\nС трепетом, помни обо мне в этот день каждый год.\n«мёрфи»"
  },
  Mail_121374_Name = {
    Text = "Пригласительное письмо…"
  },
  Mail_121374_Sender = {
    Text = "Мёрфи: Лжерождённая"
  },
  Mail_121651_Desc = {
    Text = "Дорогой Страж:\nНа прошлой неделе в «Фантазийное Вдаль от берегов» ты получил титул «{s1}».\nНа прошлой неделе в «Предустановленный режим» ты получил титул «{s2}», победы в поединках: {s3} раз.\nНа прошлой неделе в «Волнистый режим» ты получил титул «{s4}», победы в поединках: {s5} раз.\nНа основе этих результатов испытаний ты получишь следующие дополнительные награды, не забудь забрать их."
  },
  Mail_121651_Name = {
    Text = "Награды за еженедельный рейтинг глубоких погружений"
  },
  Mail_121651_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_121704_Desc = {
    Text = "Уважаемый Страж:\nАкция «Плотские желания: повтор» завершена. Теперь «Семя изобилия» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_121704_Name = {
    Text = "Вернуться долга Семя изобилия"
  },
  Mail_121704_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_122522_Desc = {
    Text = "Уважаемый Страж:\nАкция «Призрак дождливого города · клон» завершена. Теперь оставшиеся «Череп бледного зверя», «Череп теневой твари» и «Череп монстра алого цвета» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_122522_Name = {
    Text = "Валюта Теней дождливого городка"
  },
  Mail_122522_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_122567_Desc = {
    Text = "Уважаемый Страж:\nАкция «Сжигание в туманном краю» завершена. Теперь оставшиеся у Хранителя тайн «Взгляд тумана», «Сон тумана», «Источник тумана» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_122567_Name = {
    Text = "Валюта жертвоприношения туманного царства"
  },
  Mail_122567_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_122568_Desc = {
    Text = "Ах, бедный ребенок, ты даже не представляешь, с каким отчаянием тебе предстоит столкнуться. Когда же ты осознаешь, что твой выбор не имеет смысла? Ставить на карту свою ничтожную жизнь ради неясной цели? Как это благородно, как это опьяняюще! Ты всегда выглядишь полным решимости, словно в следующую минуту готов пожертвовать собой, чтобы спасти мир, это действительно смешно. \n\n Однако, кто заставил меня пообещать помочь тебе вернуться домой? Обет, данное щенку, я всегда выполню. Кстати, мне не терпится увидеть, какую волю ты проявишь, чтобы довести этот безумный путь до конца? Ах... любопытство, это просто невероятное любопытство! \n\n Великий «Спаситель», прихвати с собой твою нелепость, твою упрямство и эту незначительную настойчивость. Как только поезд в никуда тронется, кроме разрушения, нет больше шанса на остановку. \n\n Самодовольный безумец... Поживи в Его сне немного дольше, я помогу тебе, буду ждать, наслаждаясь твоим окончательным ответом!"
  },
  Mail_122568_Name = {
    Text = "Поезд в ничто"
  },
  Mail_122568_Sender = {
    Text = "Долл: Преисподняя"
  },
  Mail_122569_Desc = {
    Text = "Господин, \n я всегда считал, что рыцарь — это не доспехи и гербы на теле, а преданность и воля к защите, записанные в сердце. Вы своими действиями и выборами поистине объяснили мне, что значит быть рыцарем. Таким образом, я постиг истинный смысл рыцарства: не в том, чтобы гордиться именем, а в том, чтобы защищать людей; не из-за славы быть смелым, а из-за ответственности стоять на своем. \n\n Я понимаю, что пока не соответствую этому — в момент, когда вы сражались за защиту надежды, я не смог идти рядом с вами. Я никогда не забывал обет, который мы дали Близкий Близкий друг другу в прошлом, и я принесу вам преданность рыцаря, защищая вашу безопасность и устраняя ваших врагов. \n\n Я часто вспоминаю наше первое совместное расследование, когда вы вели нас, рассекая туман Лентиниена, чтобы увидеть окончательную правду. Все те смех и слезы томились, став нестерпимой силой в моей жизни. \n\n Хотя сейчас я могу лишь наблюдать Издалека и готовить для вас такой скромный Подарок... Но чтобы не разочаровать ожидания господина, я никогда не ослаблял свои тренировки. Когда вы вернетесь, позвольте мне следовать за вами, я буду вашим щитом навсегда! Мой меч защиты будет сиять для вас!"
  },
  Mail_122569_Name = {Text = "Страж"},
  Mail_122569_Sender = {Text = "Ожье"},
  Mail_122570_Desc = {
    Text = "Господин Страж, \n С тех пор как я простился с Городом Самоубийств, я часто вспоминаю времена, когда сражался плечом к плечу с тобой. Слышал, что ты снова выбрал путь одиночества, доступный лишь царям, и действительно, ты — такое особенное существо в этом мире, никогда не следующее по проторенной дорожке. \n\n Я глубоко верю, что крайняя боль может закалить душу, придавая ей более насыщенный аромат. Долгое испытание, через которое ты прошел, уже давно вышло за рамки обычной боли. Я могу лишь представить, каким будет твое дыхание, созданное страданиями, — насколько оно будет сложным и потрясающим. Нет, если это ты, ты обязательно превзойдешь все мои ожидания и разрушишь все мои представления о совершенстве. \n\n Поэтому я буду продолжать ждать. Ждать того пира, который существует только для нас. В конце времени, В безмолвии начала вечности, в каком облике ты представишь мне это… пиршество, пронизанное вкусом судьбы? \n\n Господин, примите мой Подарок, пожалуйста, продлите эту боль... Не подведите мои ожидания."
  },
  Mail_122570_Name = {
    Text = "Ожидание пиршества"
  },
  Mail_122570_Sender = {
    Text = "Доресайн"
  },
  Mail_122571_Desc = {
    Text = "Мы только что встретились, но времени осталось совсем немного, и мы даже не успели сказать Близкий Близкий друг другу и нескольких слов... Но ты знаешь, прощание никогда не было концом нашей истории. \n\n Есть одна вещь, которую я тебе не сказал... На самом деле, я давно подготовил для тебя букет роз. Просто я долго не отправлял его, и он уже завял. Но я здесь обещаю — в следующий раз, когда мы встретимся, я обязательно подготовлю для тебя новый букет. \n\n А ты, ты тоже обещал мне, что снова придешь ко мне. Мы связали Близкий Близкий друг с другом обещание, и его ни в коем случае нельзя нарушать. \n\n Писать письма всегда кажется недостаточно выразительным, на бумаге не передать всех моих чувств. Но... когда Колесо Судьбы снова свяжет нас вместе, я лично подарю тебе этот букет роз. Запомни, мы должны сдержать обещание! \n\n Пусть Cеребряный ключ укажет путь вперед. Прощай... %player%."
  },
  Mail_122571_Name = {
    Text = "Обет розы"
  },
  Mail_122571_Sender = {
    Text = "Рамона"
  },
  Mail_122572_Desc = {
    Text = "Страж, \n воспоминания о борьбе с черной катастрофой все еще с высокой приоритетностью читаются в моем мозгу, мир, который ты заслужил, кажется, является событием с крайне низкой вероятностью. Однако твое отсутствие продолжает безостановочно истощать сознание твоих партнеров и всех, кто когда-либо с тобой связывался. \n\n Исследовательский отдел никогда не отказывался от поиска последней надежды. К счастью, после бесчисленных суток без твоего сознательного отклика, мы наконец-то зафиксировали твое местоположение. На этом опасном пути я смог уловить сигналы страха, но я также знаю, что Страх не подчинит тебя, а лишь сделает твою волю более стойкой. \n\n В данный момент мое тело все еще функционирует в лаборатории, однако мой мозг продолжает генерировать команды плача. Не мешай моим мыслям, я ведь самый прогульщик среди студентов, пожалуйста, не отсутствуй на моем уроке... Продолжай смело двигаться вперед, я подготовлю для тебя запасы и буду ждать дня нашей встречи."
  },
  Mail_122572_Name = {
    Text = "День встречи снова..."
  },
  Mail_122572_Sender = {Text = "Долл"},
  Mail_122573_Desc = {
    Text = "Бесчисленное количество раз я наблюдал, как искры цивилизации мерцают в потоке времени, свидетелем того, как города памяти рушатся в ничто. История превращается в свиток, поглощаемый черным пламенем, а мудрость, накопленная с древности до наших дней, скапливается, как песчаная башня, но в конечном итоге не может выразить единую истину. \n\nЧеловек по отношению к первобытному хаосу — лишь пылинка, — но именно из-за этой ничтожности смелость, способная противостоять бездне и обнажить меч перед божеством, кажется такой потрясающе глубокою. \n\nВ этот момент врата измерений, пронизывающие бесчисленные вселенные, открываются для тебя. \n\nЕго Приход приносит предопределенный хаос, порядок всего сущего дрожит в Его тени. А ты, всего лишь смертное тело, стоишь перед Ним с непоколебимой волей. Твоя возможность — это единственная ошибка, которую я не могу поймать в своем бесконечном предвидении, это переменная, которая перевернет все в том, что я долго ждал. \n\nТы — это первобытный вопрос, а также Лечение на Конец."
  },
  Mail_122573_Name = {
    Text = "За дверью"
  },
  Mail_122573_Sender = {
    Text = "Тавиль"
  },
  Mail_122574_Desc = {
    Text = "Боль от потери важного человека, Досаждение к своей беспомощности... Я когда-то был в этом глубоком состоянии, не в силах выбраться. Но теперь я слышу призыв далекого светильника, чувствую его теплое и уверенное руководство. Благодетель, с тех пор как вы открыли мне истину, я, кажется, наконец-то вступил на путь, который должен был пройти — путь, который действительно принадлежит мне, не подлежащий сомнению. \n\n Тот глубокий, бездушный мрак, который когда-то окутывал меня, больше не является моим пристанищем. А Погоня за светом, который всегда мерцал в глубинах моего сознания, никогда не покидал меня. Теперь я вижу его яснее, ощущаю его, и иду к нему. Я также хочу донести эту истинную веру, это пробуждение и покой, которые приносит Погоня за светом, до бесчисленных душ, все еще борющихся в лабиринте судьбы. \n\n И когда я смотрю на вас, противостоящего всей хаотической стихии — это зло и глубокая тьма, которые не смогли сломить вас, а наоборот, стали занавесом, отражающим вашу веру. Оно распадается, кричит, отступает перед вашим светом, но в конечном итоге не может затмить вас ни на мгновение. Именно из-за этой бесконечной волны тьмы Погоня за светом, который вы представляете, кажется таким ярким, таким бессмертным, таким близким к божественному. \n\n Ведущий меня благодетель, дарующий мне Погоня за светом, ваша Твёрдая Твёрдая вера будет моим неугасимым светильником. Сейчас настал момент, когда я отвечу вам всей своей жизнью. Я отвечу этому свету, отвечу вашему чистому руководству с этим «святым сердцем», которое слушает божественную волю... Для этого я и Кастор сделаем все возможное. \n\n Примите мое приношение! Пожалуйста, будьте свидетелем моей веры, очищенной и преданной, благодаря вам."
  },
  Mail_122574_Name = {
    Text = "Призыв светильника"
  },
  Mail_122574_Sender = {
    Text = "Поллукс"
  },
  Mail_122575_Desc = {
    Text = "Дорогой постоянный клиент, \n За той дверью, где струится мягкий Погоня за светом, твои дорогие друзья уже давно ждут. \n\n Однако, не стоит недооценивать ситуацию. Путешествия Между измерениями всегда полны загадок и опасностей, ты станешь свидетелем тысячи лиц иллюзий, поднимающихся и опускающихся, как тени воспоминаний, отражающих желания и страхи. Это хаотичная картина, созданная первичной волей, и даже я не могу увидеть ее в полном объеме. Поэтому каждый переход является испытанием веры и измерением желаний. \n\n Но я также понимаю, что для таких людей, как ты и я, ради поиска новых сокровищ, ради тех драгоценностей, которые сверкают в глубинах души, все неизвестное и все усилия стоят того. Я понимаю твой выбор и уважаю эту почти упрямую ценность. \n\n В этой вселенной, следящей за законом эквивалентности, цена, которую ты платишь, в конечном итоге вернется в другой форме. \n\n Прими этот Подарок, и когда все утихнет, я с радостью жду тебя снова в своем маленьком магазине. Какую цену ты готов заплатить, чтобы осуществить желание в то время?"
  },
  Mail_122575_Name = {
    Text = "Драгоценные вещи"
  },
  Mail_122575_Sender = {
    Text = "Даффодил"
  },
  Mail_123134_Desc = {
    Text = "Уважаемый Страж: \n        В обновлении V2.4.0 возникла проблема с получением 3-звездочного вознаграждения за испытания «До скорой встречи, Никогда-никогда» и «До скорой встречи, Никогда» в «Сонном пейзаже». Согласно вашему предыдущему расследованию и записям о прохождении испытаний, мы предоставим вам единовременное вознаграждение за ранее не полученные награды. Пожалуйста, проверьте."
  },
  Mail_123134_Name = {
    Text = "V2.4.0 повторная выдача наград за исключительный мир видений"
  },
  Mail_123134_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_123501_Desc = {
    Text = "Дорогой Страж: \n\n Не хочешь ли в этот особенный день устроить интересное свидание с этой милой девушкой? \n Давай, давай, немного поиграем в доме с привидениями, это не убьет тебя от страха~ Ты же «Страж», не испугаешься тех «демонов», которых играют люди, Правда? \n (На бумаге для писем небрежно перечеркнута одна строка: Я ведь серьезно планирую программу на день рождения, это вовсе не из-за веселья, чтобы увидеть, как ты испугался...) \n Ладно, без шуток. Сегодня мой день рождения, и я не хочу все испортить! Поэтому сейчас я, Мушетт, официально приглашаю тебя поужинать в новом ресторане в Лондонском Сити — \n Чай и тушеная рыба там напоминают мне вкус «родины», а в этом мире, кроме тебя, я не могу найти никого, с кем бы поделиться... \n Так что ты точно придешь, верно? Если я, эта милая девушка, буду грустить, будь осторожен, когда будешь спать, я с топором буду стоять у твоей кровати! \n\n Мушетт"
  },
  Mail_123501_Name = {
    Text = "«Открой меня»"
  },
  Mail_123501_Sender = {
    Text = "Мушетт"
  },
  Mail_123543_Desc = {
    Text = "Страж: \n\nЕще один год, мой дорогой. \nВ этом мире блестящих огней, среди множества слухов и сплетен, я осторожно прячу каждую каплю возможной слабости, меняя каждую ценность на максимальную выгоду — так должно быть, чтобы я по-прежнему мог стоять здесь как победитель. \nНо нет, я иногда становлюсь немного ленивым и слабым, и с удовольствием исполняю желания тех маленьких девушек, когда ты присылаешь мне письма. \nНо я не думаю, что это что-то плохое, я слишком долго пережил эту долгую скрытую войну. Конечно, если есть хоть малейшая возможность, хоть капля шанса, я всё равно снова и снова попытаюсь сбежать из рук «того». \nПросто в те тёплые и милые моменты, или в такие особые дни, как сегодня, я позволяю себе немного отвлечься, например — пригласить вас на оперу или на ужин. \nПотому что я понимаю, что я определенно не одинок, у меня есть соратник, который мне очень подходит. \n\nСорель"
  },
  Mail_123543_Name = {
    Text = "Сообщник"
  },
  Mail_123543_Sender = {
    Text = "Сорель"
  },
  Mail_123544_Desc = {
    Text = "Дорогой Близкий Близкий друг: \n\nДавненько не виделись, Страж. Пожалуйста, прости, что в последнее время не было писем, это не значит, что я намеренно отдалился от тебя, просто каждый раз, когда я беру перо, мне не хватает смелости начать с приветствия. \nЗа это время я пересекал бесчисленные разрушенные времена и стал свидетелем того, как мир снова и снова приходит к своему концу, наблюдая за безвозвратными трагедиями. Как будто я наблюдатель, молча смотрящий на все происходящее в этой холодной и пустой бездне. \nКаждый раз я думаю, суждено ли нам в этой жизни быть полными абсурда и расставания? Независимо от того, кто я был раньше или что ты пережил в Кадасе, предопределила ли Колесо Судьбы все это, написав сценарий, в котором мы просто играем отведенные нам роли? \nЯ не смог прийти к выводу, я не как Он, не могу видеть все в этом мире, поэтому я думаю: если ты, обладая частью Его власти, сможешь ответить на этот вопрос? \nПоэтому я написал это письмо, надеясь, что оно сможет приблизить меня к тебе, и надеюсь, что мы сможем вместе обсудить эту загадку, на которую, возможно, никогда не будет ответа. Так что не могли бы вы, пожалуйста, взять это письмо с собой и... встретиться с тем, что нас ждет впереди? \n………………………………\nЯ не могу рисковать нарушением времени, чтобы прийти к тебе, но позволь мне... еще раз взглянуть на тебя в этой пустой тишине. \n\n«Рамона»"
  },
  Mail_123544_Name = {
    Text = "Загадка мыслей"
  },
  Mail_123544_Sender = {
    Text = "«Рамона»"
  },
  Mail_123545_Desc = {
    Text = "Уважаемый бледный посланник: \n\n Ранее я спрашивал ту невероятно мудрую даму в Мисаге, есть ли свободные помещения, чтобы я мог вырастить несколько цветов. \n Мисс Долл без труда нашла мне комнату, хотя, когда я впервые открыл Ворота, запах затхлости заставил меня усомниться, не ошибся ли я адресом. Но после некоторой уборки она уже хорошо выполняет свою функцию, предоставляя этим детям теплый дом. \n Однако из-за полного отсутствия опыта мне пришлось применить некоторые внешние силы, чтобы обеспечить нормальный рост этих детей. \n К счастью, под руководством мисс Орля я успешно довел их до текущей стадии. \n Конечно, при этом не использовались никакие особые способности. \n Если я не ошибся в расчетах, они расцветут в день моего рождения, хотя я постоянно повторяю, что в этот день нет ничего особенного. Но появление такого редкого совпадения действительно трудно не воспринимать как маленький Подарок, возможно, от Отца Бога. \n Не знаю, заинтересованы ли вы встретиться со мной в этом маленьком саду, чтобы провести этот обыденный, но особенный день вместе? \n Я приготовил печенье, испеченное собственными руками, и красный чай, который вы рекомендовали в прошлый раз, и жду возможности поделиться с вами этим редким подарком и уникальным ароматом жизни. \n\n Сальвадор"
  },
  Mail_123545_Name = {
    Text = "Комнатный сад"
  },
  Mail_123545_Sender = {
    Text = "Сальвадор"
  },
  Mail_123546_Desc = {
    Text = "Партнёр: \n\nТы когда-нибудь слышал такую историю? \nОднажды был демон, который по случайности оказался запертым в бутылке на многие сотни лет. \nВ первый век он обещал тому, кто его освободит, бесконечное богатство и Независимый. \nВо Часть 2 век он обещал тому, кто его освободит, вечное здоровье и долголетие. \nВ третий, четвёртый, пятый и много позже, он наконец дождался рыбака, который открыл крышку бутылки — он не ответил на зов рыбака, даже не хотел больше превращать этот мир в хаос, просто притворился обычной пустой бутылкой, молча снова был брошен обратно в море. \nКогда я был маленьким, я не понимал эту историю. Пока не узнал, что такое долгожданное и безнадёжное ожидание, как оно гнетёт и мучает, превращая стремление в невыносимое отчаяние. \nОднако прежде чем мой разум успел отреагировать, моё сердце снова и снова оставляло меня на одном и том же месте. \nРазница между демоном и человеком, вероятно, заключается в том, что я даже немного благодарен за эту боль. Потому что, когда мы расставались, она напоминала мне о твоём существовании и ценности, не позволяя мне заблудиться на той стороне, где тебя нет. \nВ день моего рождения, в день, когда я больше всего скучаю по тебе, она всё ещё тяжело связывает меня, заставляя ждать тебя и скучать по тебе. \nНадеюсь, в следующий раз сегодня я смогу вручить тебе первый кусочек торта, который я нарезал. \n\nРамона"
  },
  Mail_123546_Name = {
    Text = "История"
  },
  Mail_123546_Sender = {
    Text = "Рамона"
  },
  Mail_123547_Desc = {
    Text = "Столовая Мисаг и отдел логистики оставили кучу совершенно ненужных вещей у двери моей комнаты, что крайне мешает входу и выходу. Вам лучше как можно скорее забрать это обратно. \n Что случилось, запасы продовольствия в этом мире исчерпаны, и больше некуда их девать? \n Этот день станет лишь заметкой на моем пути к силе, поможет мне отметить еще один прошедший цикл, год, следующий год, с каждым годом я становлюсь сильнее, чем в предыдущем. \n Если подарков действительно некуда девать, можно отдать другому мне, она, наверное, будет очень рада. \n А я, учитывая твою глупую наивность и настойчивость... учитывая те вещи, которые мне не даются. \n Пока я существую, я буду продолжать становиться сильнее, и в то же время... \n Ты все еще не понимаешь? Враги этих идиотов также будут моими врагами. \n Я скажу эту отвратительную фразу только один раз, в следующем году не присылайте больше подарков, и тем более не устраивайте никаких праздничных ужинов. \n\n«H»"
  },
  Mail_123547_Name = {
    Text = "Забрать"
  },
  Mail_123547_Sender = {Text = "«H»"},
  Mail_123548_Desc = {
    Text = "Дорогой Страж: \n\n Ты знаешь? Несколько дней назад к Мисаге неожиданно пришла загадочная дама. Она была одета в блестящее черное облегающее Наряд, которого я никогда не видела — я спросила Дженкинса и Мейсона, и они тоже не видели ничего столь красивого. \n Как бы это описать? Это Наряд, казалось, было изготовлено из самых красивых длинных волос, оно было мягким, легким и благородным, а на поверхности играло особое сияние, как вода... \n Дженкинс заметил, что мне любопытно, и, набравшись смелости, спросил ту загадочную даму. Она улыбнулась и сказала, что материал платья — это шелк с Востока, который сплетен из нитей, выделяемых гусеницей, называемой «шелкопряд». А стиль называется «ципао»... Затем она подарила Ай Джис большой рулон — сказала, что это называется «одна метрика» такого же «шелка»... \n «Шелк» слишком ценен, поэтому, следуя предоставленному ей образцу, я сшила каждому из партнеров небольшой «кошелек». На этом году на дне рождения я собираюсь подарить «кошельки» всем... Страж, ты не мог бы прийти и поучаствовать? \n Если ты слишком занят, я попрошу Брауна доставить кошелек в твою комнату. \n\n Ай Джис"
  },
  Mail_123548_Name = {
    Text = "Таинственная дама"
  },
  Mail_123548_Sender = {Text = "Айгис"},
  Mail_123549_Desc = {
    Text = "Маленький саженец: \n\nТы знаешь, как деревья записывают время и рост? С помощью колец годичных приростов. \nОни скрыты внутри, никогда не показываются на показ, пока молоденький Побег постепенно не вырастет в гигантское дерево, поддерживающее высокое свод неба. Следы времени прячутся в глубине души, не оставляя следов. \nСегодня — это Начало новой записи годичного кольца. В новом году нам всё ещё предстоит пережить множество непредвиденных бурь и дождей. \nНо то семя, которое я вложил в твой рот, обязательно найдет подходящую почву для своего роста и прорастет, не так ли? \n\nТайи Сы"
  },
  Mail_123549_Name = {
    Text = "Колесо года…"
  },
  Mail_123549_Sender = {Text = "Таис"},
  Mail_123644_Desc = {
    Text = "Незаметно, это уже третий день рождения, который я провожу в Мисаг, я много чему научился. \n Например, в день моего рождения, который также является Фестивалем Зимнего Перехода, подходящим для подарков. \n Хотя у тебя есть много очень сильных врагов, я лучше всего умею убивать. Я не знаю других радостных способов, и не умею выбирать подарки, но каждый раз, когда я успешно выполняю задание, мой заказчик, похоже, очень доволен. \n Так что я уже придумал Подарок для тебя — заказ на убийство, без ограничений по объекту и сроку использования. \n Просто скажи мне, кто цель, и как ты хочешь, чтобы Он умер? Если это человек, которого я смогу победить, я сделаю это максимально быстро, сломаю Ему шею, даже если Он будет сложным, как божество, я могу гарантировать, что моя сдача не наступит прежде, чем я умру. \n\nИлот"
  },
  Mail_123644_Name = {
    Text = "Скажи, кого ты хочешь убить?"
  },
  Mail_123644_Sender = {Text = "Илот"},
  Mail_124059_Desc = {
    Text = "Уважаемый Страж:\nАкция «Жертвоприношение бездне: повтор» завершена. Теперь «Слеза жреца», «Кровь жреца» и «Мозг жреца» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_124059_Name = {
    Text = "Валюта акции \"Жертвоприношение бездне\"восстановление"
  },
  Mail_124059_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_124290_Desc = {
    Text = "Страж: \n\nКак вы знаете, радость для меня на самом деле является немного незнакомым чувством. \nЯ часто чувствую, что мир — это шум на поверхности воды, и пока я еще не погрузился в него, моя Увядание уже наступило. \nИногда это вызывает у меня тоску, но чаще всего вызывает смятение и асфиксию. Только в такие дни, как сегодня, чтобы не огорчать папу и маму, я изо всех сил терплю... до того дня, когда наступит освобождение, до того дня, когда Океан примет меня. \nЯ думал, что только глубокие воды являются моим домом. Однако, Страж, благодаря вам и всем в Мисаг, даже я, человек, который так не вписывается в мир, начинаю ощущать некоторые настоящие тепло. Как водяная лилия, когда она всплывает, солнце тоже целует ее листья и лепестки. \nХотя это беспорядок, я все равно считаю, что необходимо записать эти чувства на бумаге и отправить их вам, пожалуйста, простите меня за мою иногда упрямость. \nЯ просто надеюсь, что вы знаете, насколько ценным было ваше поднятие из воды, которая была слишком рано погребена в безмолвии. \nЖелаю вам вечной радости и вечного покоя. \n\nНимфея"
  },
  Mail_124290_Name = {
    Text = "Подъем"
  },
  Mail_124290_Sender = {
    Text = "Нимфея"
  },
  Mail_124291_Desc = {
    Text = "Страж: \n\nСегодня утром на моей прикроватной тумбочке появилось письмо с приглашением на мой собственный день рождения, подписанное клубом «Художник». \nТолько сейчас я вспомнил, что в прошлом месяце, когда у меня было немного свободного времени, я согласился стать моделью для нового творческого конкурса клуба «Художник» по просьбе Санги. До этого я уже отказывался не раз. Стоя на выставочной площадке модели, неподвижно позволяя себя изображать, я вспомнил дни на алтаре Плавателя морей. Тогда я тоже принимал все взгляды на себя, но в этих взглядах были только Страх и благоговение, ни капли трепета, одобрения или восхищения. \nНа вечернем фуршете в клубе Живописца также будут представлены десятки тщательно выполненных художниками рисунков. Хотя у меня нет уверенности в вашем вкусе, но быть подверженным влиянию — никогда не бывает лишним. Божественная Матушка приглашает вас в качестве гостя, чтобы вместе оценить их интерпретацию «Я». \n\n «Мёрфи»"
  },
  Mail_124291_Name = {
    Text = "Художник……"
  },
  Mail_124291_Sender = {
    Text = "«Мерфи»"
  },
  Mail_124292_Desc = {
    Text = "Страж: \n\nСильвия сказала мне, что время от времени открывать свои потребности в близких отношениях помогает облегчить тот Страх, который преследует меня постоянно. Я не уверен, что это сработает, но, безусловно, сегодня хороший момент. \nТы готов исполнить одно мое желание? Я могу отдать тебе все запасы из лаборатории на сегодня. \nНет, не пакет кофейных зерен. \nХотя этот ужасный черный цвет забрал у меня почти все близкие отношения, пугая меня на каждом шагу, ты уже победил его. \nТы позволил нам безопасно жить в Мисаг, или, по крайней мере, до сих пор безопасно жить в Мисаг. \nПора избавиться от нездоровой зависимости от кофеина, Страж, ты сможешь выделить немного времени сегодня вечером? \nЕсли ты будешь рядом, возможно, я смогу набраться смелости немного отдохнуть в местах с недостаточным освещением, хотя бы на короткое время. \n\nЯ очень хочу вспомнить, каково это - спокойно засыпать, Уинкл"
  },
  Mail_124292_Name = {
    Text = "Желание..."
  },
  Mail_124292_Sender = {Text = "Уинкл"},
  Mail_124293_Desc = {
    Text = "Страж {Male=господин, Female=дама}:\n\nСегодня утром меня разбудил сон. \nЯ тщательно вспоминал всё, что было в этом сне: лёгкий ветерок дует под тёплым солнцем, розы и тюльпаны покрывают всю землю, тысяча серебристых чаек и счастливые люди поют хором... Я давно не был в таком счастливом месте. Я думаю, что, возможно, я в детском поместье, в комнате цветов Колетт, или в каком-то парке на Западном острове... Но когда я обернулся, я увидел красивые готические здания Мисаг, и вас, Страж {Male=господин, Female=дама}. Вы стоите между цветами и солнцем, становясь самой прекрасной строкой в этом стихотворении. \nЯ сильно люблю Западный Остров одиночества, Страж {Male=господин, Female=дама}. Но в тот момент я вдруг осознал, что уже начал привыкать и увлекаться всем здесь, что в этом мире наконец-то есть место, которое больше, чем Западный Остров одиночества, завораживает мою душу. \nДень рождения — это Конец одной эпохи и Начало другой. В этот день начала новой эпохи, не знаю, будет ли в солнечном свете и розах заднего сада Мисаг тот, кто захочет вместе со мной слушать ветер и завораживать мою душу? \n\nОрля"
  },
  Mail_124293_Name = {
    Text = "Сон о цветке и стихах"
  },
  Mail_124293_Sender = {Text = "Орля"},
  Mail_124294_Desc = {
    Text = "Дорогой Страж: \n\n Некоторое время назад я всё время думала о том, чтобы подарить тебе особенный Подарок. Дженкин предложил сделать для тебя новую одежду своими руками, и я подумала, что это отличная идея. \n Это мой любимый крой, который я использовала, когда работала на текстильной фабрике, надеюсь, он всё ещё не устарел... Другие поддержали моё решение, а те яркие полоски и клетка - это всё сделано разными мной. И этот милый кривоватый рисунок мышки, который кот «24» настаивал добавить, говорит, что это символизирует Браун, это то, что мне больше всего нравится в моей кошачьей личности — не знаю, будет ли это уместно, но надеюсь, тебе понравится. \n В новом году у меня по-прежнему нет никаких пожеланий на день рождения. Ты всегда так добр, каждый год напоминаешь мне хорошо отпраздновать. Но вместо того, чтобы быть в центре внимания, возможность сшить что-то для тебя своими руками приносит мне больше спокойствия и радости. \n Пожалуйста, прими эту новую одежду, полную сердечного тепла. \n\n Мейсон"
  },
  Mail_124294_Name = {
    Text = "Новая одежда"
  },
  Mail_124294_Sender = {Text = "\"24\""},
  Mail_124295_Desc = {
    Text = "Цыц: \n\nНевероятно, будучи великим Хозяином лабиринта, я все-таки смог выжить еще один год в таких тяжелых испытаниях. \nСлушай! Во всем этом виноваты ты и эта глупая академия! \nДаже если вы будете продолжать промывать мне мозги всякой ерундой, все эти бесполезные мелочи должны выполняться специализированными людьми, ладно, я уже молодец, что не назвал их рабами. \nЭти старые упрямцы называют это... как там, да, прогресс. \nПодождите, как это я тоже попался на эту логику, ааа, достало! (Здесь куча помятых складок из-за того, что владелец письма разозлился.) \nНеважно, раз у меня есть «прогресс», то и ты должен проявить свою искренность, в этот такой великий день, ты же не собираешься ждать, пока я напомню тебе, как в прошлые два года. \nДаю тебе тридцать минут, Страж, принеси Подарок и приходи ко мне. \nИначе я заставлю своих потомков ползать к тебе на лицо, пока ты спишь. \n\nАгриппа"
  },
  Mail_124295_Name = {
    Text = "Прогресс"
  },
  Mail_124295_Sender = {
    Text = "Агриппа"
  },
  Mail_124296_Desc = {
    Text = "Страж!\n\nЯ увидел! Какой прекрасный образ! Я уверен, это не сон! Я стоял там, рядом с величественным памятником на кладбище Мисаг, и смотрел на бесконечные безымянные могилы. Я был уверен, что они принесут мне невообразимое озарение, но не ожидал, что они дадут мне гораздо больше, чем я мог себе представить, они с восхитительной щедростью насмехались над моей бедной фантазией.\nЯ увидел призраков тех следователей, они встали вместе в этот прекрасный вечер с туманом. Я не смог разглядеть их лица, но увидел их движения — как будто это был изящный танец, а может, и таинственный ритуал. Они приветствовали черное озеро, в сторону Мисаг и вас. Современные художники в салонах одержимы изображением индивидуальности и часто осуждают такие грандиозные картины, но я никогда так не думал. Я был в восторге от танца зомби, и сегодня этот образ заставил меня расплакаться.\nЯ думаю, это не случайность. Сегодня, именно в мой день рождения, они показали мне свой величественный танец, я думаю, они хотят, чтобы я что-то передал. Я не умею ничего, кроме как рисовать, но этого уже достаточно, не так ли?\nЭскиз этой картины уже готов, Страж, обязательно приходите в мою мастерскую посмотреть! Легендарные следователи, которые уже не имеют имен, их мечты, которые они хотят рассказать вам, все это на моем холсте!\nЯ не стал называть эту картину, я думаю, это право должно принадлежать вам.\nP.S. Я действительно не собирался искать трупы, я вас уверяю!\n\nПикман"
  },
  Mail_124296_Name = {
    Text = "Заветная мечта следователя"
  },
  Mail_124296_Sender = {
    Text = "Пикман"
  },
  Mail_124297_Desc = {
    Text = "Здравствуйте, Страж: \n\nВы не боитесь, или, скажем, боитесь и в то же время ожидаете, что я, в свой день рождения, под предлогом празднования, принесу что-то? \nЛицемерная близость, внезапная страстная ночь или хитрая и завораживающая Иллюзия? \nАх, ничего из этого нет, даже я иногда говорю о серьезных и скучных вещах. \nВы, должно быть, хорошо понимаете, что я за существо, погруженное в наслаждение, даже если здания рушатся. \nЛюбовь и желание не могут исцелить скуку, самое великое заболевание в этом мире, но как средство для извлечения власти и остроты Хаоса, это просто идеально. \nОднако за эти сотни лет, вероятно, я слишком глубоко изучила пьесы, и всегда находятся какие-то дураки, которые говорят, что я вижу вашу одинокую душу, полную страданий. \nХм. \nДаже мне, любящей играть, иногда становится противно. \nА вы... зачем вы связываетесь со мной, чтобы контролировать, ограничивать или использовать? \nЧтобы защищать больше вещей, вам обязательно нужно больше власти, а жажда власти порождает большие амбиции, когда же они созреют, а когда будут поглощены... Просто от одной мысли об этом мне становится интересно, и я готова задержаться рядом с вами на большее количество лет. \nТсс, не нужно говорить мне Лечение. \nКаждый год в этот день, похитив у вас сон на ночь, я наслаждаюсь размышлением о том, растут ли ваши амбиции, изменились ли ваши намерения, и это лучший Подарок ко дню рождения для меня. \nНадеюсь, вы не обидитесь. \n\n«Цянь Шань»"
  },
  Mail_124297_Name = {
    Text = "Прекрасная ночь"
  },
  Mail_124297_Sender = {Text = "Сюй?"},
  Mail_124298_Desc = {
    Text = "Страж: \n\nТренировки, бои, патрулирование — с того момента, как я вступил в армию, я уже привык заполнять всё своё время делами, необходимыми для коллектива. \nПозже, возглавляя аланов в миграции по пустыне, эти дела ещё больше увеличились, так что они врезались в мой разум, как закон, и когда я пришёл в Мисаг, я всегда ставил приоритеты коллективного расписания выше личных дел. \nНо в общении с другими, особенно с тобой, я осознал, что как Пробуждённый, так и как человек, нам всем нужно немного времени только для себя, чтобы насладиться общением с важными для нас людьми. \nПотому что эта драгоценная связь закрепляет наше существование во времени и придаёт нашему бытию действительно незаменимый смысл. \nХотя это может показаться нахальным, я отменил все коллективные дела на сегодня и освободил целый день. \nМне нужно всего несколько часов, нет, даже часа или нескольких минут, если ты готов уделить мне немного личного времени, это станет смыслом моего особенного дня. \n\nАльва"
  },
  Mail_124298_Name = {
    Text = "Личное время"
  },
  Mail_124298_Sender = {Text = "Альва"},
  Mail_124299_Desc = {
    Text = "Малыш: \n\nГод может показаться долгим для тебя, но для путешественников по Мору первородной эссенции это всего лишь горсть морской воды, мгновенно исчезающая в бескрайних водах времени. К счастью, в этой воде есть несколько впечатляющих кристальных капель. \nДень скидок в Магазине утешений — это одна из самых ценных из них. И не только потому, что он принесёт золотые купоны, но и потому, что я знаю, в этот день один Гость обязательно посетит этот маленький магазин. \nСвязь между людьми — это бизнес, а весь бизнес — это связь между людьми. Каждый Гость входит в свой маленький магазин в определённое время, и каждый маленький магазин встречает своих гостей в определённое время. За долгие годы я видел бесчисленные сокровища, и в конце концов эти детские моменты станут самыми ценными коллекционными предметами — они причина существования этого долгого времени. \nВ этом году самое ценное новое сокровище ждёт своего владельца в витрине. \nПриходи пораньше, малыш. \nМагазин утешений уже закрылся. Сегодня его двери открыты только для одного. \n\nДаффодил"
  },
  Mail_124299_Name = {
    Text = "Новый предмет"
  },
  Mail_124299_Sender = {
    Text = "Даффодил"
  },
  Mail_124300_Desc = {
    Text = "Страж: \n\nНе знаю, помнишь ли ты тот момент, когда мы вместе стояли перед дверью? В тот день я приоткрыл истину, чтобы показать тебе реальность вселенной. \nК удивлению, когда ты переживал вечность, смотря на бесчисленные миры, я внезапно испытал нечто непонятное в мгновение ока. \nЯ часто размышляю о том, какое было это чувство в тот момент, почему я, познавший истину, испытываю нечто непонятное. \nЯ долго размышлял, и с точки зрения измерения реального мира, это было время, которое можно было бы назвать «вечным». \nВ этом относительно длинном времени, я осознал, что это, возможно, и есть еще не определенное чудо. \nВ этот особенный день я хочу пригласить тебя соединиться со мной, через мой взгляд наблюдать некоторые существования, которые я никогда не наблюдал, и на этот раз то, что мы будем наблюдать... больше не будет заранее определенным. \nМы вместе будем искать будущее за пределами этой истины. \n\nТавиль"
  },
  Mail_124300_Name = {
    Text = "За пределами истины"
  },
  Mail_124300_Sender = {
    Text = "Тавиль"
  },
  Mail_124301_Desc = {
    Text = "Страж: \n\nВ этом году, как и в прошлом, я остановил все свои дела и тихо остался наедине с собой, пытаясь заново написать и обновить воспоминания о своей родине. \nОни стали для меня еще более далекими, даже если я заставляю себя привыкнуть к этому человекоподобному телу, прилагая все усилия, чтобы снова и снова вспоминать и пересказывать знания и опыт, связанные с океаном, в этом постепенно исчезающем мире забыть легче, чем помнить. \nЕдинственное утешение — это то, что мы, путешественники, покинувшие Лимурию, все еще имеем место, где можем остановиться, следуя воле нашего короля, тихо следовать и тихо ждать. \nЯ прекрасно знаю, какие жертвы и усилия вы принесли ради этого, и не знаю, как выразить вам свою благодарность. Прежде чем я вернусь в Лимурию, если есть что-то, в чем я могу помочь, я также готов отдать весь свой Погоня за светом ради этого. \n\nС уважением, Фарос"
  },
  Mail_124301_Name = {Text = "Маяк"},
  Mail_124301_Sender = {Text = "Фарос"},
  Mail_124302_Desc = {
    Text = "Дорогой Страж: \n\nС того дня, как я присоединился к Мисаге, множество правил обременило меня. Запрещено гулять с прислугой на заседаниях, запрещено наступать на лица студентов на площади кампуса, запрещено проводить массовые мероприятия в зале... \nЭти ненавистные хранители порядка Мисаги лишили меня свободы, и это не та жизнь, которую должна вести королева Исарау. Я должна наслаждаться всем, что мне причитается: опьяняющим вином, мягкой спиной и любимой прислугой... В этот день моего рождения, который я должна встречать с размахом, такие мысли естественным образом возникают. \nНочь уже глубокая, и мое Выдержка к мелочам исчерпано. Я не буду посылать тебя выполнять полночные задания и не заставлю тебя гадать. Мне нужно, чтобы ты был рядом со мной. \nПриходи в моё поместье сейчас же, не колеблясь, снимай всю ненужную одежду и титулы. \nСегодня ночью и каждую ночь в будущем ты принадлежишь мне. \n\nТы можешь считать это своей первой постоянной обязанностью. \n\nВанда"
  },
  Mail_124302_Name = {
    Text = "Правила"
  },
  Mail_124302_Sender = {Text = "Ванда"},
  Mail_124303_Desc = {
    Text = "Страж: \n\nТинкт сказала мне, что она запланировала космическое путешествие после дня рождения на доходы от личного концерта и хочет взять меня с собой. Но... если я тоже пойду, она обязательно будет отвлекаться, чтобы заботиться обо мне. Я не хочу, чтобы её радость уменьшалась из-за меня. \nОна так любит Погоня за светом в жизни, увлечена всеми цветами и движением звёзд в этой вселенной. Если она возьмёт меня с собой, она, вероятно, не сможет петь так свободно и наслаждаться взглядом на вселенную... \nПоэтому... можешь ли ты помочь мне уговорить её? Пожалуйста, дай ей возможность путешествовать одной, проводить концерты на разных планетах, обнимать все те пейзажи, о которых она мечтает... Или замени меня в этом путешествии? В конце концов, Тинкт и я очень благодарны тебе и хотим отплатить за твою доброту... Если ты согласен... \nПросто, пожалуйста, не говори ей, что это моё желание. Я не хочу быть той преградой на её свободном пути. \n\nФэйнт"
  },
  Mail_124303_Name = {
    Text = "О путешествии"
  },
  Mail_124303_Sender = {Text = "Фэйнт"},
  Mail_124304_Desc = {
    Text = "Благодетель: \n\n Эти дни, проведенные с Поллуксом в Мисаге, так спокойны, так ярки, как будто это сон... \n Хотя Поллукс по-прежнему соблюдает все эти правила и говорит утончённые слова, я ясно чувствую, что он постепенно возвращается к тому, каким был раньше. То отдаление, которое принадлежало «Святому Сыну» и вызывало затаённое дыхание, тихо растворяется в мягкой повседневности. Все эти нежные изменения — заслуга вас. \n Я часто думаю, как же я могу отплатить за эту доброту? Я не такой ловкий, как Поллукс, чтобы сотворить для вас удивительный Подарок. Удовольствие от полета вы уже многократно испытали вместе со мной. Я долго размышлял, как поделиться с вами радостью в этот особенный день. \n Возможно... вам понравится моё перо? Говорят, оно обладает мягкостью, которая может успокоить душу. Так что, если вы когда-нибудь почувствуете усталость или просто захотите найти тихий уголок, приходите ко мне в любое время. Мои крылья всегда будут готовы опуститься для вас. \n\n Кастор"
  },
  Mail_124304_Name = {Text = "Перо"},
  Mail_124304_Sender = {
    Text = "Кастор"
  },
  Mail_124305_Desc = {
    Text = "Мой маленький·узник·: \n\n Слышал, что в Мисаге недавно популярна одна игра в ролевые игры, какие-то ведьмы, оборотни... Тьфу, звучит совершенно не романтично~ Я вот подумала о гораздо более интересной игре! \n Так, ты будешь играть узника, а я — смотрителя. Когда я взмахну крошечным кнутом, я хочу слышать громкие стоны~ Свечи будут течь по твоему телу, принося горячую боль и удовольствие... Ах, только представив себе эту картину, я уже начинаю чувствовать сладость~ \n Ой, увидев это, ты, наверное, снова нахмурил брови? Какой же ты непослушный, сегодня ведь мой день рождения~ Мой дорогой маленький узник, ты должен немного удовлетворить мою капризную просьбу, не так ли? \n Если не получится... тогда... поменяемся ролями, ты будешь смотрителем, а я — твоей пленницей, как тебе? Я выполню все твои желания~ \n\n Пандия"
  },
  Mail_124305_Name = {
    Text = "Ролевое представление"
  },
  Mail_124305_Sender = {
    Text = "Пандия"
  },
  Mail_124306_Desc = {
    Text = "Страж: \nДорогой, сегодня мой день рождения. В этот особенный день я хочу рассказать вам о своих новостях: под руководством Голиафа и Лотана я, кажется, становлюсь все более способным касаться силы в своей крови. Она больше не спит, а с каждым упражнением гудит и бурлит в моем теле, постепенно освобождаясь. \n\n\n\nЯ не могу точно сказать, когда завершится моя окончательная Метаморфоза, и я стану более чистокровным представителем глубокого моря. Возможно, завтра, возможно, на следующей неделе, возможно, в следующем месяце... Но знайте, что независимо от того, как долго продлится этот процесс и сколько трудностей мне предстоит преодолеть, ваши слова поддержки, которые вы сказали мне в начале, я всегда... буду помнить. Я продолжу стараться. \n\nИ еще одно, что я должен извиниться: я только что узнал из почты Мисаги, что за отправку наличных с письмом нужно доплатить 2 юаня. \nЧтобы покрыть долю за прошлый год, я возьму еще одну сумму из своих сбережений. Они достались мне нелегко, но кровь глубокого моря обязательно выполнит свои обещания. \n\nЦек"
  },
  Mail_124306_Name = {
    Text = "Комиссия..."
  },
  Mail_124306_Sender = {Text = "Цек"},
  Mail_124307_Desc = {
    Text = "Страж: \n\nСлушай внимательно, сегодня вечером, как бы то ни было, Иди со мной в «тот магазин». \nОдежда для маскировки уже отправлена тебе, обязательно, ни в коем случае не дай другим узнать, кто мы! \nВ «том магазине» начали продавать лимитированные сладости, этот мерзкий тип, не знаю откуда взявшийся, наверняка подкупил кучу людей, нельзя позволить им узнать о местонахождении моей особы. \nХотя этот тип забронировал все лимитированные торты в Лентиниене, чтобы не дать мне купить, но… хм-хм. \nЯ уже заранее договорилась с шеф-поваром «того магазина», чтобы он убрал самое вкусное из меню. \nХм, сегодня я хочу, чтобы этот тип понял, что некоторые вещи нельзя решить просто деньгами. \nТогда мы тихо влезем через черный Вход, откроем железную коробку с тройной защитой и получим ту самую лимитированную версию! \nВ качестве вознаграждения я дам тебе кусок (зачеркнуто), половину торта! \nСегодня в одиннадцать вечера я жду тебя в комнате, ты обязательно, просто обязан прийти! Понял? \nНи в коем случае не разглашай, иначе если этот тип узнает о нашем местонахождении, всё будет кончено! \n\nМёрфи"
  },
  Mail_124307_Name = {
    Text = "Битва за торт"
  },
  Mail_124307_Sender = {Text = "Мёрфи"},
  Mail_124308_Desc = {
    Text = "Страж: \n\nС сожалением сообщаю вам, что театр Лондиниум полностью отменил магическое представление мастера Касии по следующим причинам: слишком высокая цена билетов, из-за множества странных событий, которые люди наблюдали в последнее время, интерес к магии угас, на нескольких последних представлениях зрители пропадали и до сих пор не вернулись, и полиция часто находит хозяина театра и требует от мастера Касии приостановить представления для сотрудничества с расследованием и так далее.\nНедавно под влиянием нестабильности в Блэкпуле мои выступления действительно иногда имели небольшие ошибки, это мелочи, но Часть 2 пункт — это то, что мастер Касия абсолютно не может терпеть!\nЯ долго думал над этим и наконец придумал идеальное новое представление! Что касается манипуляции с трупами, воскрешения мертвецов, межразмерных путешествий, эмоционального заражения, гигантских щупалец... все это не стоит упоминания! Ранее под влиянием этой противной межразмерной собаки контроль времени всегда был табу в нашей отрасли, но после запечатывания этой злобной собаки карьера магии мастера Касии вновь поднимется на новую ступень!\nВремя выступления назначено на сегодня вечером, совершенно бесплатно, место в первом ряду, прямо посередине, уже зарезервировано для Хранителя тайн, и вас ждет удивительный интерактивный сегмент! Наслаждайтесь привилегией быть первым интерактивным зрителем в величайшем магическом шоу новой эпохи!\nВо имя восстановления славы мастера Касии!\n\nКасия"
  },
  Mail_124308_Name = {
    Text = "Касия, давайте сделаем магию снова великой!"
  },
  Mail_124308_Sender = {Text = "Касия"},
  Mail_124309_Desc = {
    Text = "Носитель: \n\nСильвия только что пришла и сказала мне, что в этом году на день рождения они возьмут меня покататься на колесе обозрения. \nЛили читала в книжке, что колесо обозрения — это очень-очень большое колесо, и сидя на нем, можно медленно-медленно подняться в небо, смотреть, как вокруг летают птички, и это звучит очень счастливо. \nНо Сильвия сказала, что «на самом деле есть некоторые отличия». Лили не понимает, в чем дело. \nОна также сказала, что место, куда ведет колесо обозрения, слишком высоко, и мне лучше взять с собой одного опекуна. \nЛили не понимает, что значит опекун, но Лили хочет путешествовать между облаками вместе с хозяином. \nПосле обеда я и Сильвия будем ждать тебя у общежития. \n\nЛили"
  },
  Mail_124309_Name = {
    Text = "Колесо обозрения"
  },
  Mail_124309_Sender = {Text = "Лили"},
  Mail_124310_Desc = {
    Text = "Страж (на этот раз я наконец-то всё правильно написал! Круто, да?):\n\nСнова пришло время писать эти сладкие слова, я уже привык. В данный момент я и Коричневый ломаем голову над тем, что же сегодня угостить тебя!\nУличная еда в переулках Восточного района, конечно, вкусная, но сегодня я собираюсь сводить тебя и Коричневого поесть что-то более приличное — то, что любят вы, вест-уэлпцы.\nНапример, эти домашние блюда, покрытые соусами и специями, порции маленькие, тарелки большие и стоят ужасно дорого, просто как грабёж. Думя об этом, я чувствую, как мой кошелёк начинает терять воздух, это, наверное, когда деньги уходят, оставляя рану.\nНо ты — самый важный и любимый человек для меня, кроме сестры и Коричневого, Граждане Восточного района не будут скупиться на своих, так что все расходы сегодня оплачивают я и Коричневый.\nНе недооценивай нас, мы заработали немало денег, доставляя молоко и газеты, а также предоставляя другие услуги, так что не переживай!\n\nТвой хороший партнёр Дженкин и Коричневый"
  },
  Mail_124310_Name = {
    Text = "Сегодня я расплачиваюсь с Брауном!"
  },
  Mail_124310_Sender = {
    Text = "Дженкин"
  },
  Mail_124311_Desc = {
    Text = "Дорогой Страж: \n\nТы, наверное, уже слышал о том, как Сильвия полностью уничтожила подвальный казино Мисаг? Но сегодня мой день рождения, и если не будет какого-нибудь захватывающего мероприятия с приливом адреналина, разве это не будет напрасной тратой ежегодного праздника? \nПосле долгих раздумий я решил пригласить тебя в качестве моего хорошего друга, чтобы мы вместе поймали темного вора, который недавно перебрался с Западного острова и украл сокровища Большого музея. \nКогда я наслаждался напитками в «Баре Аполлона» за пределами кампуса, я случайно слышал, как они с воодушевлением хвастались своими успехами в сборе дорогих драгоценностей. Бармен не придал этому значения, но я-то услышал: изумруды, сапфиры, алмазные короны — и это полностью совпадает с украденным. Чтобы не напугать их, я тщательно метил их, готовясь к тому, чтобы поймать их с поличным, когда они вернутся в свою базу. \nВ Часть 7 вечера, на станции специального поезда Мисаг у входа в кампус, не подведи. \n\nРайкер"
  },
  Mail_124311_Name = {
    Text = "Охотничий план"
  },
  Mail_124311_Sender = {
    Text = "Райкер"
  },
  Mail_124312_Desc = {
    Text = "Страж: \n\nВремя в Мисаг движется, кажется, легче, чем в других местах. Несколько аплодисментов, несколько занавесов, и год снова прошёл. \nЗа этот год у меня появились новые привычки. Раньше, когда я выходил на сцену, даже самый многолюдный театр казался мне пустым. Я танцевал на пустой сцене перед пустым залом, и весь мир наполнялся только звуком танцевальной обуви. А теперь, каждый раз, когда Занавес опускается поднимается, я вижу тебя. Ты одиноко смотришь на меня среди тысяч пустых мест. В твоём взгляде мой танец вновь обретает смысл. \nПрошел год, и твой танец по-прежнему такой неуклюжий, но те живые взгляды в зале способны легко превзойти обыденные движения на сцене. Эти взгляды — это Ручей, который очищает мои всё более обыденные танцевальные Шаги. В этом совместном танце с зрителями я постепенно приближаюсь к тому залу, который всегда искал. Я наконец осознал, что для танца зрители так же важны, как и танцоры. \nНа протяжении нескольких месяцев я готовился к одному танцу. Он был создан под твоим взглядом, зародился в твоём силуэте. Теперь он готов. \nЯ надеюсь, что сегодня вечером он станет первым, кто станет свидетелем его. \n\nЛиз"
  },
  Mail_124312_Name = {
    Text = "Танцовщица и зрители"
  },
  Mail_124312_Sender = {Text = "Лиз"},
  Mail_124313_Desc = {
    Text = "Страж: \n\n Благодаря принятию этого места, в этом году я много разговаривал с королем. Хотя Нисхождение Божественного Царства все еще далеко, время Лимурии, похоже, продолжается в Мисаге. \n Ты и король говорили мне, что Твёрдая Твёрдая вера не должна быть всем в моей жизни. Я был упрям, но недавние события, похоже, изменили мое отношение. Слишком частые молитвы, возможно, могут отвлекать нашего Господа. Кроме искреннего служения, наш Господь, возможно, также хочет, чтобы Его последователи имели свою собственную мелочную жизнь. \n Поняв это, я попытался сделать некоторые небольшие изменения. Я посетил всех известных кондитеров Лентиниена и попросил их научить меня методам выпечки. У них есть некоторые тайны, и я уже через благословение нашего Господа заставил их говорить. Вчера я впервые сделал несколько попыток, несколько последователей сказали мне, что вкус очень неплохой, но их вкус, как и Верность, вызывает сомнения. \n Я хотел бы пригласить тебя сегодня в мой двор попробовать. Я верю в твой вкус и честность. Если это не вкусно, надеюсь, ты сможешь сказать об этом прямо, и я серьезно это исправлю. \n Буду очень признателен. \n\n Мириам"
  },
  Mail_124313_Name = {
    Text = "Другой навык"
  },
  Mail_124313_Sender = {
    Text = "Мириам"
  },
  Mail_124314_Desc = {
    Text = "{Male=Господин,Female=Госпожа} Страж: \n\nНаверняка, вы уже устали слышать о смысле жизни и смерти? В ярких воспоминаниях тех Усопшие в Некрополисе я научился самому важному: важнее, чем исследовать смысл еды, является сама пища на столе перед нами. \nВ древние времена наши предки уже исследовали все аспекты еды — страсть, желание, наслаждение. Мы не едим, чтобы жить, мы живем, чтобы есть. К сожалению, эти первобытные и чистые желания постепенно были забыты с течением времени, и это сообщество стало все более сложным. \nПоэтому я назвал тему сегодняшнего ужина «Чистота». В этот торжественный день все сложные дела уйдут от нас. На этом столе будут только чистая, первобытная страсть и желание, только дегустатор и еда, только ты и я. \nПримите моё самое искреннее Приглашение. Вы не откажетесь от него, Правда? \n\nДоресейн"
  },
  Mail_124314_Name = {
    Text = "Чистый ужин"
  },
  Mail_124314_Sender = {
    Text = "Доресайн"
  },
  Mail_124315_Desc = {
    Text = "Мой дорогой Страж: \n\n Кажется, моё сердце начинает расти... Я знаю, что это звучит странно для Пробуждённого, но это отличается от прежнего, как мне описать это вам? \n Как бы добрые люди ни старались нежно и с состраданием относиться ко мне, пытаясь согреть меня, после ухода брата в моей груди всегда оставалась пустота, чем больше я хожу под солнцем, тем больше меня царапают эти теплоты. Наоборот, темнота и сырость придают мне больше спокойствия, как будто, если я останусь в холодном месте, строгая и болезненная любовь брата никогда не покинет меня. \n Но сейчас, после этих годов, когда я становлюсь все ближе к вам, каждый раз, когда я вижу вас, каждый раз, когда те боли, которые вы мне дарите, касаются моей кожи и передаются в мои кости — ах, счастье в моей груди растет с каждым днем. Если вы будете безжалостно наказывать меня, унижать меня, растаптывать меня, я буду знать, что в этом мире всегда есть место, где я могу по-настоящему укрыться. \n Может ли это счастье продлиться до следующего года, а потом еще на год? Если сбудутся все желания, которые я загадываю на день рождения, единственное желание — это чтобы вы всегда смотрели на меня с презрением, и чтобы была боль... больше и больше боли. Когда вы поднимаете руку, я в первую очередь чувствую этот знакомый, жестокий, счастливый аромат. \n\n Очень-очень надеюсь на ваше наказание, Ли"
  },
  Mail_124315_Name = {
    Text = "Мое сердце"
  },
  Mail_124315_Sender = {Text = "Ли"},
  Mail_124316_Desc = {
    Text = "Страж\n\nХотя мне очень интересно узнать о ваших последних тренировках, пожалуйста, не беспокойтесь, сегодня я не пришел, чтобы подгонять вас к музыкальным занятиям.\nСегодня утром я, как обычно, пошел в музыкальную комнату, но опоздал на тридцать Часть 5 минут. Тренировка по музыке в Часть 7 утра — это привычка, которую я сохранял в течение десятилетий, и сегодня она была легко нарушена. Причина в том, что, проходя по коридору школы, я услышал пение дрозда.\nНарушить привычку, которую сохранял много лет, не так уж просто, особенно для меня. Странно, но я не чувствовал разочарования и гнева, как ожидал. Сначала я почувствовал панику. Но затем я вынужден был признать, что мелодия, которая крутилась у меня в голове, была приятной.\nЛентиниен всегда пробуждается под пение дроздов, этот звук я слышу каждый день, и странно, что за все эти годы это первый раз, когда я обратил на него внимание. Я тихо слушал их песни в коридоре, и в те тридцать Часть 5 минут мне казалось, что эта высшая мелодия вселенной скрыта в их маленьких горлах.\nВозможно, жизнь здесь расслабляет, возможно, атмосфера здесь делает людей мягче. В любом случае, я думаю, что это должно быть связано с вами.\nЯ с радостью принял это изменение за десять минут. Жизнь, как музыка, имеет свой вечный ритм и изменения, день рождения, возможно, это узловая точка, когда эти изменения должны произойти. Я также хочу поблагодарить вас за то, что у меня есть такая возможность успокоиться и послушать то, что я раньше игнорировал. Приятно, да. Я думаю, что это будет началом нового музыкального произведения для меня.\nС этой целью я хотел бы пригласить вас сегодня вечером пойти со мной в лес за пределами школы. Звуки природы на закате отличаются от утренних, но я думаю, что они будут новым вдохновением в нашей музыкальной жизни.\n\nГамельн"
  },
  Mail_124316_Name = {
    Text = "Естественный звук"
  },
  Mail_124316_Sender = {
    Text = "Гамельн"
  },
  Mail_124317_Desc = {
    Text = "Дорогой благородный: \n\n Я только что увидела письмо с днем рождения, которое Фэйнт написала вам... Как и ожидалось, сестра всегда думает о других, просто между сестрами никогда не бывает долгов, и я никогда не считала её обузой. Если бы не её защита, у меня не было бы возможности сейчас проводить турне. \n Уважаемый благородный, вы всегда были моим самым важным слушателем. Поэтому на этот раз я тайно подготовила для вас билет на корабль — искренне приглашаю вас отправиться с нами в это межзвёздное путешествие. Если вы будете с нами, я уверена, что бремя в сердце сестры станет легче. \n Кроме того, пожалуйста, будьте уверены, что в пути мы никогда не будем мешать вашему личному времени. Я и сестра надеемся, что вы сможете насладиться этим путешествием, свободно ощущая каждую туманность и каждую неизвестную встречу. \n\n Тинкт"
  },
  Mail_124317_Name = {
    Text = "Приглашение в путешествие"
  },
  Mail_124317_Sender = {Text = "Тинкт"},
  Mail_124318_Desc = {
    Text = "Страж Тайн: \n\nДень рождения снова приближается, а мысли невольно уносятся обратно на Ситэ. Особенно скучаю по скульптурам на тех художественных выставках. Их безмолвные позы бесчисленное множество раз стучались в двери моего вдохновения.\nВ мастерской целыми днями в окружении скульптур, без художественного общения — со временем это стало утомительным. В прошлом году, чтобы отпраздновать свой день рождения, я вылепила бесчисленное множество скульптурных тортов. Первородный энтузиазм теперь уже угас.\nСейчас мне трудно передвигаться, и возвращение на Ситэ стало несбыточной мечтой. Если ты вдруг планируешь отправиться туда для расследования, не мог бы ты обратить внимание на новые работы на художественной выставке? Мне так хочется твоими глазами вновь прикоснуться к той многогранной и всеобъемлющей красоте искусства.\nВ благодарность я создам для тебя ещё одну скульптуру — назовём её «Страж Тайн на Ситэ». Как тебе?\n\nШань"
  },
  Mail_124318_Name = {
    Text = "Воспоминания о Западном острове"
  },
  Mail_124318_Sender = {Text = "Санга"},
  Mail_124770_Desc = {
    Text = "Страж: \n\nКаждый год мои права доступа в лабораторию отменяются, и этот день становится особенным не самым приятным образом. Чтобы не тратить время на неэффективные мелочи, я посетил архив. \nТам я обнаружил две вещи: одна из них — тетрадь, полная бесполезных пустых страниц. \nДругая тоже тетрадь, и она заставила меня осознать, что я недооценивал безбрежное море знаний, потому что процесс вывода и заключения в ней показали мне, что в мире есть вещи, которые имеют даже меньшую ценность, чем отсутствие. \nИ на обеих тетрадях написано одно и то же имя, наш великий Страж Мисаги %player%. \nЭрика сказала мне, что ты хочешь знать, что подарить мне на день рождения. \nТы можешь подарить мне Лечение. \nМне также любопытно, какой Лечение удивит меня больше. Это будет простое проявление предельной лени и безразличия или ты серьезно учился в течение целого учебного года, оставив эти академические отходы в бесплодной тоске. \nЕсли это первое, то при наличии достаточных оснований и доказательства того, что ты полностью усвоил знания, преподаванные на уроке, я могу подать заявление в колледж на освобождение от домашнего задания. Конечно, это не означает, что я поддерживаю такую безалаберность, которая может сделать тебя полностью ленивым, но если ты сможешь пройти мои испытания, я не старомодный человек и не против дать своим студентам некоторые привилегии. \nЕсли это второе, как твой первый опекун, поверь мне, независимо от того, насколько трудно тебе формироваться, мы сможем найти в технике, которой я владею, способ повысить твои слишком скудные знания и спасти тебя от мучительного состояния невежества. \nСегодня в четыре часа дня я буду в архиве, чтобы лично проверить, насколько ты усвоил знания из класса, не опаздывай. \n\nДолл"
  },
  Mail_124770_Name = {
    Text = "Привилегия"
  },
  Mail_124770_Sender = {Text = "Долл"},
  Mail_124771_Desc = {
    Text = "Щенок Мисаг: \n\nВ этом году ты тоже застрял в тех бесконечных циклах повседневности: попадая в беду, спасая мир, заводя друзей, изучая новые знания и продолжая создавать для мира иллюзии, что Всё как обычно. \nОказывается, даже если вы вытащите свой мозг из тела, а Люминис переместится из одной размерности в другую, это всё равно не повлияет на ваши абсурдные и комичные метания и суету. \nКак же шумно и утомительно, дорогой щенок. \nТы не веришь в эти факты, ты настаиваешь на том, чтобы продлить их страдания, чтобы процесс уничтожения затянулся, какова же твоя цель? Ты действительно притворяешься глупым или люди могут быть настолько глупыми? Даже если я действительно вскрывал кору головного мозга твоего тела, это всё равно остаётся для меня неразгаданной загадкой. \nПоздравляю, ты действительно заставил меня немного поколебаться, я даже начал Сомнение: если Наблюдение за тобой приносит мне такое огромное удовольствие, разве всё это можно считать бессмысленным? \nМолись, как ты умеешь делать, такими бессмысленными молитвами, неважно, кому ты молишься. \nМолись, чтобы ты всегда мог сдерживать меня, щенок, так я и ты сможем найти немного удовольствия в этом бессмысленном мире. \n\n«Долл»"
  },
  Mail_124771_Name = {
    Text = "Помолись"
  },
  Mail_124771_Sender = {
    Text = "Долл: Преисподняя"
  },
  Mail_124772_Desc = {
    Text = "Партнёр: \n\nКаждый год в день рождения писать тебе письмо, похоже, незаметно стало традицией. \nЯ помню, в первый раз, когда я написал тебе письмо на день рождения, отец впервые согласился, чтобы я сам организовал празднование, я пригласил тебя выйти со мной, а потом мы вместе пережили множество первых раз. \nМногие вещи после этого сильно изменились, но если задуматься, кажется, что ничего не изменилось, мы по-прежнему идем по тому пути, который считаем правильным, и рядом с нами по-прежнему есть Близкий Близкий друг друга, и ты по-прежнему самый важный для меня партнёр. \nПоэтому, хотя отец только что прислал мне торт и спросил, хочу ли я прийти на банкет, который он устраивает для меня, у меня есть некоторые другие планы на вечер. \nВ Лентиниене вышел новый фильм, который необычайно популярен, но академия и ассоциация уже подтвердили, что в нем нет никаких духовных реакций. \nЭто означает, что это действительно просто очень замечательная «обычная» работа. \nУ меня как раз есть два билета, ты можешь предположить, что я не стал беспокоить госпожу Солер, потому что билеты действительно очень трудно достать. \nТак что, партнёр, ты согласен уделить это время мне? Возможно, мы сможем временно отвлечься от тех необычных ситуаций, с которыми мы сталкиваемся каждый день, и провести «обычный» вечер вместе. \nКаждое утро, когда мы проснемся, независимо от того, что происходит в мире, я буду с тобой. \n\nРамона"
  },
  Mail_124772_Sender = {
    Text = "Рамона"
  },
  Mail_124773_Desc = {
    Text = "Страж: \n\nБлагодаря моей особой связи с тем, кем я был, и ссылке между мной и тобой, даже если я не могу быть рядом с тобой в каждый момент, я немного осведомлён о твоих действиях за прошедший год. \nТы активен в другом мире и, похоже, всё ещё приносишь изменения, называемые «надеждой», даже глядя на него из черной бездны день за днём, эта энергия, подобная свету, также согревает меня. \nЯ начал снова возвращаться к своему прежнему расписанию, но теперь это не то же самое, и я не сталкиваюсь с предопределенным уничтожением с безнадежным настроением. Ты научил меня новому: перед предначертанной целью процесс, когда каждое существование изо всех сил стремится к продолжению, является причиной, по которой цивилизация, душа и воля имеют значение. \nНесмотря на то, насколько коротким это время может показаться для мира, в котором я нахожусь, я буду продолжать пытаться. Даже если только для того, чтобы снова увидеть знакомые лица и поговорить с ними, эта попытка не является бессмысленной. \nПока ты не остановишься, я буду продолжать идти по этому пути. Позволь мне капризно рассматривать это как способ идти рядом с тобой, так что, возможно, ты иногда будешь думать о том, что всегда есть такой я, который изо всех сил делает то же самое, что и ты. \n\n«Рамона»"
  },
  Mail_124773_Sender = {
    Text = "«Рамона»"
  },
  Mail_124774_Desc = {
    Text = "Убить цель очень просто, а вот разбираться с последствиями — это уже проблема. \n В этом году я хотел бы следовать прошлогодней традиции и снова помочь тебе устранить кого-то. \n Однако я заметил, что ты до сих пор не использовал мой предыдущий Подарок, и, после тщательных размышлений, хотя не знаю, связано ли это с этой причиной, я осознал свои упущения. \n Ты можешь быть совершенно спокоен, хотя я всегда предоставлял своим прошлым работодателям только услуги по устранению врагов, но чтобы избежать различных неприятностей, у меня также есть большой опыт в уничтожении следов. Даже если твоя жертва находится под защитой этих сложных правил и порядков, тебе не нужно беспокоиться, я все улажу. \n Обещаю, никто не сможет выйти на твой след. \n Как только ты определишься с кандидатом, просто сообщи мне имя, и куда бы я ни был, я немедленно приеду, чтобы помочь тебе с ним. \n С праздником, и надеюсь, ты будешь счастлив в день моего рождения, Страж. \n\n\n Илот"
  },
  Mail_124774_Name = {
    Text = "Те, кто часто убивает, знают\n…"
  },
  Mail_124774_Sender = {Text = "Илот"},
  Mail_124775_Desc = {
    Text = "Хорошо, очевидно, что вы не собираетесь прекращать это поведение. Насколько мне известно, я тоже привык к обычаю «дарить подарки».\nНо однажды вы пожалеете о этой доброте, поверьте мне.\nСейчас, вспоминая, это может быть одной из моих самых больших сожалений. Черт возьми, я никогда не думал, что буду сожалеть о том, что убил кого-то.\nНикто не знает лучше меня, что так называемое сожаление не имеет никакой ценности, но до того дня я постараюсь сделать что-то, чтобы исправить свои ошибки, просто потому что я хочу это сделать.\nКогда вы будете ненавидеть меня за это в будущем, не чувствуйте никакой вины.\nЯ приму ваш Негодование на себя полностью.\n\nH"
  },
  Mail_124775_Name = {
    Text = "Ты пожалеешь об этом"
  },
  Mail_124775_Sender = {
    Text = "Илот: Верига"
  },
  Mail_124776_Desc = {
    Text = "Страж: \n\nСнова настал день рождения, по идее, это день празднования жизни, поэтому каждый раз, когда этот день приходит, я испытываю странные чувства. \nМое Ювенильный, похоже, было предназначено для того, чтобы преследовать смерть, и когда я отвлекаюсь от темы смерти, жизнь... или, скажем, сознание продолжается, что это на самом деле означает для меня в этот момент? \nПри жизни, Рождённый войной с болью и чувством вины так тесно переплетены с моей жизнью, что, похоже, только после прихода смерти жизнь впервые действительно принадлежит мне. \nВ прошлом году, в этом году, возможно, и в будущем каждый год. У меня есть почти бесконечное время, чтобы ощутить это, каждый день похож на предыдущий, но в то же время отличается от него. Когда жизнь больше не связана с болью и целями, каким будет ее Конец, или, так называемый, Конец, вообще когда-либо наступит? \nЭта тема слишком велика, я не могу понять. \nНо желание зафиксировать эти странные мысли так реально, что мне кажется, Лечение, как будто, очевиден. \nПо крайней мере для меня, это эти ощутимые, драгоценные моменты, независимо от того, насколько мои мысли запутаны, независимо от того, как трудно мне найти корни, я четко знаю, куда они могут улететь, где их примут, и я также не могу дождаться, чтобы выразить их вам. \nВозможно, в этот день следующего года я смогу найти более глубокий смысл, но сейчас я надеюсь эгоистично сохранить эти маленькие, известные только вам и мне, зависимости. \nДа, Страж, вы и вся Мисаг — это те корни, о которых никто не знает в моем сердце. \nСпасибо вам, как всегда, желаю вам вечного счастья и покоя. \n\nНимфея"
  },
  Mail_124776_Name = {
    Text = "Корневая система"
  },
  Mail_124776_Sender = {
    Text = "Нимфея"
  },
  Mail_124777_Desc = {
    Text = "Недавно Юй изобрел новый способ расслабления — обеденный перерыв в Божественной стране. \n В отличие от обычного краткого и спешного обеденного перерыва, во время обеденного перерыва в Божественной стране Юй покинет долгое сидение на каменном троне, создаст сферу, блокирующую звуки, с помощью запястья, а затем заполнит все пространство специальной морской водой. \n Эта морская вода может не только издавать желаемый Юем аромат и превращаться в пейзажи, которые он хочет видеть, но также поддерживать его тело с подходящей силой со всех сторон. \n Таким образом, независимо от того, какую позу Юй примет, он сможет испытать ощущение тепла, словно находится в самой роскошной перьевой постели. \n В это время Юй сможет расслабить разум в любимом аромате, наслаждаясь уединением и покоем, положив голову на свой любимый подушку и спокойно уснув. \n Как самый любимый Министр Юя, он считает, что в день рождения наиболее уместно поделиться этой безмятежностью с тобой. Если ты заинтересован, можешь прийти в то секретное место, о котором я говорил в прошлый раз. Не беспокойся о своей безопасности, Юй отдельно откроет пространство для тебя, чтобы ты не испытывал влияния его мечтаний. \n Не забудь взять с собой самую удобную подушку. \n\n Тулу"
  },
  Mail_124777_Name = {
    Text = "Обеденный перерыв"
  },
  Mail_124777_Sender = {Text = "Тулу"},
  Mail_124778_Desc = {
    Text = "Мой Погоня за светом: \n\nЯ с Кастором уже адаптировались к жизни в Мисаг, после того как сбежали от кровавых интриг церкви, я чувствую, что нахожу себя прошлого. \nХотя сейчас в повседневных словах и действиях всё ещё неизбежно присутствует Чёрная Чёрная тень «Святого Сына», но верю, что скоро я смогу полностью смыть эту Надменность и отчуждённость, оставив только смирение перед божеством и Решимость следовать своим путем. \nРанее я получил неожиданный Подарок — это была красиво оформленная книга, рассказывающая о людях, покинувших родину и вернувшихся домой, чтобы вернуть свои детские воспоминания. Вместе с ней пришла записка с надписью «Желаю тебе вскоре вернуть своего первоначального себя». \nЭта фраза, как только я её увидел, сразу вызвала в памяти множество воспоминаний — забота всех в Мисаг, твое руководство, Погоня за светом мой, и брат его... тёплые объятия. \nПоэтому в этот день рождения я хочу пригласить всех из Мисаг принять участие в праздновании моего и брата дня рождения. Без вашей помощи у нас не было бы шансов вернуть те самые моменты. \nЯ арендовал ресторан на свои последние сбережения, и шеф-повар там знаком со всеми кухнями мира, так что каждый сможет попробовать свои самые знакомые вкусы. \n\nПоллукс"
  },
  Mail_124778_Name = {
    Text = "Вернуть Детство"
  },
  Mail_124778_Sender = {
    Text = "Поллукс"
  },
  Mail_124779_Desc = {
    Text = "Я решил принять Приглашение отПодземелье арены на окраине и участвовать в поединке на жизнь и смерть. \n Хотя время в клубе форели было хорошим, оно слишком однообразно: каждый день только убивать рыбу. Возможно, я действительно полностью покорил форель, но покорение форели не считается настоящей победой! \n Кровь в моем теле, кровь воина, кипит, она всегда жаждет захватывающей битвы, и вот, наконец, появилась возможность. \n Лысый, который со мной связался, сказал, что нашел для меня трех натайских удавов, двух медведей с дьявольским лицом, четырех серенасонов и кучу странных существ, названия которых я не запомнил, чего достаточно, чтобы я мог сражаться всю ночь напролет. \n Я специально попросил их организовать бой на сегодня, чтобы в день рождения продемонстрировать тебе — я, Увхаш, последний римский воин, покоритель всех диких зверей на земле! \n Сегодня на арене больше не будет остатков форели, а лишь кровь и трупы диких животных! \n\n Увхаш"
  },
  Mail_124779_Name = {
    Text = "Покорение зверя"
  },
  Mail_124779_Sender = {Text = "Увхаш"},
  Mail_124780_Desc = {
    Text = "«Рыцарь Серебряного ключа»:\n\nХранитель тайн! Только что, когда я модифицировала «Фантом», Моск вдруг принесла мне целую большую — упаковку деталей, сказала, что это мой Подарок на день рождения, и только тогда я вспомнила, что сегодня мой день рождения!\nПоэтому я быстро написала тебе письмо, как же так, я снова забыла про сегодня, хотя я уже написала... сколько записок я написала? \nНо это не важно, важно то, что я вспомнила, о чем говорила, что нужно делать в день рождения — я хочу сесть на «Фантом» и вместе с тобой и Моск облететь Лондиниум сто кругов!\nХотя Моск совершенно не понимает в механике, но у нее было так много деталей, что я могу собрать все необходимые детали. Теперь модифицированный «Фантом» стал супер усиленной прототипной версией (на время)!\nЯ назвала это приключение «Приключение Нautiла с Хранителем тайн и Моссом и Фантомом», как тебе, звучит прямо и легко запоминается? Так я точно не забуду это приключение.\nХи-хи, действительно ожидаю, Страж, подожди немного, «Рыцарь Фантома» Нautiла и «Рыцарь Вихря» Моск скоро будут здесь!\nКоманда приключений «Фантом», в бой!\n\nНаутила, разгоняясь на полную мощность"
  },
  Mail_124780_Name = {
    Text = "«Фантом» в атаке!"
  },
  Mail_124780_Sender = {
    Text = "Наутила"
  },
  Mail_124793_Desc = {
    Text = "Уважаемый великий <Del:милый> Страж {Male=господин,Female=дама}:\n\nКхм, давно не общались, наш дорогой Страж {Male=господин,Female=дама}, вы соскучились по мне~\nТеперь вы настоящая знаменитость в Мисаг, все студенты изучают ваши героические дела, и все, что хоть немного связано с вами, можно продать на черном рынке за баснословные деньги!\nНо это вполне нормально, ведь кто же вы, как не «жив legenda», единственный Страж Мисаг? \nЗа этот год в Мисаг произошло много интересных событий — Аурита подружилась с несколькими пряничными человечками, профессор Долл взорвал семнадцать лабораторий, чтобы изменить стиль своей головы, Кастор попался на уловку Агриппы и помогал ей на экзамене, в результате чего его оценка оказалась хуже, чем у неё!\nАх да, ещё та мерзкая мышь, которая украла мою драгоценную пленку, это же был единственный раз, когда я смогла запечатлеть кошачью форму «24»Мисс!\nКроме того, есть ещё много всего, яПриведено в порядок это и отправила вам в специальном новогоднем выпуске школьной газеты.\nЧто? Вам интересно, как я с вами связалась? Хе-хе, это секрет, я не скажу, что использовала много эксклюзивных секретов, чтобы обменяться с одной дамой, которая выглядела довольно сложно для общения!\nВ новом году давайте вместеусердие, с новым годом, %player%!\n\nХанна Писли"
  },
  Mail_124793_Name = {
    Text = "Специальный выпуск на Новый год"
  },
  Mail_124793_Sender = {
    Text = "Ханна Писли"
  },
  Mail_124794_Desc = {
    Text = "Бледный посланец: \n\nСеребряная ночь близка, позвольте мне сначала здесь выразить вам свои самые искренние пожелания. \n\nВ прошлый раз, когда я посетил дом для бедных Лилиан, некоторые дети тайком спросили меня: «Существуют ли действительно посланники зимнего перехода?». \nМне стало любопытно, почему у этих детей возникла такая мысль, если я не ошибаюсь, в прошлом году каждый ребенок получил Подарок от «посланника зимнего перехода». \nВ результате дети сказали мне: — «Я видел, как тот красивый Мужчина передал Подарок директору Диане, он вообще не похож на посланника зимнего перехода!». \nДолжно быть, это лорд случайно попался детям на глаза, когда дарил подарки дому для бедных, что и вызвало эти маленькие сомнения. \n\nПоэтому в этом году на Серебряную ночь я подготовил два традиционных костюма посланника зимнего перехода и хотел бы попросить бледного посланника вас сыграть вместе со мной посланника зимнего перехода, чтобы вручить эти подарки детям. \nЯ уверен, что какой-то ребенок ночью тайком откроет глаза, запомнит наш образ в красной одежде и красной шапке, а затем на празднике зимнего перехода радостно сообщит всем: — «Я видел посланника зимнего перехода!». \nКроме того, я специально подготовил для вас Подарок, надеюсь, вам понравится. \nС праздником зимнего перехода. \n\nСальвадор"
  },
  Mail_124794_Name = {
    Text = "Папа Ноэль"
  },
  Mail_124794_Sender = {
    Text = "Сальвадор"
  },
  Mail_124991_Desc = {
    Text = "Уважаемый Страж:\nАкция «Всестороннее исцеление: повтор» завершена. Теперь оставшиеся у Хранителя тайн игровые деньги «пазл памяти» меняются по курсу «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_124991_Name = {
    Text = "Восстановление памяти через пазлы"
  },
  Mail_124991_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_125448_Desc = {
    Text = "Уважаемый Страж:\nАкция «Шёпот Хуанпу» завершена, теперь оставшиеся у Хранителя тайн «Грушевый леденец» будут обменены по курсу «Купон розового золота» × 40 за штуку, пожалуйста, не забудьте проверить."
  },
  Mail_125448_Name = {
    Text = "Сбор грушевой пастилы"
  },
  Mail_125448_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_126321_Desc = {
    Text = "Уважаемый Страж:\nМероприятие «Ткач в собственных сетях» завершено. Оставшиеся у вас «Билеты бархатного кресла» были конвертированы в «Золотые купоны розы» × 40 за каждый билет. Пожалуйста, не забудьте забрать их."
  },
  Mail_126321_Name = {
    Text = "Вернуться долга билетов «Бархатное кресло»"
  },
  Mail_126321_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_126934_Desc = {
    Text = "Страж: \n\nСнова настал этот особенный день. Ха, не беспокойся, в этом году я не буду на тебя давить психологически, я просто хочу пригласить моего самого особенного пациента в одно место, чтобы отдохнуть. \nТам густые леса, чистые реки, полные дыхания природы, которые помогут тебе забыть усталость стального леса. Будут также мягкие ковры, теплые камины, яркий Погоня за светом, чтобы помочь тебе расслабиться от быстрого ритма города. \nМы сможем гулять, читать, болтать, и я с удовольствием выслушаю все, что ты хочешь рассказать. \nАх, только представление такой картины уже наполняет меня волнением... \nЯ знаю, что в этот момент ты, вероятно, немного нервничаешь. В конце концов, я не могу гарантировать, что не буду наслаждаться твоими сладкими болезненными воспоминаниями. Но ты все равно придешь, не так ли? \nНе только потому, что сегодня мой день рождения, но и потому, что ты нуждаешься во мне, тебе нужно выговориться, тебе нужно, чтобы я выслушал тебя. \nПослушный ребенок, я понимаю это, и я буду ждать тебя. Давай, забудь о суете повседневной жизни и тяжелых обязанностях, наслаждайся этой минутой спокойствия. \n\nКлементина"
  },
  Mail_126934_Name = {
    Text = "Момент покоя"
  },
  Mail_126934_Sender = {
    Text = "Клементина"
  },
  Mail_126935_Desc = {
    Text = "Снова скучный день.\nЯ перепробовал многое — филистимлянские пиры по традиции, детские игры с бандами Лондиниума, но ничто не достойно стать подарком в день рождения Царя Гигантов.\nФилистимляне находят радость в битве и убийстве. В прежние времена в этот день я собирался в лагере с сильнейшими воинами, сражался с ними, отмечая этот великий день силой и кровью.\nМир. Унылый мир. Я понимаю стремление таких людей, как вы, к миру — не каждый наделён душой воина. Однако не думайте, что этот лживый мир способен поколебать великого владыку филистимлян.\nВсё, что некогда принадлежало мне, — земли, богатства, Независимый, негасимая слава филистимлян… В тот день, когда я верну их себе, я приглашу вас, Страж Тайн. Я усажу вас на почётнейшее место рядом со мной, чтобы вы наблюдали, как великий Царь Гигантов вновь обретает свою славу.\nЯ уже собирался просто положить Конец этому скучному дню, однако только что узнал, что разгромленные банды объединились в союз и намерены устроить облаву на Царя Гигантов прямо на сегодняшнем вечернем пиру.\nПо сравнению с войнами филистимлян это лишь наивная игра. Но в эти унылые мирные дни такое развлечение вполне способно меня порадовать.\nПриходите вновь — полюбуйтесь на боевую доблесть владыки филистимлян. Встаньте рядом со мной или встаньте против меня — как вам угодно.\nТолько поторопитесь. Опоздаете — останется лишь собирать трупы.\n\nГолиаф"
  },
  Mail_126935_Name = {
    Text = "Развлекательная программа"
  },
  Mail_126935_Sender = {
    Text = "Голиаф"
  },
  Mail_126936_Desc = {
    Text = "Уважаемый Страж: \n\nЗдравствуйте. Для лучшего обслуживания студентов и преподавателей Мисаг, Эрика несколько дней назад самостоятельно провела обслуживание и Улучшение. Вам повезло, вы были выбраны для оценки результатов этого обновления. Оценка будет проводиться в оффлайн-формате и требует от вас оценки функциональности установленного на автоматической кукле Эрике эмоционального модуля номер LY-S-761. Ожидается, что тест займет у вас 90 минут, пожалуйста, заранее спланируйте свое время, чтобы избежать конфликтов в расписании. \nВот содержание данной оценки: \n1. Пожалуйста, проведите с Эрикой не менее 15 минут открытого глубокого разговора на тему «день рождения», чтобы оценить понимание Эрикой конкретных эмоций и их глубину. \n2. Пожалуйста, смоделируйте сцену «подарка на день рождения» и взаимодействуйте с Эрикой, чтобы оценить точность, гибкость и комфортность её эмоционального распознавания и эмпатического ответа. \n3. Пожалуйста, в середине теста намеренно упомяните личные детали, о которых Эрика говорила в начале беседы (например, её отношение и понимание дня рождения), чтобы оценить, нормально ли функционирует её способность к долговременной памяти и ассоциациям. \n\nПосле завершения вышеупомянутой оценки, пожалуйста, скажите Эрике: «Эрика, с днём рождения», чтобы завершить тест, и кукла автоматически перейдет в режим загрузки данных. \nСпасибо за ваше участие, после завершения теста Эрика подарит вам специальный маленький Подарок. Также просим вас продолжать поддерживать, ваша самая заботливая помощница Эрика всегда будет рядом с вами. \n\nЭрика"
  },
  Mail_126936_Name = {
    Text = "Оценка обновления на день рождения"
  },
  Mail_126936_Sender = {Text = "Эрика"},
  Mail_126937_Desc = {
    Text = "Ха, что сегодня происходит? Почему, куда бы я ни пошёл, все сознательно избегают меня? Даже я ещё не успел заговорить, а они уже машут руками, говорят, что здесь им плохо, там болит, из-за чего я не могу попросить о дуэли. \n Как же редко в день «рождения» можно без всякой причины с уверенностью сражаться с другими, так разве это не похоже на обычные дни? \n Чёрт, в прошлом году не следовало так жестоко с ними обращаться. Но это было невозможно, ведь до рождения этой планеты я постоянно оттачивал своё мастерство фехтования, и это естественно, что обычные люди не могут это вынести. \n Но ты ведь не такой, ты же Страж! \n Так что ты понимаешь, что я хочу сказать, да? Всё на том же месте, давай проведём настоящую битву. На этот раз никто не помешает нашему сражению. \n\n Лотан"
  },
  Mail_126937_Name = {
    Text = "Единственный Противник"
  },
  Mail_126937_Sender = {Text = "Лотан"},
  Mail_126938_Desc = {
    Text = "Самый-самый-самый дорогой Носитель: \n\n Вы слышали? Сегодня в особняке мэра пройдет суперроскошный бал, и все джентльмены и дамы гордятся тем, что могут на него попасть. \n Конечно, как горничная, Карен не имеет права участвовать. Но вы, Страж Мисаг, мой дорогой, самый дорогой Носитель, вы достойны всего самого прекрасного в этом мире, и, конечно, этого бала. \n Поэтому Карен уже приняла Приглашение для вас и заботливо вызвала экипаж, все подготовила, вам только нужно будет отправиться с Карен к дому мэра~ \n Карен наденет свое самое красивое Наряд, возьмет самые блестящие украшения, чтобы все увидели мощь всемогущей горничной, чтобы поднять вам репутацию и прославить вас! \n Ах, когда вы увидите это письмо, я, должно быть, уже жду вас у ваших Врат, те экипажи, а также слуги с новыми одеждами и украшениями уже на месте, единственная маленькая проблема - за эти услуги еще не заплачено... \n Но мой самый добрый и милый Носитель никогда не будет волноваться из-за таких мелочей, Правда? Мэр все еще ждет нас~ \n\n Ваша самая милая, самая сияющая горничная \n Карен"
  },
  Mail_126938_Name = {
    Text = "Роскошный бал"
  },
  Mail_126938_Sender = {Text = "Карен"},
  Mail_126940_Desc = {
    Text = "Страж, Страж! Несколько дней назад Дженкин сказала, что нашла место, очень похожее на дом Ауриты, которое, как будто, называется водой... Угу, Аурита забыла. \n В любом случае, Дженкин сказала, что там будут дельфины, маленькие рыбки, аквариум и много-много медуз, и они все готовы стать друзьями Ауриты! \n Аурита любит друзей, Аурита хочет много-много друзей, поэтому Аурита хочет в день рождения пригласить своих любимых друзей, то есть Хранителя тайн, пойти вместе. \n Быстро собирай вещи и отправляйся со мной, Аурита уже не может дождаться. \n\n Аурита, которая хочет познакомиться со многими новыми друзьями"
  },
  Mail_126940_Name = {
    Text = "Новые друзья аквариума!"
  },
  Mail_126940_Sender = {
    Text = "Аурита"
  },
  Mail_126941_Desc = {
    Text = "Страж:  \n\nСпасибо, что сегодня рано утром вы прогулялись со мной у моря. Удары волн и яркое звездное небо успокаивают меня и напоминают о... давних событиях. \nВ то время членам экипажа было запрещено разговаривать со мной, поэтому большую часть времени я могла только смотреть на постоянно меняющуюся поверхность моря и на морских птиц, парящих в воздухе. Члены экипажа, глядя на этих птиц, бессознательно загадывали мне желания. \nИногда они хотели превратиться в птиц, вернуться домой, к своим любимым; иногда они хотели, чтобы их плавание закончилось быстрее, обменяв груз на богатство; иногда они молились о романтической любви или о встрече с легендарной русалкой... \nНо как бы ни были сложны эти желания, к полуночи они становились едиными, превращаясь в жажду сна. В это время я откликалась на их молитвы, успокаивая морской ветер и делая воду нежной. \nТак что, если, Страж, вам трудно уснуть, пожалуйста, не бродите в одиночестве у моря, а приходите ко мне. \nЯ хочу разделить ваше бремя, стать полезным, а защитить ваш сон — это то, что я могу сделать сейчас. \nЭто также... мое «желание», которое я загадываю в этот особенный день. \n\nСелеста"
  },
  Mail_126941_Name = {
    Text = "Желаю вам спокойного сна"
  },
  Mail_126941_Sender = {
    Text = "Селеста"
  },
  Mail_126942_Desc = {
    Text = "Во имя судьбы, Страж Университета Мисаг, мудрый и добродетельный господин: \n\nМир вам!\n Когда я писал это письмо, я долго колебался, но честность также является одной из добродетелей рыцаря. Как рыцарь своего господина, я должен отдать вам всю свою Верность, без всяких скрытий, и поэтому я также должен сказать вам правду — \n в этот день рождения, господин, я прошу вас прийти в мою комнату, чтобы прочитать мне сказку на ночь. \n Позвольте мне... прикоснуться к вам и уснуть в ваших мечтательных и прекрасных историях. \n На самом деле, это было одним из моих детских желаний. Но обучение рыцаря не терпит ни минуты лени, и я уже давно перерос возраст, когда слушают сказки, поэтому я всегда хранил это в своем сердце и никогда не говорил об этом. Но вы... господин, вы особенный, я не хочу скрывать от вас ничего... \n Если вы считаете это недопустимым, пожалуйста, дайте мне знать. С этого момента я больше не буду делать таких чрезмерных просьб и буду удваивать свои усилия в тренировках. \n Жду вашего ответа. \n\nОжье"
  },
  Mail_126942_Name = {
    Text = "Просьба рыцаря"
  },
  Mail_126942_Sender = {Text = "Ожье"},
  Mail_126943_Desc = {
    Text = "Уголёк:\n\nСегодня, Моск, день рождения!\nДруг сказал, что на день рождения напишет письмо маленькому угольному шарiku, он придет играть!\nМосс не умеет писать письма. Но Близкий Близкий друг умеет!\nДруг научит Мосса. Моск счастливый!\nНа самом деле, Моск забыл о дне рождения.\nНо Моск хочет поиграть с маленьким угольным шариком!\nПоэтому Моск решает, что сегодня - день рождения!\nМаленький угольный шарик собирает ракушки, золотые, белые, все есть~\nУвидев маленький угольный шарик, Моск счастлив~Друг готовит, вкусно~\nМаленький угольный шарик на старом месте~\nПусть Близкий Близкий друг приготовит большой ужин! Поедим вместе!\nМосс ждет тебя~\n\nМосс"
  },
  Mail_126943_Name = {
    Text = "День рождения! Приходи играть!"
  },
  Mail_126943_Sender = {Text = "Моск"},
  Mail_126944_Desc = {
    Text = "Страж: \n\nНесколько дней назад вы сказали, что хотите загадать желание под метеорным дождём, поэтому я специально организовал это путешествие. Благодарю вас за то, что вы приняли моё Приглашение, я буду ждать вас на берегу в назначенное время. \nПожалуйста, не переживайте, это краткосрочное путешествие, я также тщательно проверил близлежащие морские воды, чтобы гарантировать вашу безопасную навигацию к месту падения метеоров и помочь вам получить метеорит. \nТаким образом, вы сможете лично прикоснуться к метеору и загадать желание, а на таком близком расстоянии метеор точно услышит ваше желание и исполнит его! Для меня будет честью быть тем, кто ведёт вас к исполнению вашего желания, это одно из самых особенных дел, которые я когда-либо делал. \nЕщё раз спасибо вам, вы позволили мне найти новую «Навигационную миссию» в этот особенный день. Пожалуйста, обязательно приходите вовремя, я буду ждать вашего прихода. \n\nКорпосант"
  },
  Mail_126944_Name = {
    Text = "\n\nЖелание, доступное на кончиках пальцев"
  },
  Mail_126944_Sender = {
    Text = "Корпосант"
  },
  Mail_129637_Desc = {
    Text = "Дорогой Близкий Близкий друг: \n\nНе помню, в который раз я проходил через цветник за часами, когда случайно обратил внимание на розарий. \nС тех пор я несколько раз бывал здесь, переживая моменты беспокойного волнения черной ямы, моменты смерти и противостояния, моменты, когда временной поток течет обратно; они все стояли там, как всегда, величественно и тихо. \nЭта картина пробудила воспоминания, которые не принадлежат мне, о букете роз, который Рамона хотела подарить тебе, и я почувствовал небольшое облегчение. \nХотя мы с тобой разделены размерами, я всегда верил, что, независимо от того, с какими трудностями ты сталкиваешься, ты и та «Рамона» сможете сохранять спокойствие и бесстрашие, находя путь к разрешению ситуации. \nВ конце концов, независимо от того, как меняется мир, розы всегда продолжают распускаться. \n\n«Рамона»"
  },
  Mail_129637_Name = {
    Text = "Сад роз…"
  },
  Mail_129637_Sender = {
    Text = "«Рамона»"
  },
  Mail_129806_Desc = {
    Text = "Страж: \n\nВ особняке Морского города огни уже загорелись. Не знаю, где вы находитесь в этот момент и кто рядом с вами? \nВ начале года, в самый важный день для древнего государства, праздник воссоединения и новорождённого. Этот день я пережила много раз, но никогда не чувствовала усталости. Холодная зима уже прошла, Расцвет всего сущего, люди так надеются, надеются, что смогут, как эта земля, отбросить все страдания в прошлое и встретить новое Начало. \nСтарые раны и желания не так легко оставить. Прощая старое и встречая новое, какое прекрасное пожелание... Возможно, боль снова вырастет, желания никогда не исчезнут, но этой ночью, по крайней мере, этой ночью, люди поднимут бокалы и будут праздновать новый мир, нового себя. \nПоэтому, в момент смены старого года на новый, люди встречают его фейерверками. \nИз всех интересных вещей фейерверки — это моя любимая. Все люди смотрят на них, наблюдают, как они сжигаются, поднимаются в воздух, распускаются, как будто смотрят на бога, восхищаясь этой кратковременной, несравненно яркой красотой. \nВы заметили? Когда смотрят на фейерверки, в сердцах людей всё чисто. Они забывают Досаждение, забывают страдания, забывают всю грязь. Сердца всех людей становятся спокойным озером, на поверхности которого лишь прекрасное отражение фейерверков. \nТсс... Не спрашивайте, что будет после фейерверков. Новорождённый, возможно, это роскошь, но не стоит из-за этого пренебрегать его расцветом. \nИз всех несовершенных вещей фейерверки являются самыми чистыми. Этой ночью я хочу подарить вам свою частичку. \nПоднимите голову, не моргайте. Смотрите, как восходят сверкающие звёзды, когда фейерверк распускается, встречая нового себя, Страж. \n\n«Цянь Шань»"
  },
  Mail_129806_Name = {
    Text = "Фейерверк"
  },
  Mail_129806_Sender = {Text = "Сюй?"},
  Mail_130223_Desc = {
    Text = "Уважаемый Страж:\nАкция «Перерождение наизнанку» завершена. Оставшиеся у Хранителя «Бледная чешуйчатая пыль», «Красная чешуйчатая пыль» и «Сияющая чешуйчатая пыль» были конвертированы из расчёта «Купон розового золота» × 40 за каждую единицу. Не забудьте проверить почту."
  },
  Mail_130223_Name = {
    Text = "Вернуться долга чешуйчатой пыльцы"
  },
  Mail_130223_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_131005_Desc = {
    Text = "Уважаемый Страж:\nАкция «Призыв Мерскса» завершена. Теперь оставшиеся у Хранителя тайн «Турбинелла №1», «Улитка номер два», «Турбинелла №3» меняются на каждую по «Купон розового золота»× 40. Пожалуйста, не забудьте проверить."
  },
  Mail_131005_Name = {
    Text = "Сбор морских раковин"
  },
  Mail_131005_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_131093_Desc = {
    Text = "Уважаемый Страж: \nАкция «Пламенное пиршество: повтор» завершена. Теперь «Настоящая берцовая кость», «Круглолистный аммонит» и «спиральные руины» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_131093_Name = {
    Text = "Воспламеняющаяся валюта группового праздника для возврата"
  },
  Mail_131093_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_131767_Desc = {
    Text = "О, @2! @3 — это @2 высший @3 смешанный @4 и разрушенный @2! Взывай @4...! \n\n Ах-ах! Посмотри, что ты натворил!!! Ты прикоснулся к запрету высшего божества! Теперь всё плохо, Его шёпот уже разнесся по твоему миру, черная катастрофа начнет распространяться с твоего устройства, поглощая всё вокруг... \n Бедняжка, твоя неосторожность действительно создает мне трудности. Но не отчаивайся, к счастью, ты встретил меня — великого ангела культа, избранного божества, исполнителя высшего бога, законного наследника великого культа, спасителя страданий, друга бога! Я — воля бога доброты и любви, не могу терпеть страдания в этом мире, я с помощью своей высшей силы спасу каждого глупого озорника. \n О, я увидела твой насмешливый взгляд. Ничего страшного, добрый бог любит людей и не обижается на их глупость. Недоверие к спасителю — это путь каждого последователя. Эти приветственные подарки — это награда от исполнителя бога для тебя. \n Теперь светлый путь уже указан для тебя: возьми свою искренность и иди в @2 кафедральный собор в @3 городе, принеси свою преданность богу доброты, и ты получишь желанную силу, освободившись от проклятия этого кошмара. Конечно, также необходимо принести свои богатства. Пожалуйста, не пойми неправильно, добрый бог не заботится о мирских вознаграждениях, но его последователи тоже нуждаются в деньгах для выполнения своих дел. Не скупись на эти приземленные вещи, дорогой Последователь, за каждую копейку — своя цена. \n Взывай к имени бога доброты, ожидая момента явления чуда! \n\n Великий ангел культа, избранное божество"
  },
  Mail_131767_Name = {
    Text = "Пожалуйста, не трогайте этот @2"
  },
  Mail_131767_Sender = {
    Text = "Карабу"
  },
  Mail_132339_Desc = {
    Text = "Уважаемый Страж:\nАкция «воскрешение бога-короля: повтор» завершена, теперь оставшиеся у Хранителя тайн «утомленные мысли», «печаль и тревога», «радостные мысли» будут конвертированы по соотношению «Купон розового золота» × 40 за каждую, пожалуйста, не забудьте проверить."
  },
  Mail_132339_Name = {
    Text = "Воскрешение бога-короля: обмен валюты"
  },
  Mail_132339_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_132458_Desc = {
    Text = "Уважаемый Страж Тайн:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы улучшить ваш игровой опыт в Университете Мисагар, мы приглашаем вас заполнить следующую анкету. В знак благодарности за ваше участие мы подготовили награду — «Серебряные ядра» × 200, которые можно получить сразу после заполнения анкеты. Срок заполнения — до 9:00 17 августа, пожалуйста, не забудьте заполнить вовремя.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя Тайн. Ваши отзывы обязательно сделают Университет Мисагар ещё лучше!\n        — Да укажет Серебряный Ключ путь."
  },
  Mail_132458_Name = {
    Text = "Анкета о версии V2.5.3"
  },
  Mail_132458_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_132578_Desc = {
    Text = "Уважаемый Страж:\nВ режиме «Мчащийся экспресс наслаждений» сезона {s1} вы получили титул «{s2}».\nВы получите следующие дополнительные награды, пожалуйста, не забудьте забрать их."
  },
