  },
  Mail_132579_Desc = {
    Text = "Уважаемый Страж:\nВ режиме «Фазовые шахматы: Режим готовых колод» сезона {s1} вы получили титул «{s2}».\nВы получите следующие дополнительные награды, пожалуйста, не забудьте забрать их."
  },
