  },
  Mail_132580_Desc = {
    Text = "Уважаемый Страж:\nВ режиме «Погружение в грёзы» сезона {s1} вы получили титул «{s2}».\nВы получите следующие дополнительные награды, пожалуйста, не забудьте забрать их."
  },
  Mail_132580_Name = {
