  },
  Mail_132580_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_132581_Desc = {
    Text = "Уважаемый Страж:\nВ режиме «Фазовые шахматы: Режим драфта» сезона {s1} вы получили титул «{s2}».\nВы получите следующие дополнительные награды, пожалуйста, не забудьте забрать их."
  },
  Mail_132581_Name = {
    Text = "Итоги сезона «Фазовые шахматы: Режим драфта»"
  },
  Mail_132581_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_132605_Desc = {
    Text = "Пи-пи-пи, пи-пи-пи-пи-пи!\n(Страж, с днём дурака!)\nПи-пи-пи, пи-пи!\n(Фотография, на память!)\n«Беспорядочный влажный след морского выдры»\n«Большое количество неудачных оттисков воска»\n                                                         — аккуратный след морской выдры"
  },
  Mail_132605_Name = {
    Text = "Комок мокрой бумаги"
  },
  Mail_132605_Sender = {Text = "Пи!"},
  Mail_133276_Desc = {
    Text = "Уважаемый Страж:\nМероприятие «Великое завоевание · Повтор» завершено. Оставшееся у вас «Вкусное Инкарнация на гриле от Лео» было конвертировано в «Золотые купоны розы» × 40 за каждую единицу. Пожалуйста, не забудьте забрать их."
