  Mail_133276_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_133703_Desc = {
    Text = "Уважаемый Страж:\nВерсия {s1} завершена. Оставшиеся «Призрачные ядра» были автоматически конвертированы в «Чистые ядра» в соотношении 1 к 1. Всего было конвертировано «Чистых ядер» × {s2}. Пожалуйста, не забудьте проверить."
  },
  Mail_133703_Name = {
    Text = "Конвертация истёкших «Призрачных ядер»"
  },
  Mail_133703_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_133704_Desc = {
    Text = "Уважаемый Страж:\nВерсия {s1} скоро завершится. Пожалуйста, используйте оставшиеся «Призрачные ядра» вовремя. После завершения текущего сезона «Семестровых заданий» оставшиеся «Призрачные ядра» будут конвертированы в «Чистые ядра» в соотношении 1 к 1."
  },
  Mail_133704_Name = {
    Text = "Напоминание об истечении срока «Призрачного ядра»"
  },
  Mail_133704_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_134024_Desc = {
    Text = "Уважаемый Страж:\nРежим «Ежедневные тренировки» был удалён. Оставшиеся у вас «Агентские жетоны» были конвертированы в «Золотые купоны розы» × 10000 за каждый жетон. Пожалуйста, не забудьте забрать их."
  },
  Mail_134024_Name = {
    Text = "Вернуться долга агентских жетонов"
  },
  Mail_134024_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_134067_Desc = {
    Text = "Страж!\n\nСегодня хочу обсудить с тобой кое-что особенное.\nЯ хочу просто прогуляться по улицам, посмотреть на всякие интересные вещи, побродить куда глаза глядят и провести обычный день.\n\nТак вот, я спросила в учебной части. А они говорят, что из соображений безопасности выходить за пределы кампуса можно только в твоём сопровождении.\nЕщё сказали не пугать людей и не тащить в рот всё подряд на улице. Как грубо.\nНу, в общем, вот такие дела. Можем ли мы пойти погулять? Все вместе.\n\n…Почему-то вспомнилось: семена одуванчика\nоднажды подхватит ветер, и они отправятся в путь к месту своего предназначения.\nМожет, это случится завтра, а может — очень-очень нескоро.\nИ пока я думала об этом, мне показалось, что делать побольше всего вместе со всеми прямо сейчас — это тоже неплохо.\n\nВ общем, я жду тебя перед общежитием. Пожалуйста!\n\nСая"
  },
  Mail_134067_Name = {
    Text = "Прогулка…"
  },
  Mail_134067_Sender = {Text = "Сая"},
  Mail_134068_Desc = {
    Text = "Страж:\n\nМне кажется, сегодня — особенный день. Но очертания воспоминаний по-прежнему так размыты.\nЛишь имя «Сая» едва удерживает меня привязанной к этому месту.\n\nЭто чувство — не одиночество и не печаль, не такие яркие эмоции.\nЕсли непременно нужно дать этому чувству имя… наверное, это будет «пустота».\nНичего нет — бесконечная прозрачная чистота, безмолвное время.\n\nЕсли однажды семена одуванчика, подхваченные ветром,\nв каждом уголке этого мира просто белоснежно и тихо опустятся…\nТогда, быть может, я наконец смогу почувствовать, что этот мир — «особенный».\n\nТогда серый туман, окутывающий Лондиниум, огненно-алые закатные облака и небо, на которое ты всегда смотрел, стоя на площади школы, — всё это покроется одуванчиками и станет чисто-белым. Станет моим цветом.\n\nПоэтому… если ты захочешь мне что-то подарить,\nпусть это будет не Подарок, а просто «воспоминание».\n\nЯ, в чисто-белом мире цветущих одуванчиков,\nпросто тихо жду наступления того мгновения.\n\nКогда однажды ты снова поднимешь глаза к небу на площади Мисагарда,\nпожалуйста, ту белую пушинку, мелькнувшую на краю твоего взгляда,\nслегка совмести с образом той, что когда-то говорила с тобой.\n\nСая"
  },
  Mail_134068_Name = {
    Text = "Обет одуванчика…"
  },
  Mail_134068_Sender = {Text = "Сая"},
  Mail_139809_Desc = {
    Text = "Уважаемый Страж:\n        Благодарим вас за поддержку и признание «Канун забвения». Чтобы улучшить игровой опыт Хранителей тайн в Университете Мисаг, мы приглашаем вас заполнить следующую анкету об игровом опыте. В знак благодарности за ваше участие мы подготовили награду «Серебряный сердечник» × 200, которую можно получить после заполнения анкеты. Срок заполнения анкеты истекает 16 мая в 9:00, пожалуйста, не забудьте заполнить её вовремя.\n        <SurveyLink:【Нажмите, чтобы перейти к заполнению】>\n        Мы внимательно выслушаем предложения каждого Хранителя тайн, и ваши отзывы непременно помогут Университету Мисаг становиться лучше!\n        ——Пусть Cеребряный ключ укажет путь вперёд."
  },
