    Text = "Уважаемый Страж!\nСобытие «Незримая симфония · Повтор» завершено. Оставшиеся у вас «Возвышенные аккорды» конвертированы в «Золотые купоны розы» × 40 за каждый. Пожалуйста, проверьте получение."
