  Mail_141372_Desc = {
    Text = "Уважаемый Хранитель:\n«Вечный Эпоянс» Завершено, и оставшиеся у Хранителя «Свежая »добыча«», «Крупная »добыча«», «Древняя »добыча«» будут конвертированы по курсу «Купон розового золота» × 40 за каждую единицу. Пожалуйста, не забудьте проверить получение."
