  },
  Mail_141470_Desc = {
    Text = "Уважаемый Хранитель:\n«Узник зеркал: повтор» Завершено, и оставшиеся у Хранителя «Книга общих знаний», «Книга математики», «Книга литературы» будут конвертированы по курсу «Купон розового золота» × 40 за каждую единицу. Пожалуйста, не забудьте проверить получение."
  },
  Mail_141470_Name = {
    Text = "Сбор валюты из Зеркальных Узников"
  },
  Mail_141470_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_141507_Desc = {
    Text = "Страж: \n\nВ день своего рождения, возможно, это важный день для тебя? \nДля меня же вес каждой дня на сети судьбы одинаков. Именно другие истории придают этому дню особое значение. \nЯ родилась в этот день, в этот день осознала Пророчество, в этот день получила колесо судьбы Ткачихи, в этот день увидела те сложные ниточки судьбы и те кошмары, которые ждут на их концах. \nДля Ткачихи судьбы этот день ничем не примечателен. Для актёров на сцене этот день стоит отпраздновать. А среди всех личностей, больше всего радости мне приносит моя роль актрисы. \nСтраж, сегодня Погоня за светом театра судьбы потушен, только один сценический Погоня за светом горит ярко. Ты упоминал, что хочешь больше узнать о судьбах, через которые я прошла. А сейчас на этой сцене будет разыграна история о мне. \nЯ не знаю, какая именно история будет разыграна. Я подарю воспоминания сцене, и она в те сильные моменты выберет тот Фрагмент, который ты больше всего хочешь увидеть, чтобы представить на сцене этой ночью. \nЭта история, возможно, причинит мне боль, возможно, будет неловкой, но это неважно, не так ли? Я думаю, иногда позволить колесу само ткет судьбы, быть простым зрителем — это приятно. \nЕдинственный билет на это представление уже у тебя в руках. Приди с этим письмом, Страж. Этой ночью история, о которой больше никто не знает, ждёт твоего прихода. \n\nАрахна"
  },
  Mail_141507_Name = {
    Text = "Скрытая история"
  },
  Mail_141507_Sender = {
    Text = "Арахна"
  },
  Mail_141833_Desc = {
    Text = "Уважаемый Хранитель:\n«Новолуние и Глубокий Снег» завершено. Оставшиеся у Хранителя «Красные Яблоки», «Золотые Яблоки» и «Сахарные Яблоки» будут конвертированы по курсу «Купон розового золота» × 40 за каждое. Пожалуйста, проверьте вложение."
