  },
  Mail_142101_Desc = {
    Text = "Давно не виделись, %player%:\n\nКогда ты получишь это письмо, я, должно быть, буду пролетать над Ягро — каждый год в этот месяц мой охотничий маршрут становится чуть длиннее.\nНет ничего более подходящего в качестве музыкального сопровождения для дня рождения, чем вопли и стоны врагов. К тому же у меня припасено достаточно клеток — пока найдётся хоть один глупец, готовый поклоняться лжебогам, которые несут лишь страдания и никакого Искупления, я найду его на краю света и заставлю осознать свою ошибку.\nИногда, когда кошмар пронзает облака и можно увидеть Луну, в голове мелькают какие-то нелепые мысли.\nНапример, когда всё это внезапно и неотвратимо прекратится — так же, как жизнь когда-то рухнула без всякого предупреждения.\nНо потом я сама над собой смеюсь. В тот день, когда я ступила на этот путь, я оказалась на дороге без возврата. Уверена, ты прекрасно понимаешь, что я имею в виду, малыш. В этом мире нет никого, чьё положение было бы более схожим с нашим.\nМы оба выбрали выборы, в которых не было выбора. Хорошая новость в том, что мы оба наслаждаемся своим выбором.\nВ новом году — только свистни в охотничий свисток, который я тебе подарила, и я тут же окажусь рядом.\nКонечно, если ничего непредвиденного не случится, позволь мне сначала насладиться этим путешествием в полной мере. В следующем месяце я привезу тебе сувениры и поделюсь новыми впечатлениями.\nЖелаю тебе всего наилучшего и счастья.\n\nТвой любимый «дядюшка»"
  },
  Mail_142101_Name = {
    Text = "Впечатления"
  },
  Mail_142101_Sender = {
    Text = "Твой любимый «дядя»"
  },
  Mail_143935_Desc = {
    Text = "Уважаемый Страж:\nАкция «временный текст» завершена. Теперь оставшиеся у Хранителя тайн «временный текст»,«временный текст»,«временный текст» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_143935_Name = {
    Text = "Свиток иного мира возврат"
  },
  Mail_143935_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_145435_Desc = {
    Text = "Уважаемый Хранитель:\nМероприятие «Игра Левиафана» завершено. Оставшиеся у Хранителя «Кровавые Жертвы» будут конвертированы из расчёта «Купон розового золота» × 40 за каждую. Не забудьте проверить полученное."
  },
  Mail_145435_Name = {
    Text = "Возврат Кровавой Жертвы"
  },
  Mail_145435_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_145468_Desc = {
    Text = "Уважаемый Хранитель:\nМероприятие «Если б жизнь была как прежде: повтор» завершено. Оставшиеся у Хранителя «Прибрежные ракушки» будут конвертированы из расчёта «Купон розового золота» × 40 за каждую. Не забудьте проверить полученное."
  },
  Mail_145468_Name = {
    Text = "Сбор прибрежных ракушек"
  },
  Mail_145468_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_146401_Desc = {
    Text = "Календарь — скучное изобретение. Все дни ничем не отличаются друг от друга, включая сегодняшний.\nПо вашему календарю сегодня — день моего рождения. Слово «рождение» не совсем точно для меня. Я — обломок, вырванный из Хаоса, клинок, выкованный в бесчисленных сражениях. Меня создала не утроба — меня создал каждый Противник, скрестивший со мной оружие. И ты — один из самых важных среди них.\nВы придаёте таким дням большое значение. Пиры, подарки, тосты — мне всё это не нужно.\nМне нужна лишь одна битва.\nЗа это время ты совершил немало невероятных вещей. Но я знаю: то, что ты показал, — ещё далеко не твой предел.\nСегодня на закате — на тренировочной площадке. Возьми своё оружие, я буду ждать тебя там. Не думай о победе или поражении, не беспокойся о потерях. Миг, когда клинки сталкиваются без удержания, — это единственный подарок, которого я жду. Покажи мне, на что способен осколок @4.\nДумаю, ты меня удивишь, мой «Противник»."
  },
  Mail_146401_Name = {
    Text = "Единственное ожидание"
  },
  Mail_146401_Sender = {
    Text = "Лотан: Китовластица"
  },
  Mail_146873_Desc = {
    Text = "Уважаемый Страж:\nАкция «временный текст» завершена. Теперь оставшиеся у Хранителя тайн «временный текст»,«временный текст»,«временный текст» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_146873_Name = {
    Text = "Свиток иного мира возврат"
  },
  Mail_146873_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_147081_Desc = {
    Text = "Календарь — скучное изобретение. Все дни ничем не отличаются друг от друга, включая сегодняшний.\nПо вашему календарю сегодня — день моего рождения. Слово «рождение» не совсем точно для меня. Я — обломок, вырванный из Хаоса, клинок, выкованный в бесчисленных сражениях. Меня создала не утроба — меня создал каждый Противник, скрестивший со мной оружие. И ты — один из самых важных среди них.\nВы придаёте таким дням большое значение. Пиры, подарки, тосты — мне всё это не нужно.\nМне нужна лишь одна битва.\nЗа это время ты совершил немало невероятных вещей. Но я знаю: то, что ты показал, — ещё далеко не твой предел.\nСегодня на закате — на тренировочной площадке. Возьми своё оружие, я буду ждать тебя там. Не думай о победе или поражении, не беспокойся о потерях. Миг, когда клинки сталкиваются без удержания, — это единственный подарок, которого я жду. Покажи мне, на что способен осколок @4.\nДумаю, ты меня удивишь, мой «Противник»."
