  Mail_148477_Name = {
    Text = "Выдача невостребованных наград «{s1}»"
  },
  Mail_148477_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_148478_Desc = {
    Text = "Уважаемый Хранитель:\n        Награды, полученные в «Семестровом проекте – Сложная тема» {s1} периода, не были получены. Они отправлены вам в виде вложения к этому письму. Пожалуйста, освободите место в инвентаре перед получением."
  },
  Mail_148478_Name = {
    Text = "Досылка неполученных наград сложной темы {s1} периода"
  },
  Mail_148478_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_148514_Desc = {
    Text = "Уважаемый Хранитель:\n        В обновлении версии V1.4.3.5 в «Мире чуждых снов: Осквернение» был добавлен уровень «Новый король». Поскольку часть Хранителей не была своевременно уведомлена об этом обновлении, они ошибочно полагали, что «Мир чуждых снов: Осквернение» пройден полностью.\n        В связи с этим в текущем обновлении V2.6.2 мы восполнили прогресс прохождения уровня «Новый король» для Хранителей, которые прошли последующие уровни после «Нового короля» до обновления, а также досылаем соответствующие награды за первое прохождение. Пожалуйста, проверьте вложение."
  },
  Mail_148514_Name = {
    Text = "Восполнение прогресса «Осквернения»"
  },
  Mail_148514_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_148515_Desc = {
    Text = "Дорогой Хранитель:\n\nТа-да~ Неожиданно, правда? Это первый день рождения этой феи в Мисаге, и поэтому —\nВнимание! Никаких рекламных писем, никаких Приглашений на богослужение и даже никаких апокалиптических Пророчеств~\nНо не стоит расстраиваться — эта фея, конечно же, приготовила кое-что более ценное и замечательное для самых особенных прихожан.\nБудучи Всеведущ и всемогущ феей-крёстной, она, разумеется, предвидит все закономерные сомнения и подозрения. Хотя это немного огорчает эту фею, ради распространения благодати своей паствы небольшое Жертвоприношение всегда неизбежно.\nПоэтому, сделав шаг назад и хорошенько подумав, просто попробуйте — терять-то всё равно нечего, а вдруг это правда? Верно?\nЭто шанс, который выпадает лишь раз в году, и его ни в коем случае нельзя упускать~\nНе нужно никаких Подношений, никаких обещаний и обменов — достаточно лишь разделить с феей-крёстной сладкое послеполуденное чаепитие, и вы узнаете, сколько искренних чувств к вам скрыто под толщей льда и снега.\nРазве это не соблазнительное предложение?\nПримечание: пожалуйста, обязательно возьмите с собой достаточно Леонских флоринов для оплаты счёта — не менее 10, 100, 1000, чем больше, тем лучше.\n\nБдение вас в том заведении, которое мы оба знаем,\nКарабу"
  },
  Mail_148515_Name = {
    Text = "☆☆☆Супер-письмо с подарками☆☆☆"
  },
  Mail_148515_Sender = {
    Text = "Карабу"
  },
  Mail_149949_Desc = {
    Text = "Это письмо обошло тысячу кругов между мирами живых и мёртвых — не удаляй его!\n\nВ середине седьмого месяца врата духов открываются, поднимается потусторонний ветер, и блуждающие души возвращаются домой.\nЯ — ■■■ из Хуского города Древней страны дракона спирали, и это моё скромное послание!\nВо исполнение указа Чжунъюань, с грамотой призыва душ в руках, нынешней ночью я насылаю проклятие. Тот, кто прочтёт эти слова, будет внесён в реестр душ, имя его уже вписано в книгу — и если до полуночи он не перешлёт это письмо пятидесяти живым людям, то непременно...\nДокумент рассыплется в прах за миг до сохранения...\nВ пузырьковом молочном чае всегда будет не хватать трёх жемчужин...\nЗаряд Серебро-коммуникатора навечно застрянет на 1%, и никакая зарядка не поможет...\n\nПослушайся — и проклятие снимется само, талисман сгорит, злой дух отступит, а свет не погаснет.\nПересылай!! Немедленно!!!"
  },
  Mail_149949_Name = {
    Text = "[Предупреждение Чжунъюань] Осмелившийся удалить это письмо навлечёт на себя..."
  },
  Mail_149949_Sender = {
    Text = "Ичжи Е"
  },
  Mail_149985_Desc = {
    Text = "Господин,\n\nПрошу простить за неожиданное письмо — надеюсь, оно не покажется вам бестактным. Но есть кое-что на душе, о чём я могу говорить лишь с вами.\nПрошлой ночью мне впервые за долгое время приснился сон — я вернулась в Наш дом, в те давние дни. Всё было таким родным: тёплые, мягкие руки отца, народная песня, которую напевала служанка во время Подметать, и та белая пони, что принадлежала мне... Я думала, что всё это давно утонуло в болоте памяти, но увидев снова во сне, я почувствовала прежнее тепло.\nПроснувшись, я увидела в окно, как преподаватели и студенты Мисаг неспешно беседуют, проходя мимо. Такое умиротворение и красота — на миг мне показалось, что эта картина ничем не отличается от той, что была во сне. И ещё я заметила, что незримое, что живёт во мне, с этого утра хранит необычную тишину. Неужели в день рождения и правда случается что-то счастливое?\nЕсли это так, то, пожалуй, сегодня я могу позволить себе быть немного жадной...\nЯ знаю, что люди обычно загадывают желания в день рождения — как надежду на целый год вперёд. Я давно не смела мечтать о чьих-то поздравлениях, но есть одна возможность, которую мне хотелось бы получить.\nТак же, как вы доверяете мне, я не стану ничего от вас скрывать — [Удержание] — поэтому позвольте открыть вам моё желание:\nЕсли в следующий раз у вас будет задание, назначьте меня Свита и возьмите с собой.\nЧто бы ни случилось, я хочу всегда быть рядом, когда вы нуждаетесь в помощи больше всего, — первой вставать на вашем пути и быть вашим самым надёжным Щит.\nВот желание, которое я загадываю в этом году.\n\nОжье"
  },
  Mail_149985_Name = {
    Text = "Желание на день рождения..."
  },
  Mail_149985_Sender = {
    Text = "Клятвопреступник·Ожье"
  },
  Mail_18019_Desc = {
    Text = "Дорогой Страж:\nСистема обнаружила, что текущий аккаунт совершил операцию возврата средств. Разработчики уже в {s1} произвели вычет соответствующей части виртуальной валюты согласно вашему заказу на возврат. Если после вычета Баланс становится отрицательным, необходимо восстановить его для корректной работы.\nЕсли у вас есть вопросы, пожалуйста, свяжитесь со службой поддержки клиентов."
  },
  Mail_18019_Name = {
    Text = "Уведомление о возврате"
  },
  Mail_18019_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_18020_Desc = {
    Text = "Привет, Страж, награда, полученная в {s1}, из-за того, что ваш рюкзак полон, была отправлена вам как вложение в письме. Пожалуйста, освободите место в рюкзаке, чтобы получить награду"
  },
  Mail_18020_Name = {
    Text = "Выдача невостребованных наград"
  },
  Mail_18020_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_18021_Desc = {
    Text = "Уважаемый Страж:\nАктивность «Семестровые задания» текущего сезона завершится {s1} 【GMT+8】. После завершения активности награды текущего сезона «Семестровых заданий» станут недоступны. Пожалуйста, не забудьте забрать награды до окончания активности."
  },
  Mail_18021_Name = {
    Text = "Напоминание о получении награды за приказ"
  },
  Mail_18021_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_18029_Desc = {
    Text = "Привет, Страж, это награда за ранг в Иллюзорное Вдаль от берегов."
  },
  Mail_18029_Name = {
    Text = "Награда за рейтинг Иллюзорное Вдаль от берегов"
  },
  Mail_18029_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_18031_Desc = {
    Text = "Дорогой Страж:\n\nПуть впереди долгий и покрытый терновыми зарослями. В такие трудные моменты нам нужно помогать Близкий Близкий друг другу и двигаться вперёд вместе.\nК этому письму прилагается сегодняшняя специальная партия Линфеина, пожалуйста, примите её.\nПусть Cеребряный ключ освещает ваш путь.\nПримечание: на данный момент выдача данной специальной партии завершена, благодарю вас за усердие и усилия.\n\nЛогистический отдел Учёного совета Мисаг"
  },
  Mail_18031_Name = {
    Text = "Пополнение в ножнах"
  },
  Mail_18031_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_18034_Desc = {
    Text = "Привет, Страж. Вы не забрали очки за Вдаль от берегов. Мы отправили награду в письме."
  },
  Mail_18034_Name = {
    Text = "Накопительные награды за глубокое Вдаль от берегов в иллюзию ещё не получены"
  },
  Mail_18034_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_18035_Desc = {
    Text = "Дорогой Страж:\n\nПуть впереди долгий и заросший тернием, в такие трудные моменты нам нужно действовать сообща и двигаться вперёд.\nК этому письму прилагается сегодняшний особо одобренный запас линфеина, прошу принять его.\nПусть Cеребряный ключ освещает ваш путь.\nP.S.: ваш особо одобренный запас истекает через {s1} дней, пожалуйста, рационально распределите время расследования.\n\nЛогистический отдел комитета Мисаг"
  },
  Mail_18035_Name = {
    Text = "Пополнение в ножнах"
  },
  Mail_18035_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_20231_Desc = {
    Text = "Дорогой Страж, новый сезон фазового поединка начался, ваш ранг сброшен с {s1} до {s2}. Награда за ранг нового сезона была сброшена, вы можете получить больше чести и наград, повышая свой ранг! {s3}\n{s4}"
  },
  Mail_20231_Name = {
    Text = "Почта сезона фазового поединка"
  },
  Mail_20231_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_21453_Desc = {
    Text = "Дорогой Страж:\n\nПрошу прощения за Беспокойство, не знаю, как у вас дела?\nИзвините, что беспокою вас в такое занятное время, но Дженкинс и остальные приготовили для меня небольшую вечеринку по случаю дня рождения. Я долго-долго думала, и всё же решила сама отправить вам это Приглашение.\nБольшинство сирот, которых приютила мастерская, не помнят свои дни рождения, поэтому девушка Сара назначила днем рождения день их появления в приюте. Только я другая: девушка Сара сказала, что меня оставили на пороге дома для бедных в одну из самых холодных зимних ночей. Она хотела, чтобы моя жизнь больше не была холодной и блеклой, поэтому выбрала для меня теплый день в качестве дня рождения. Поэтому это особенный день, когда меня окружают забота и любовь. Для меня это очень важный день, и я хочу, чтобы Страж тоже был со мной в этот день — это моё маленькое желание. Конечно, если это невозможно, то это тоже нормально, ведь у Хранителя тайн много дел, Ай Джис это понимает.\nЕсли это Приглашение доставило вам какие-либо неудобства, пожалуйста, сообщите мне, и примите мои искренние извинения. Но если, возможно, вы сможете найти время, то я буду очень-очень рада вашему присутствию на их шалостях. Может быть, это будет очень интересно, ведь это Дженкинс готовил.\n\nАй Джис"
  },
  Mail_21453_Name = {
    Text = "Простите за Беспокойство в вашей загруженной повестке.."
  },
  Mail_21453_Sender = {Text = "Айгис"},
  Mail_21454_Desc = {
    Text = "Эй:\nЯ всегда не могу понять, что такого особенного в дне рождения, чтобы его праздновать? Стоит ли из-за этого устраивать такой большой переполох?\nВ прошлом году в этот день один студент спросил меня о дате моего дня рождения. Просто смешно. Когда я родилась, на этой планете еще не существовало понятия времени, не говоря уже о днях рождения. Но она так меня достала, что я сказала ей: «это момент равноденствия, когда день и ночь делятся поровну». Не знаю, как она это в итоге поняла.\nНапоминаю тебе: сегодня после 12 ночи убери цветы у входа в мою комнату, они невыносимо пахнут!\n\nРотань"
  },
  Mail_21454_Name = {
    Text = "Те прекрасные цветы.."
  },
  Mail_21454_Sender = {Text = "Лотан"},
  Mail_21455_Desc = {
    Text = "Эрика сегодня принесла большую упаковку кофе, сказала, что это Подарок на мой день рождения, и добавила, что это твоя ежегодная доля на весь этот год.<Del:Но ты сделал это по своей воле? Если нет>\n Если это Дора или кто-то ещё подстроил тебе розыгрыш, то хотя мне будет очень жаль, я всё равно могу вернуть его... тебе. Ведь это же кофе! Я засыпаю уже после двух чашек, а целый год без него? Ты, должно быть, спишь как Тулу. Не то чтобы он плохой, просто... чёрные вещи появляются ночью... В общем, если тебе нужно, ты можешь забрать кофе в любое время, конечно, если ты оставишь кофе здесь,<Del:я тоже> я думаю, что буду очень рад. Тогда я наконец смогу провести тот эксперимент, который я задумал: извлечь и сконцентрировать кофеин, чтобы создать средство для поглощения через кожу, которое можно приклеить на кожу и оставаться бодрым, всё время...\n\n\n Венкор, который очень хочет провести этот эксперимент"
  },
  Mail_21455_Name = {Text = "Кофе.."},
  Mail_21455_Sender = {Text = "Уинкл"},
  Mail_21456_Desc = {
    Text = "День рождения?\nЕсли уж на то пошло, мой день рождения не является хорошим днём. В этот день погибли сотни невинных жизней, чтобы я мог «родиться» и затем убить ещё больше людей.\nПоэтому в этот день особо нечего праздновать. Но я понимаю, что вы, люди, очень цените ритуалы, и у меня как раз есть немного денег — не волнуйтесь, это честно заработанные деньги, которые я заработал, потея в Клубе ТROUT, а не незаконные доходы.\nВозьмите эти деньги и купите себе Подарок, пусть это будет празднованием моего дня рождения.\n\nЮу Хаши"
  },
  Mail_21456_Name = {
    Text = "День рождения.."
  },
  Mail_21456_Sender = {Text = "Увхаш"},
  Mail_21457_Desc = {
    Text = "Страж:\n\nСуществует ли в землях Мисаг обычай празднования дня рождения?\nВ моей памяти о родине... каждый год устраивались грандиозные церемонии в честь дня рождения короля.\nСо временем особое значение «дня рождения» распространилось на всех людей.\nВ далеком прошлом, в день рождения коллеги и друзья прибывали ко мне Издалека.\nЭто чувство окружения близкими... это тепло, словно объятия солнца... возможно, именно поэтому я не могу отпустить прошлое.\nАх... я слишком увлекся, не помешал ли я вашей работе?\nЯ приготовил некоторые из привычных ранее угощений и хотел бы поделиться ими с вами.\nЕсли вам будет угодно, приходите ко мне после ужина.\n\nФалост"
  },
  Mail_21457_Name = {
    Text = "Нерукотворный Погоня за светом.."
  },
  Mail_21457_Sender = {Text = "Фарос"},
  Mail_21458_Desc = {
    Text = "Сегодня действительно день, достойный памяти: в этот день произошло величественное Нисхождение Господа Голиафа, короля гигантов, в мир; в этот день Океан содрогнулся, а звёзды померкли.\nГоворят, в кампусе запрещено расточительство, так что давайте устроим мой день рождения в масштабе одной десятой от прежнего уровня — десять жареных поросят, сто шашлыков из осьминогов и музыкальную группу, исполняющую народные песни Голиафа. Ах да, танцовщиц тоже дюжину...\nЧто? Это всё запрещено?\nТогда хотя бы танцовщицы... Не дюжина, достаточно четырёх или пяти.\nЧто? И это не разрешено?!\nТакая скудная организация не подходит для моего положения. Объявляю сейчас: план вечеринки отменяется!\n\nГолиаф"
  },
  Mail_21458_Name = {
    Text = "План ужина.."
  },
  Mail_21458_Sender = {
    Text = "Голиаф"
  },
  Mail_21459_Desc = {
    Text = "Страж——\n\nСегодня, когда я проходила тренировку памяти у миссис Сильвии, она спросила о моем дне рождения. Ты же знаешь, я только что положила гаечный ключ и сразу же забыла его, как же я могу помнить день рождения! Более того, это ведь то, что знаю только я! Этот день рождения можно считать забытым. \n\nНо Священник Сальвадор сказал, что конкретная дата не важна, важно, что я отмечаю каждый день, поэтому я решила, что сегодня — мой день рождения! Я уже договорилась с одним человеком (я забыла, кто это, не ты ли, Страж?) провести вечеринку у входа в столовую, ты обязательно должен прийти! \n\n\n\nЯ абсолютно-абсолютно запомню эту дату дня рождения, Нотила\n\n\n\nЗаписка, пришедшая вместе с письмом: \n\nЭтот ребенок, закончив писать письмо, стремительно ушел, оставив письмо и некоторые вещи, которые, как он сказал, предназначены для тебя, на столе. \nЯ все вложила в конверт, жду вечера, чтобы встретиться с тобой на вечеринке. Не переживай, я напомню ей о необходимости прийти сегодня. \n\n——Сильвия"
  },
  Mail_21459_Name = {
    Text = "Я решил свой день рождения!"
  },
  Mail_21459_Sender = {
    Text = "Наутила"
  },
  Mail_21460_Desc = {
    Text = "Малыш:\n\nВ Море Первоматерии нет ни звёзд, ни солнца, ни луны, ни смены времён года, поэтому мой день рождения должен значиться как «неизвестен».\nНо сегодня действительно особенный день, ведь этот облик унаследован от одной человеческой девушки, имевшей «заветное желание». Она любила шумные компании, поэтому и открыла эту маленькую лавку, но из-за постоянных расследований свои дни рождения она обычно проводила лишь в моём обществе. Чтобы исполнить её прижизненное желание, лавка «Утешение» сегодня проведёт ужин при свечах, и мы сердечно приглашаем всех наших верных клиентов.\nРазумеется, лавка «Утешение» также предоставит всем гостям небольшую скидку, так что, малыш, не упусти эту возможность.\n\nДафодель"
  },
  Mail_21460_Name = {
    Text = "Человеческое желание.."
  },
  Mail_21460_Sender = {
    Text = "Даффодил"
  },
  Mail_21461_Desc = {
    Text = "Когда меня забрали от семьи, моя приёмная Матушка... жена правителя разбила глиняную табличку с записью о моём рождении вдребезги, уничтожив моё прошлое как тилорианца. Настоящий день рождения, конечно же, теперь уже не узнать.\nПосле расставания с Лай, я тоже задумался... А что, если считать днём моего «день рождения» ту ночь, когда я сбежал и начал мстить? Как ты думаешь, это подходящая идея?\nХотя сейчас уже нет необходимости отмечать наступление нового года жизни, но как Подсказка о смене времени это кажется неплохим вариантом."
  },
  Mail_21461_Name = {
    Text = "День рождения"
  },
  Mail_21461_Sender = {Text = "Илот"},
  Mail_21462_Desc = {
    Text = "Тестирование, тестирование. \n Уважаемый Страж, привет. Если вы получили это письмо, это означает, что ваше мнение крайне важно для Эрики, и вы были выбраны для участия в ежегодной проверке и ремонте языкового модуля автоматической куклы Эрика. Данная оценка проводится в форме открытых вопросов, и вам нужно оценить функциональность последнего установленного языкового модуля EA-L-1033 у Эрики. Это не займет много времени, поэтому, пожалуйста, не переживайте. \n Открытый вопрос: \n Поняли ли вы основное содержание данного письма? \n\n Пожалуйста, запишите Лечение прямо под вопросом в отведенном месте и поместите письмо обратно в конверт. \n Благодарим за ваше участие. \n\n Эрика"
  },
  Mail_21462_Name = {
    Text = "Тестирование, тестирование.."
  },
  Mail_21462_Sender = {Text = "Эрика"},
  Mail_21463_Desc = {
    Text = "Страж:\n\nТы один из немногих в этой школе, кто остался в здравом уме. Твой взгляд способен проникнуть сквозь это искалеченное тело и увидеть истинную меня.\nС твоими способностями ты точно сможешь объяснить детям: я не русалка, это тело одолеет моря и горы ради достижения совершенного облика.\n... Ладно, не буду тебя затруднять. Но хотя бы сегодня не позволяй им играть с моим хвостом.\nСегодняшний день особенный. Если у тебя найдётся время, я хотела бы кое-что рассказать тебе лично.\n\nКекес"
  },
  Mail_21463_Name = {
    Text = "Совершенное тело.."
  },
  Mail_21463_Sender = {Text = "Цек"},
  Mail_21464_Desc = {
    Text = "Страж:\n\nМой день рождения в обычном смысле слова — это день, когда отец усыновил меня.\nРаньше он всегда придавал этому дню особое значение и каждый год устраивал большие балы — танцевать в корсете намного труднее, чем размахивать мечом три тысячи раз.\nНо это было его сердечное желание как отца, и я не хочу разочаровать его в этой нелегкой любви.\nОднако в этом году он наконец согласился, чтобы я сама организовала программу на свой день рождения. Возможно, в глазах отца я уже больше не ребенок, которого нужно держать под контролем.\nКстати, ты сможешь пойти со мной на вершину колокольни? Поговорим, подышим свежим воздухом.\nГоворят, сегодня будет полнолуние.\n\nРамона"
  },
  Mail_21464_Name = {
    Text = "Полная луна.."
  },
  Mail_21464_Sender = {
    Text = "Рамона"
  },
  Mail_21465_Desc = {
    Text = "Дорогой, самый дорогой Носитель:\nДа, верно, сегодня у Гарен день рождения, ей исполняется @1 год (возраст дамы должен оставаться тайной)!\nПо этому поводу Гарен подготовила невероятно грандиозную вечеринку и пригласила всех, кого только можно было пригласить~! Хотя в итоге согласились прийти только Орета, Оргр и Лили...\nНо это не важно, где есть люди, там есть вечеринка, а где есть вечеринка, там есть Гарен! Для этого случая Гарен тщательно приготовила «Улучш. вариант» жабьего рагу, чесночных торфяных слизней и карри из летучей мыши, Носитель обязательно должен попробовать~\n\nТихонько спрошу, Носитель, вы наверняка подготовили Подарок для Гарен, Правда? Помните, он должен блестеть!\n\nВаша всегда покорная Служанка\nГарен"
  },
  Mail_21465_Name = {
    Text = "Подарок.."
  },
  Mail_21465_Sender = {Text = "Карен"},
  Mail_21466_Desc = {
    Text = "Дорогой <Del:Страж> из Западного района:\nЭто <Del:приглосительное пригла пригласительное Приглашение> в общем, приходи есть бесплатный торт и заодно отпраздновать мой день рождения! На самом деле это ещё и чтобы поблагодарить тебя за то, что ты помог мне найти сестру и привёл меня сюда, дав мне и Брауну место, где можно спокойно жить.\n(Всё это выше Эйджис заставила меня написать, жуть какая слащавость. Между нами такие церемонии ни к чему, Правда ведь, Страж?)\nВ общем, сегодня вечером во дворе за твоим общежитием мы с Брауном и Эйджис приготовили кое-что вкусное и ждём тебя, чтобы разделить это вместе! Ну, на самом деле в основном готовила Эйджис, она потрясающе готовит, даже дамы на кухне хвалят её талант. Если не придёшь — пожалеешь, гарантирую.\n\nТвои старые приятели Дженкин и Браун"
  },
  Mail_21466_Name = {
    Text = "Дорогой западный парень.."
  },
  Mail_21466_Sender = {
    Text = "Дженкин"
  },
  Mail_21467_Desc = {
    Text = "Страж:\n\nКогда люди оставались в царстве богов, мы уже начинали выражать свои чувства через танец – безумные вращения, Шаги скорби... Говорят, история танца так же длинна, как и история человечества, ведь танец свидетельствовал как о наших триумфах, так и о падениях.\n\nЯ сказала, что больше не буду танцевать, но... я всё-таки рождена для танца. Так что, хотя бы сегодня, ты готов танцевать со мной? Погрузиться вместе, почувствовав ритмы глубин тела.\n\nЯ буду ждать тебя в танцевальном зале.\n\n\n\nЛиз"
  },
  Mail_21467_Name = {
    Text = "Приглашение к танцу"
  },
  Mail_21467_Sender = {Text = "Лиз"},
  Mail_21468_Desc = {
    Text = "Уважаемый Страж:\n\nДо того как стать Пробудившим, я праздновал свой день рождения с товарищами, пробираясь с алкоголем снаружи лагеря, и прятались мы в палатке для хранения продовольствия, отмечая за считанные хлеба и тайно выбрасывая бутылки в траву, пока нас не обнаружил командир.\n\nНо Митхаг – это не армия, здесь мы можем полностью отдаться удовольствию. Не хотите ли вы разделить с нами бутылку вина и отпраздновать мой день рождения?\nЕсли вы согласны, приходите вечером, когда луна взойдет над башней, на крышу общежития. Вы, возможно, заметили, что здесь открываются лучшие виды митхага.\n\n\n\nАльва"
  },
  Mail_21468_Name = {
    Text = "Поделиться вином.."
  },
  Mail_21468_Sender = {Text = "Альва"},
  Mail_21469_Desc = {
    Text = "Пляж, пляж, пляж, пляж!\nЭй? В начале письма нужно указывать получателя — как неудобно! Ведь Страж даже на записках, приклеенных к холодильнику, не пишет получателя!\nСегодня у Ореты... эээ... сколько ей лет? В общем, день рождения Ореты!\nВот сокровища Ореты! Все это тебе! Отвези Орету на пляж, пожалуйста, пожалуйста, пожалуйста!\nСчитайте это подарком на день рождения Ореты, хорошо?~\n\nОрета"
  },
  Mail_21469_Name = {Text = "Пляж!"},
  Mail_21469_Sender = {
    Text = "Аурита"
  },
  Mail_21470_Desc = {
    Text = "Уважаемый:\n\nВ прошлом, когда я жил с сестрой на пустынной планете, мы всегда обнимались и получали энергию от одного растения, чтобы отметить день нашего рождения.\nТе дни были горькими, но теперь, вспоминая о них, я чувствую радость и тепло.\nСегодня снова день нашего рождения. Если возможно, могу ли я предложить обмен: песню на одну веточку?\nСладкую веточку, которая представляет мое прошлое с сестрой и мое будущее с вами...\n\nТинкерт"
  },
  Mail_21470_Name = {
    Text = "Песня дня рождения"
  },
  Mail_21470_Sender = {Text = "Тинкт"},
  Mail_21471_Desc = {
    Text = "С благословения судьбы, Страж Университета Мисаг, мудрый и добродетельный повелитель:\nБудьте здоровы!\nНесколько дней назад я заметил грузовики, заезжающие в конюшню университета, где привезли породистую теплокровную лошадь. Вспомнил, как во время нашей последней задачи расследования вы упоминали, что у вас не было опыта верховой езды. Теплокровные кобылы послушны и идеальны для новичков.\nСкакать на лошади, преследуя восход и Закат, — это самые приятные моменты в моей памяти. Если пожелаете, я с радостью разделю с вами это удовольствие.\n\nОргр"
  },
  Mail_21471_Name = {
    Text = "Тёплоокровная лошадь.."
  },
  Mail_21471_Sender = {Text = "Ожье"},
  Mail_21472_Desc = {
    Text = "Календарь старого государства сильно отличается от того, что ныне используется в Лондиниуме.\nЯ родился в пятый день полных звёзд второго летнего месяца; выбор сегодняшней даты для празднования — результат вычислений руководителя лаборатории.\nКогда старое государство ещё существовало, верховный жрец устраивал всё. После великого жертвоприношения начинались всенародные торжества и семидневные каникулы.\nХоть я этого и не просил, у меня нет причин препятствовать распространению веселья.\nСегодня не выходной день в Мисагарде, и обязанности Хранителя тайн не предполагают регулярных дней отдыха.\nОднако если подать заявку на выходной под предлогом празднования моего дня рождения, полагаю, администрация не посмеет возразить.\nПроведи спокойный послеобеденный день.\n\nТуру"
  },
  Mail_21472_Name = {
    Text = "День рождения.."
  },
  Mail_21472_Sender = {Text = "Тулу"},
  Mail_21473_Desc = {
    Text = "Страж:\n\nОрета сказала, что именинники всегда должны загадывать желания.\nА я как раз тот, кто никогда не загадывает желаний.\nПотому что мои мысли всегда сбываются. Это не удача, а скорее что-то вроде... предопределённого руководства?\nКак, например, прошлым месяцем, когда я вышел в море вместе с Хилестером, я снова «случайно» нашёл красивый ископаемый.\nМестные Граждане называют его «морской лилией». Его щупальца похожи на ветряную мельницу, лениво наслаждающуюся солнцем летнего полудня.\nХрупкий, красивый. Увидев его, я сразу вспомнил о тебе.\nНа этот раз я тоже не загадывал желание — \nты наверняка бы понравился, Правда?\n\nШань"
  },
  Mail_21473_Name = {
    Text = "Морская лилия.."
  },
  Mail_21473_Sender = {Text = "Санга"},
  Mail_21475_Desc = {
    Text = "Страж:\n\nВ прошлом, когда я плавал с Элтоном, он каждый год в этот день готовил целый стол блюд и просил меня «загадать желание».\nПрежде чем прийти сюда, я не понимал, что такое «желание». Сейчас я не знаю, какое у меня может быть «желание»...\nВозможно, найти «желание» тоже может стать «желанием»?\n\nХилестер"
  },
  Mail_21475_Name = {
    Text = "Желание.."
  },
  Mail_21475_Sender = {
    Text = "Селеста"
  },
  Mail_21476_Desc = {
    Text = "Страж:\n\nОрета сказала мне, что ты исполнишь все желания, загаданные в день рождения, Правда?\nНе может быть, чтобы это было правдой. Исполнить желания всех людей — слишком большая неприятность для тебя.\nНо если бы можно было загадать желание... Я хотела бы, чтобы Тинкерт получил более широкую сцену.\nЭто будет слишком сложно исполнить? Э-э... тогда, тогда пусть будет: «В течение следующего года на моем столе больше не появится сельдерей», хорошо?\n\nФейнт"
  },
  Mail_21476_Name = {
    Text = "Желание.."
  },
  Mail_21476_Sender = {Text = "Фэйнт"},
  Mail_21477_Desc = {
    Text = "Дорогой Страж:\n\nРасскажу тебе один секрет: этот день рождения на самом деле выдуманный. Что касается моей истинной даты рождения... пусть она растворится в ветре.\nПосле болезни, брат всегда в день моего рождения просил слугу тайно приготовить для меня маленький торт.\nНе было песен о дне рождения, не было благословений, словно празднование дня рождения было чем-то постыдным.\nСейчас всё иначе, я могу гулять под солнцем, могу громко петь, а также отмечать свой день рождения.\nЭто всего лишь небольшие радости, но они заставляют меня чувствовать ностальгию.\nБлагодарю вас, Страж.\n\n(Конечно, если бы вы и все остальные были со мной немного строже, ещё строже... это было бы идеально.)\n\nРея"
  },
  Mail_21477_Name = {
    Text = "Один секрет.."
  },
  Mail_21477_Sender = {Text = "Ли"},
  Mail_21478_Desc = {
    Text = "Мой маленький·заключённый·пленник:\n\nЯ уже давно·давно·давно не хлестала плетью——\nЗаблокированная в этой скучной школе, заточённая в школьную форму, у Пандии внутри всё чешется, как будто шаловливый котёнок царапает. Но никто меня не понимает, а сотрудники ещё и всеми способами пытаются помешать мне «развлекаться»—— Это просто слишком!\nОй, сегодня — специальный день, очень подходящий для того, чтобы мой кнут снова коснулся мягкой кожи, позволь мне услышать интонацию боли... Если у тебя сегодня есть свободное время, то почему бы не прийти поговорить со мной?~?\n\nПандия"
  },
  Mail_21478_Name = {
    Text = "Хлесткий звук плети.."
  },
  Mail_21478_Sender = {
    Text = "Пандия"
  },
  Mail_21479_Desc = {
    Text = "<Big:Магистр магии Касия представляет юбилейное выступление, только сегодня!>\n\nЧтобы поблагодарить всех зрителей за поддержку и вдохновение на протяжении многих лет, магистр магии Касия проведет специальное юбилейное выступление сегодня вечером в 20:00 в центральном дворе Университета Мисаг (рядом со статуей Филипса)! Сегодня вас ждет более яркая сцена, более захватывающее шоу и — самое главное — невероятная магия, которая заставит вас усомниться в собственных глазах! Даже если бы сам Мозг Мисаг присутствовал, он был бы поражен этой магией. Это гарантирует магистр Касия!\n\nУникальная возможность, только сегодня, и совершенно бесплатно! Магистр Касия ждёт вас!\n\n<Small:PS: Если во время или после выступления возникнут симптомы усталости или снижения настроения, магистр Касия ответственности не несет.>\n<Small:PPS: Вся информация о Мозге Мисаг будет соответствовать реальным обстоятельствам на момент мероприятия. Магистр Касия сохраняет за собой право на интерпретацию программы и её эффектов.>"
  },
  Mail_21479_Name = {
    Text = "Мастер магии Касия: юбилейное выступление!"
  },
  Mail_21479_Sender = {Text = "Касия"},
  Mail_21480_Desc = {
    Text = "Эй, сегодня же мой день рождения, где Подарок?\nЧто, ты забыл подготовить...? Хм, я так и думала.\nВот, возьми этот календарь, там чётко написаны даты моего дня рождения, дня смерти, первого дня прихода в Мисаг, а также праздников Веселья и Сатурналий... Эти праздники мы должны отмечать вместе, так что в следующий раз не забудь!\n\nЕсли ты снова забудешь... Похоже, я всё равно ничего не смогу с тобой поделать, хм.\nНо всё равно не смей забывать.\n\nАгриппа"
  },
  Mail_21480_Name = {Text = "Эй.."},
  Mail_21480_Sender = {
    Text = "Агриппа"
  },
  Mail_21481_Desc = {
    Text = "Страж:\n\nЯ не хотел писать это письмо, но работа Эрики пошла не так, как надо, и её тревожные сигналы не прекращались, пока я писал это письмо.\nДень рождения для меня не имеет никакого значения, вероятность успеха эксперимента не выше, чем в любой другой день, и мой Индекс гнозиса не изменится из-за этой даты. Но Рамона настояла на том, чтобы сделать этот день моим «днём отдыха» и ограничила мне доступ в лабораторию сегодня.\nМне некуда больше идти, поэтому сегодня я проведу полную проверку твоих предыдущих отчётов.\nПожалуйста, приходи в архив после ужина. Обрати внимание, не надо пытаться принести какой-либо торт в архив, бумажные документы очень хрупкие.\n\nдора"
  },
  Mail_21481_Name = {
    Text = "После ужина.."
  },
  Mail_21481_Sender = {Text = "Долл"},
  Mail_22435_Desc = {
    Text = "Дорогой Страж:\nСначала я выбрал читать стихи в тихом кампусе на рассвете, потому что в это время меньше прохожих и легче погрузиться в Мир поэзий. Позже я полюбил светлеющее утро, хрустальные капли росы и мелодичное пение птиц.\nК моему удивлению, многие преподаватели и студенты незаметно следили за мной и создали клуб любителей поэзии. Сегодня мой день рождения, и как раз в этот день нарциссы в клубе готовы распуститься. Используя это как повод, они решили организовать встречу для обсуждения стихов и совместного чтения в кампусе.\nВ такой атмосфере я надеюсь, что вы сможете присоединиться к нам и разделить эту радость. \n\nНифия"
  },
  Mail_22435_Name = {
    Text = "Приглашение на поэтический вечер"
  },
  Mail_22435_Sender = {
    Text = "Нимфея"
  },
  Mail_23897_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.0.21 мы скорректировали награды за первый проход сложности «Сложный» в режиме «Исследование», Уровни обычной и сложной сложности в бою «Погружение в сознание», а также интервалы I-IV между сменами для каждой границы в «Область тьмы». Подробные изменения доступны в «Объявление о онлайн поддержке V1.0.21».\n        Согласно вашим данным о прохождении расследований и испытаний, мы выдадим вам однократно все недополученные награды согласно новым правилам. Конкретную информацию смотрите во вложении."
  },
  Mail_23897_Name = {
    Text = "V1.0.21 корректировка компенсация за изменения"
  },
  Mail_23897_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_24199_Desc = {
    Text = "Уважаемый Страж:\nВ обновлении V1.0.24 мы вновь открыли пятую главу «Расследовательской операции», которая была временно закрыта в версии V1.0.16. Принцип справедливости соблюдён: компенсация рассчитана на основе изменений в наградах до и после корректировки, а также ваших записей о расследованиях. Ваша компенсация уже отправлена во вложение."
  },
  Mail_24199_Name = {
    Text = "Компенсация за повторное открытие пятой главы в версии V1.0.24"
  },
  Mail_24199_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_24200_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.0.24 мы снова открыли пятую главу «расследовательской операции», которая была временно закрыта в V1.0.16. Исходя из принципа справедливости, мы будем выдавать соответствующую компенсацию с учетом изменений в наградах до и после корректировок, а также на основе записей расследования каждого Хранителя тайн. По вашим записям расследования, вам компенсация не требуется."
  },
  Mail_24200_Name = {
    Text = "Компенсация за повторное открытие пятой главы в версии V1.0.24"
  },
  Mail_24200_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_24202_Desc = {
    Text = "Уважаемый Страж:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы обеспечить Хранителям тайн лучший игровой опыт в Университете Мисагард, приглашаем вас заполнить анкету. В благодарность за участие мы подготовили награду — «Серебряные ядра» × 200, которую можно получить после заполнения анкеты.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя тайн. Ваши отзывы обязательно сделают Университет Мисагард ещё лучше!\n        — Да укажет Серебряный ключ путь."
  },
  Mail_24202_Name = {
    Text = "Анкета по тестированию версии V1.0 ниже"
  },
  Mail_24202_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_24280_Desc = {
    Text = "Привет, Страж:\nВ рейтинге расследования за вчерашнее глубокое Вдаль от берегов в иллюзию вы получили {s1} ранг, заняв {s2} место. Титул расследования — «{s3}». Ниже указаны награды за ранг. Просим Хранителя тайн не забыть их проверить."
  },
  Mail_24280_Name = {
    Text = "Ежедневная награда за рейтинг в Глубоком погружении в иллюзию"
  },
  Mail_24280_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_24877_Desc = {
    Text = "Страж:\n\nКаждый мой день рождения — это самое великолепное собрание, где полно гостей и все веселятся.\nНо на этот раз у меня есть другие мысли — \nпосидев слишком долго в качестве хозяина, иногда хочется почувствовать себя гостем.\nБудет ли это снова изысканное собрание или обычный домашний ужин, решать тебе, как?\nОднако, если выберешь провести ещё одно собрание, не приглашай тех аристократов и знаменитостей.\nВ такой прекрасный день я не хочу носить маску улыбки.\n\n<Del:Дама в алом>Солер"
  },
  Mail_24877_Name = {
    Text = "Решать тебе.."
  },
  Mail_24877_Sender = {
    Text = "Сорель"
  },
  Mail_24878_Desc = {
    Text = "Носитель:\n\nСегодня день рождения Лили, и Агриппа сказал, что нужно «устроить большой переполох».\nРаньше мама праздновала день рождения Лили не так — мама надевала мне остроконечную шапочку, и мы вместе хлопали в ладоши и задували свечи.\nЛили не знает, как правильно поступить. Пожалуйста, Носитель, отдай приказ.\n\nЛили"
  },
  Mail_24878_Name = {
    Text = "Беспокойство.."
  },
  Mail_24878_Sender = {Text = "Лили"},
  Mail_25147_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.1.0 награды за очки этой недели в режиме «Иллюзорное Вдаль от берегов» были заменены новыми «Еженедельными испытаниями». Из соображений справедливости, мы компенсируем не полученные награды за очки этой недели тем Хранителям тайн, которые ранее разблокировали «Иллюзорное Вдаль от берегов», но не успели все получить до 5:00 15 января и вошли в игру до этого времени. Пожалуйста, проверьте вашу почту."
  },
  Mail_25147_Name = {
    Text = "V1.1.0 Иллюзорное Вдаль от берегов. Компенсация награды за эту неделю"
  },
  Mail_25147_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_25148_Desc = {
    Text = "Уважаемый Страж: \n        В обновлении V1.1.0 режим 'Фазовая игра (бета)' убран, заменён на 'еженедельные испытания', которые имеют тот же прогресс и награды, что и 'еженедельные испытания' в 'Глубоком погружении в иллюзию'. В соответствии с принципом справедливости мы компенсируем 1000 жемчужин эрозии тем Хранителям тайн, которые ранее разблокировали 'Фазовая игра (бета)', но не завершили или не получили награду за эту неделю и вошли в игру до 15 января в 5:00 (UTC+8). Пожалуйста, проверьте."
  },
  Mail_25148_Name = {
    Text = "Компенсация награды недели в режиме Фазовая игра (V1.1.0)"
  },
  Mail_25148_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_25414_Desc = {
    Text = "Уважаемый Страж:\n\nВес дня рождения для каждого человека различен. Но день рождения Хранителя тайн имеет огромное значение для всего Мисаг.\nЛеди Сильвия приготовила для вас праздничный ужин в зоне общежития, на который прибудут декан Холтер и лорд Декстер. Учитывая вашу духовную усталость, я уже подготовил для вас праздничный наряд, он висит в шкафу у входа, можете переодеться перед мероприятием.\nМне большая честь в этом году быть вашим напарником, и я надеюсь, что следующий год будет таким же.\nПусть Cеребряный ключ освещает ваш путь.\n\nP.S. Индивидуальный маленький торт уже доставлен Эрикой в вашу комнату в общежитии.\n\nГотов быть вашим вечным напарником, Рамона"
  },
  Mail_25414_Name = {
    Text = "День рождения.."
  },
  Mail_25414_Sender = {
    Text = "Рамона"
  },
  Mail_34667_Desc = {
    Text = "Уважаемый(ая) @1@2:\n\nМир забыл твоё имя.\nПоэтому я пробуждаю тебя — так же, как ты пробудил(а) меня. До того как придёт Конец, ты и я будем идти по этому миру, свидетельствовать, а затем помнить и забывать.\nСегодня — день твоего рождения, случайно найденная страница среди рассыпанных Осколков Памяти. В честь этого — вздох и Благословление.\nКогда мир вспомнит твой истинный облик, что ты почувствуешь? Или же по-прежнему ничего не узнаешь и ничего не ощутишь?\nЯ жду твоего ответа на Краю небытия.\n\n@2"
  },
  Mail_34667_Name = {
    Text = "День рождения.."
  },
  Mail_35231_Desc = {
    Text = "Уважаемый Страж:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы обеспечить Хранителям тайн лучший игровой опыт в Университете Мисагард, приглашаем вас заполнить анкету. В благодарность за участие мы подготовили награду — «Серебряные ядра» × 200, которую можно получить после заполнения анкеты.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя тайн. Ваши отзывы обязательно сделают Университет Мисагард ещё лучше!\n        — Да укажет Серебряный ключ путь."
  },
