  Mail_36235_Desc = {
    Text = "Уважаемый Страж:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы обеспечить Хранителям тайн лучший игровой опыт в Университете Мисагард, приглашаем вас заполнить анкету. В благодарность за участие мы подготовили награду — «Серебряные ядра» × 200, которую можно получить после заполнения анкеты. Срок заполнения анкеты — до 4 апреля, 9:00. Пожалуйста, заполните вовремя.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя тайн. Ваши отзывы обязательно сделают Университет Мисагард ещё лучше!\n        — Да укажет Серебряный ключ путь."
