  },
  Mail_36235_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_36865_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.2.4 мы изменили награды за еженедельные испытания в «Глубоком погружении в иллюзию», больше не предоставляя награды «Р-Жемчужина», «Кристалл мимикрии» и «розовый золотой ваучер». Соблюдая принцип справедливости, для Хранителей тайн, которые разблокировали «Иллюзорное Вдаль от берегов» до обновления, но не получили все награды за эту неделю и вошли в игру до 5:00 11 марта, мы компенсируем недополученные награды «Р-Жемчужина», «Кристалл мимикрии» и «розовый золотой ваучер» за эту неделю. Пожалуйста, проверьте их."
  },
  Mail_36865_Name = {
    Text = "V1.2.4 еженедельные испытания: компенсация наград"
  },
  Mail_36865_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_36866_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.2.4, после прохождения обычного режима сознательного плавания «Кровь и Песок», «Искажённое ядро», «Желание рыцаря» добавлены новые ключевые приказы: «Рёв крови и песка», «Кратковременная вечность», «Последняя клятва». Для Хранителей тайн, которые завершили указанные миссии в обычном режиме до обновления, мы вышлем соответствующие ключевые приказы. Пожалуйста, проверьте их."
  },
  Mail_36866_Name = {
    Text = "V1.2.4 Повторная выдача ключевого приказа для сознательного плавания"
  },
  Mail_36866_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_36867_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.2.4 количество уникальных материалов для улучшения навыков и мимикрических кристаллов, дроп которых происходит из «сверхопытного существа», было увеличено. В целях справедливости, для Хранителей тайн, которые получили награду за эту неделю до обновления, мы выдадим дополнительные мимикрические кристаллы равной ценности согласно рекомендуемому уровню пройденных этапов. Пожалуйста, проверьте полученное."
  },
  Mail_36867_Name = {
    Text = "V1.2.4 компенсация за награды сверхопытного существа"
  },
  Mail_36867_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_36871_Desc = {
    Text = "Уважаемый Страж:\nЗа прохождение максимальной сложности в 'Иллюзорное Вдаль от берегов' вчера вы получите следующие награды. Пожалуйста, проверьте их."
  },
  Mail_36871_Name = {
    Text = "Ежедневная награда за Сон-иллюзию"
  },
  Mail_36871_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_39293_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.2.7 после прохождения обычного режима в сюжетных главах «Сознательное плавание: Как песнь резьбы», «Потомки бледных» и «Шаг от» добавлены новые ключевые приказы «Объятия, разъедающие кости», «Озёрная ретроспектива» и «Переход через врата отката». Для Хранителей тайн, которые завершили вышеуказанные главы в обычном режиме до выхода обновления, мы отправим соответствующие ключи. Пожалуйста, проверьте их."
  },
  Mail_39293_Name = {
    Text = "V1.2.7 ключевой приказ для сознательного плавания восстановлен"
  },
  Mail_39293_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_39548_Desc = {
    Text = "Дорогой Страж:\n\nДля вечной жизни празднование дня рождения кажется излишним. В сравнении с бескрайним потоком времени, ваши человеческие воспоминания, которые вы считаете незабываемыми или яркими, кажутся... несущественными.\nНо вы создали бесчисленные праздники и церемонии, чтобы отметить эти «несущественные моменты». Конечно, это одна из причин, почему люди вызывают у меня интерес. Вы действительно очаровательны.\nОднако наша встреча не относится к этим «несущественным» мгновениям, ведь ты отличаешься... И я с нетерпением жду, какой шторм эта «особенность» может вызвать в будущем.\nИтак, прости за многословие... Сегодня мой день рождения, и я хочу воспользоваться правом именинника.\nЧто от тебя требуется — это разгадать загадку, которая ждёт тебя в моей спальне. Приходи туда сегодня ночью в полночь.\n\nВанда"
  },
  Mail_39548_Name = {
    Text = "Права именинника.."
  },
  Mail_39548_Sender = {Text = "Ванда"},
  Mail_39549_Desc = {
    Text = "Сегодня день рождения господина Морфи — день рождения должен сопровождаться банкетом и празднованием!\nЛюди из отдела логистики справились неплохо, но они действительно не умеют разыгрывать представления, всё делали скрытно — я давно заметила, как они заносили украшения для торта в хранилище пробуждения. Эм... ты ведь не будешь наказывать этих сотрудников? Они действительно отлично поработали, просто не смогли сохранить сюрприз...\nНа этом закончу писать, кажется, кто-то ищет меня, чтобы выйти — они лучше не обсыпают меня глупыми цветными бумажками.\nКстати, когда будут резать торт, ты будешь там?\n\nМорфи"
  },
  Mail_39549_Name = {
    Text = "День рождения.."
  },
  Mail_39549_Sender = {Text = "Мёрфи"},
  Mail_43571_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.2.10 в мероприятии [Туманное путешествие] добавлены награды за выполнение задач [Завершите главу 1 основной линии расследования «Тайны восточного округа» на сложности] и [Завершите главу 2 основной линии расследования «Во имя восковых фигур» на сложности] : [Серебро] × 1000. Хранителям тайн, которые уже получили награды за вышеуказанные задачи до обновления, мы предоставим соответствующие сердечники. Пожалуйста, проверьте."
  },
  Mail_43571_Name = {
    Text = "V1.2.10 Восстановление наград за Туманное путешествие"
  },
  Mail_43571_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_43821_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.3.0 в «отчёт о действиях» на этапах 1/2/3/4/5/6 были добавлены награды в виде опыта хранителя тайн в размере 500/1000/1500/2000/2500/3000 соответственно. Для тех хранителей тайн, которые уже получили все эти награды до обновления, мы вышлем соответствующий опыт. Пожалуйста, проверьте."
  },
  Mail_43821_Name = {
    Text = "Отчёт о действиях V1.3.0: восстановление опыта"
  },
  Mail_43821_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_44571_Desc = {
    Text = "Уважаемый Страж:\n«Пастух душ» завершится 18 апреля в 9:00 «GMT+8». После окончания акции соответствующие входы будут закрыты, включая Путь к святилищу, Ярмарку благотворительности святилища и другие. Билеты на благотворительную распродажу, которые не были использованы вовремя, исчезнут автоматически. Страж, не забудьте вовремя приобрести товары на Ярмарке благотворительности святилища до завершения акции."
  },
  Mail_44571_Name = {
    Text = "Акция «Пастух душ» вскоре подойдет к концу"
  },
  Mail_44571_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_44690_Desc = {
    Text = "Привет, Страж:\nВы выполнили задание внешнего агента вчера во время глубокого погружения в иллюзию, расследование титула было «{s1}». Ниже указаны награды за ранг, Страж, пожалуйста, не забудьте их проверить."
  },
  Mail_44690_Name = {
    Text = "Награда за ранг агентов глубокого погружения в иллюзию"
  },
  Mail_44690_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_44831_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.3.0 добавлены новые ключевые приказы «Истинное лицо серого тумана», «Победа розы» и «Памятный кадр лета» после прохождения обычного режима Оперативной записи «Призрак дождливого города», «Воспевание розы» и «Магия историй». Для Хранителей тайн, которые завершили вышеуказанные главы в обычном режиме до выхода обновления, мы вышлем соответствующие ключевые приказы. Пожалуйста, проверьте."
  },
  Mail_44831_Name = {
    Text = "Особая операция V1.3.0: повторный выпуск ключевого приказа"
  },
  Mail_44831_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_44836_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.3.0 мы увеличили награды за 1 победу и 3 победы в еженедельных испытаниях «Иллюзорное Вдаль от берегов»: «Доверенность» ×1. Для Хранителей тайн, которые уже получили указанные награды до обновления, мы отправим соответствующее количество «прокси-учетных данных». Пожалуйста, проверьте."
  },
  Mail_44836_Name = {
    Text = "V1.3.0 восстановление еженедельных наград за испытания"
  },
  Mail_44836_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_44837_Desc = {
    Text = "Уважаемый Бледный Посланник:\n\nСегодня несколько детей принесли мне букет цветов и сладости, и только тогда я вспомнил, что более ста лет назад по календарю Гонса, в этот день я получил дар жизни от Отца Бога и пришел в этот мир. Это было так давно, воспоминания о детстве уже стерлись, но запах ладана в церкви Бендоцары все еще остается в моей памяти, не исчезая. Даже если церковь все еще стоит, рецепт ладана уже не тот, что был раньше.\n\nПрости, ностальгия не была целью моего письма. Я приготовил чайную церемонию с помощью сладостей, которые принесли дети, и надеюсь, что ты придешь и поделишься со мной — не ради празднования моего дня рождения, а ради празднования каждого дня жизни, каждого дня надежды.\n\nКогда у тебя день рождения? Пожалуйста, обязательно расскажи мне об этом после чашки чая.\n\n\n\nСальвадор"
  },
  Mail_44837_Name = {
    Text = "Бледный посланец.."
  },
  Mail_44837_Sender = {
    Text = "Сальвадор"
  },
  Mail_44843_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.3.0 мы убрали привилегию «Основных заданий»: удвоение опыта Хранителя тайн в «Глубоком погружении в грёзы» и «Фазовых шахматах (бета)». Приносим извинения. В качестве компенсации мы будем ежедневно начислять «Опыт Хранителя тайн» × 240 всем, кто приобрёл «Основные задания» текущего сезона, до завершения текущего сезона «Семестровых заданий». Пожалуйста, проверьте."
  },
  Mail_44843_Name = {
    Text = "Повторная выдача наград за основную тему в версии 1.3.0"
  },
  Mail_44843_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_47305_Desc = {
    Text = "Уважаемый Страж:\nВчера при глубоком погружении в иллюзию вы прошли максимальную Сложный «{s1}».\nВчера в фазовом поединке вы получили титул «{s2}», ни одной победы.\nНа основе вышеуказанных результатов вызова, вы получите следующие жемчужины эрозии в качестве награды. Пожалуйста, не забудьте проверить их."
  },
  Mail_47305_Name = {
    Text = "Награда за дуэль глубокого погружения с жемчужиной растворения"
  },
  Mail_47305_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_47306_Desc = {
    Text = "Уважаемый Страж:\nВ ходе вчерашнего глубокого погружения в иллюзию вы получили титул «{s1}».\nВ ходе вчерашнего фазового поединка вы получили титул «{s2}», без победных раундов.\nС учетом результатов вышеуказанных вызовов, вы получите следующее дополнительное вознаграждение, пожалуйста, проверьте."
  },
  Mail_47306_Name = {
    Text = "Дополнительная награда за глубокую дуэль"
  },
  Mail_47306_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_47307_Desc = {
    Text = "Уважаемый Страж:\nВ ходе вчерашнего Глубокого погружения в иллюзию вы получили титул «{s1}».\nВ ходе вчерашнего фазового поединка вы получили титул «{s2}» и одержали победы в поединке.\nУчитывая результаты этих вызовов, вам полагаются следующие дополнительные награды. Пожалуйста, проверьте свои награды."
  },
  Mail_47307_Name = {
    Text = "Дополнительная награда за глубокую дуэль"
  },
  Mail_47307_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_47308_Desc = {
    Text = "Уважаемый Страж:\nВчера в Глубоком погружении в иллюзию вы завершили на максимальной сложности «{s1}».\nВчера в фазовом поединке вы получили титул «{s2}» и одержали победы в поединках.\nС учетом результатов всех этих вызовов, вы получите следующие жемчужины эрозии в качестве награды. Пожалуйста, не забудьте проверить их."
  },
  Mail_47308_Name = {
    Text = "Награда за дуэль глубокого погружения с жемчужиной растворения"
  },
  Mail_47308_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_48005_Desc = {
    Text = "Дорогой Страж:\n\nПростите за Беспокойство, надеюсь, мой ужасный почерк не испортит ваше настроение, я действительно плохо умею писать......\nЯ пишу это письмо, чтобы сообщить вам, что, кажется, настал мой день рождения. В связи с этим я приготовил несколько маленьких печений и надеюсь, что вы тоже их попробуете.\nЧестно говоря, я не уверен, правильная ли это дата. После заражения растворением следы моего существования исчезают один за другим. Мисс Дора спросила меня, каково это — осознавать, что все вокруг тебя забывают?\nЭто трудно описать...... Это похоже на то, будто ты стоишь в полной темноте на краю светящейся реки, люди на другой стороне реки разговаривают Близкий Близкий друг с другом, заняты своими делами, проходят мимо меня. Я могу только наблюдать за ними, но не могу издать одну точку звука.\nЭто чувство глубокого одиночества. К счастью, вы не среди этих людей.\nПо крайней мере, вы помните мою историю, верно?\n\nP.S. Прилагаю двенадцать маленьких печений.\n\nМейсон"
  },
  Mail_48005_Name = {
    Text = "Прошу прощения за Беспокойство.."
  },
  Mail_48005_Sender = {Text = "\"24\""},
  Mail_48145_Desc = {
    Text = "Уважаемый Страж:\nАкция «Множественное исцеление» завершена, теперь оставшиеся у Хранителя тайн валюты мероприятия «Пазл памяти» будут возвращены по бесконечному курсу обмена «Анализ личности». Просим Хранителей тайн проверить свои счета."
  },
  Mail_48145_Name = {
    Text = "Восстановление памяти через пазлы"
  },
  Mail_48145_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_48156_Desc = {
    Text = "Уважаемый Страж:\nВчера во время глубокого погружения в иллюзию вы получили титул «{s1}».\nВчера в фазовом поединке у вас не было победных матчей.\nНа основании результатов вышеуказанных вызовов вы получите следующее дополнительное вознаграждение. Пожалуйста, не забудьте проверить."
  },
  Mail_48156_Name = {
    Text = "Дополнительная награда за глубокую дуэль"
  },
  Mail_48156_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_48157_Desc = {
    Text = "Уважаемый Страж:\nВчера в Глубоком погружении в иллюзию вы прошли максимальную Сложный «{s1}».\nВчера в фазовом поединке у вас не было ни одной победы.\nНа основании вышеуказанных результатов вызова вы получите следующую награду жемчужинами эрозии, пожалуйста, проверьте."
  },
  Mail_48157_Name = {
    Text = "Награда за дуэль глубокого погружения с жемчужиной растворения"
  },
  Mail_48157_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_48914_Desc = {
    Text = "Уважаемый Страж:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы обеспечить Хранителям тайн лучший игровой опыт в Университете Мисагард, приглашаем вас заполнить анкету. В благодарность за участие мы подготовили награду — «Серебряные ядра» × 200, которую можно получить после заполнения анкеты. Срок заполнения анкеты — до 28 октября, 9:00. Пожалуйста, заполните вовремя.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя тайн. Ваши отзывы обязательно сделают Университет Мисагард ещё лучше!\n        — Да укажет Серебряный ключ путь."
  },
  Mail_48914_Name = {
    Text = "Анкета для оценки пользовательского опыта версии V1.6.3"
  },
  Mail_48914_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_48915_Desc = {
    Text = "Уважаемый Страж:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы обеспечить Хранителям тайн лучший игровой опыт в Университете Мисагард, приглашаем вас заполнить анкету. В благодарность за участие мы подготовили награду — «Серебряные ядра» × 200, которую можно получить после заполнения анкеты. Срок заполнения анкеты — до 30 сентября, 9:00. Пожалуйста, заполните вовремя.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя тайн. Ваши отзывы обязательно сделают Университет Мисагард ещё лучше!\n        — Да укажет Серебряный ключ путь."
  },
  Mail_48915_Name = {
    Text = "Анкета по исследованию пользовательского опыта версии V1.6.1"
  },
  Mail_48915_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_49931_Desc = {
    Text = "Уважаемый Страж:\nАкция «Плотские желания» завершена. Теперь «Семя изобилия» меняются на каждую по «Купон розового золота» × 20. Пожалуйста, не забудьте проверить."
  },
  Mail_49931_Name = {
    Text = "Вернуться долга Семя изобилия"
  },
  Mail_49931_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_50344_Desc = {
    Text = "Росточек:\n\nВетер принёс мне твой аромат — он стал слаще, чем когда мы только познакомились.\nТы выросла в моей любви, вскормлена и созрела в моей любви… совсем как пчёлка и мёд.\nСегодня особенный день — не придёшь ли повидаться со мной?\nЯ уже, как ты просила, послушно ждала очень долго… Пора бы мне получить награду, не так ли?\n\nТайис"
  },
  Mail_50344_Name = {
    Text = "Сладкий, как мёд.."
  },
  Mail_50344_Sender = {Text = "Таис"},
  Mail_51376_Desc = {
    Text = "Уважаемый Страж:\nАкция «Магия историй» завершена, теперь оставшееся у Хранителя тайн «Путешествующее вдохновение» будет конвертировано по курсу 60 банкнот с розой за каждую. Пожалуйста, не забудьте проверить."
  },
  Mail_51376_Name = {
    Text = "Улетучивающееся вдохновение собирается"
  },
  Mail_51376_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_51777_Desc = {
    Text = "Уважаемый Страж:\nАкция «Магия историй: повтор» завершена. Теперь «Путешествующее вдохновение» меняется на каждую по «Купон розового золота» × 25. Пожалуйста, не забудьте проверить."
  },
  Mail_51777_Name = {
    Text = "Улетучивающееся вдохновение собирается"
  },
  Mail_51777_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_53149_Desc = {
    Text = "Я давно решил посвятить каждый день своей жизни тому единственному... как искупление за мои глупые поступки.\nДень рождения моего ничтожного тела не заслуживает упоминания и не стоит внимания.\nСегодняшний день не отличается от любого другого дня в прошлом или будущем, я по-прежнему направлюсь в молельню.\nНо если вы хотите, чтобы я сегодня покинул молельню как Гость Мисаг, я не стану противиться воле хозяина.\nЕсли пожелаете увидеть мою молитву, буду рад приветствовать вас... с почтением.\n\nМириам"
  },
  Mail_53149_Name = {
    Text = "Целый день тренировок.."
  },
  Mail_53149_Sender = {
    Text = "Мириам"
  },
  Mail_53151_Desc = {
    Text = "Уважаемый Страж:\nАкция «Жертвоприношение бездне» завершена. Теперь «Слеза жреца», «Кровь жреца» и «Мозг жреца» меняются на каждую 100 штук на «Купон розового золота» × 2500. Пожалуйста, не забудьте проверить."
  },
  Mail_53151_Name = {
    Text = "Валюта акции \"Жертвоприношение бездне\"восстановление"
  },
  Mail_53151_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_53152_Desc = {
    Text = "Уважаемый Страж: \nАкция «Пастырь душ» завершена. Теперь оставшиеся у Хранителя тайн «билеты на благотворительную распродажу» меняются по курсу 120 штук на «Купон розового золота» × 5000. Пожалуйста, не забудьте проверить."
  },
  Mail_53152_Name = {
    Text = "Сбор билетов на благотворительную распродажу"
  },
  Mail_53152_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_53153_Desc = {
    Text = "Уважаемый Страж: \n Акция «Пламенное пиршество» завершена. Теперь «Настоящая берцовая кость», «Круглолистный аммонит» и «спиральные руины» меняются на каждую 80 штук за «Печать тысячи ликов» × 1. Пожалуйста, не забудьте проверить."
  },
  Mail_53153_Name = {
    Text = "Валюта мероприятия горящего пира"
  },
  Mail_53153_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_53869_Desc = {
    Text = "Уважаемый Страж: \n Акция «Послание розы» завершена. Теперь «Веер из перьев духовной птицы» меняется на каждую по «Купон розового золота» × 50. Пожалуйста, проверьте."
  },
  Mail_53869_Name = {
    Text = "Колдовской веер из перьев для восстановления"
  },
  Mail_53869_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_54803_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.5.1 мы увеличили награды за «Серебро» для уровней Хранителя тайн с 21 по 80, а также добавили награду в виде «расследовательского значка» × 1000 за выполнение заданий на этапах «Мастерства царства»I~V. Хранителям тайн, которые уже получили вышеупомянутые награды до обновления, мы выполним компенсацию в виде соответствующего «сердечника из серебра» или «расследовательского значка». Пожалуйста, проверьте."
  },
  Mail_54803_Name = {
    Text = "Дополнительное возмещение за награды в руководстве V1.5.1"
  },
  Mail_54803_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_55168_Desc = {
    Text = "Уважаемый Страж:\nАкция «Перед тем как весна увянет» завершена. Теперь «Весёлые стихи», «Меланхоличная поэзия» и «Поэма сожаления» меняются на каждую 200 штук на «Купон розового золота» × 5000. Пожалуйста, проверьте."
  },
  Mail_55168_Name = {
    Text = "Поэтический переработка"
  },
  Mail_55168_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_56101_Desc = {
    Text = "Страж {Male=господин,Female=госпожа}:\n\nСегодня в полночь роза расцвела под птичьим пением ранней весны.\nОна должна была остаться нераспустившимся весенним бутоном, но в День святого Валентина, в день моего рождения, она распустилась не в свой сезон.\nЯ вспомнил Западный Остров одиночества. Каждый год в мой день рождения улицы Западного острова всегда были полны жизни. Я слышал звук распускающихся цветов, слышал застенчивые признания людей. Но я уже давно не имел возможности прикоснуться к ним... до сегодняшнего дня.\nВы верите в совпадения, Страж? Я думаю, что совпадение — это язык, а роза — это метафора. Сегодня, в саду Мисаг, эта роза распустилась, её лепестки широко раскрылись, словно трогательное стихотворение.\nПоэтому сегодня, Страж... Не хотите ли вы присоединиться ко мне и посмотреть на распускание этой розы?\nЯ и цветок ждём вашего прихода.\n\nОрла"
  },
  Mail_56101_Name = {
    Text = "Роза распускается весной.."
  },
  Mail_56101_Sender = {Text = "Орля"},
  Mail_57328_Desc = {
    Text = "Уважаемый Страж:\nАкция «Звёзды на своих местах» завершена. Теперь «бездушный зародыш», «безжелательный эмбрион» и «безграничное зародышевое ядро» меняются на каждую по «Купон розового золота»× 40. Пожалуйста, проверьте."
  },
  Mail_57328_Name = {
    Text = "Восстановление эмбриона"
  },
  Mail_57328_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_57414_Desc = {
    Text = "Уважаемый Страж:\nАкция «Справочник Детектива» завершена. Теперь «решающие фишки» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, проверьте."
  },
  Mail_57414_Name = {
    Text = "Вернуться долга фишек"
  },
  Mail_57414_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_58253_Desc = {
    Text = "Уважаемый Страж: \nАкция «Пастырь душ: повтор» завершена. Теперь «билеты на благотворительную распродажу» хранителя будут обменены по курсу 200 штук на «Купон розового золота» × 5000. Пожалуйста, не забудьте проверить."
  },
  Mail_58253_Name = {
    Text = "Сбор билетов на благотворительную распродажу"
  },
  Mail_58253_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_58690_Desc = {
    Text = "Уважаемый Страж:\nАкция «бесформенная симфония» завершена. Теперь «Возвышенная музыкальная глава» Хранителя тайн меняется на каждую по «Купон розового золота» × 40. Пожалуйста, проверьте."
  },
  Mail_58690_Name = {
    Text = "Возвышенная музыкальная глава: восстановление"
  },
  Mail_58690_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_61154_Desc = {
    Text = "Уважаемый Страж: \nАкция «Пламенное пиршество: повтор» завершена. Теперь «Настоящая берцовая кость», «Круглолистный аммонит» и «спиральные руины» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_61154_Name = {
    Text = "Воспламеняющаяся валюта группового праздника для возврата"
  },
  Mail_61154_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_61155_Desc = {
    Text = "Уважаемый Страж:\nАкция «Всестороннее исцеление: повтор» завершена. Теперь оставшиеся у Хранителя тайн игровые деньги «пазл памяти» меняются по курсу «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_61155_Name = {
    Text = "Восстановление памяти через пазлы"
  },
  Mail_61155_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_62392_Desc = {
    Text = "Страж:\n\nМоё исполнение когда-то служило перед троном императора и вызывало восхищение у множества людей. Однако все эти восторженные слова не имеют для меня никакой ценности, я стремлюсь лишь к высшему совершенству музыки.\nПо сравнению с выступлениями на величественных и помпезных мероприятиях, мне больше нравится играть в одиночестве в лесу, где никого нет рядом. Это приносит мне больше расслабления.\nРаньше я не любил, чтобы кто-то подслушивал мои тренировки, ведь они были всего лишь черновиками на пути к совершенству, бессмысленными набросками.\nНо с тех пор, как я узнал о вас и нашёл вас, вся моя музыка обрела смысл.\nИменно вы дали мне величайшую и благородную музыку, спасли меня от заблуждений, даже если сами того не осознаёте...\nСегодня мой день рождения, я уже почти забыл о нём, но теперь хочу отметить своё возрождение и того, кто подарил мне новую жизнь.\nКстати, недавно появились новые партитуры, и я хотел бы пригласить вас оценить их. Простите за моё запоздалое появление, моя роль пока ещё не позволяет мне показаться перед коллегами в Мисаге, поэтому могу передать вам это Приглашение только после того, как горизонт поглотит последние лучи заката.\nВечером сегодня в лесу позади школы я устрою особый концерт, а зрительное место будет всего одно.\nЖду с нетерпением вашего прибытия.\n\nХамлин"
  },
  Mail_62392_Name = {
    Text = "Секретный музыкальный концерт.."
  },
  Mail_62392_Sender = {
    Text = "Гамельн"
  },
  Mail_65350_Desc = {
    Text = "Уважаемый Страж:\nАкция «Когда растает снег» завершена. Теперь оставшиеся у Хранителя тайн валюты акции «замороженный бутон», «серебряный бутон» и «солнечный бутон» будут возвращены по пропорции «Купон розового золота» × 40 за каждую, пожалуйста, не забудьте проверить."
  },
  Mail_65350_Name = {
    Text = "Восстановление почки цветка"
  },
  Mail_65350_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_65441_Desc = {
    Text = "Уважаемый Страж:\nАкция «Жертвоприношение бездне: повтор» завершена. Теперь «Слеза жреца», «Кровь жреца» и «Мозг жреца» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_65441_Name = {
    Text = "Валюта акции \"Жертвоприношение бездне\"восстановление"
  },
  Mail_65441_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_65442_Desc = {
    Text = "Уважаемый Страж:\nАкция «Ворота всех явлений» завершена. Теперь оставшиеся у Хранителя тайн игровые деньги «Конечный указатель» будут выкуплены по коэффициенту «Купон розового золота» × 40. Пожалуйста, Страж, не забудьте проверить."
  },
  Mail_65442_Name = {
    Text = "Сбор конечного указателя"
  },
  Mail_65442_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_67147_Desc = {
    Text = "Страж:\n\n    Размерности Вселенной для меня не являются единственными, за Вратами предела можно увидеть тысячи миров и бесчисленные существа. Там превосходят все фантазии и математическую логику, поэтому невозможно Подтвердить дату «Дня Рождения».\n    Поэтому давай назовём момент нашей первой встречи именно этим временем. В шкале времени твоего континуума сегодня должно состояться де ритуал, посвящённый мне, чтобы исполнить моё желание.\n    Так что переступи порог серебряного ключа и приди ко мне. Я научу тебя... некоторым знаниям об истинном источнике, принадлежащим Вселенной. Сегодня ночью миллионы светящихся тел засияют для нас двоих.\n    Я жду тебя за Вратами предела.\n\nТави"
  },
  Mail_67147_Name = {
    Text = "За порогом Серебряных врат.."
  },
  Mail_67147_Sender = {
    Text = "Тавиль"
  },
  Mail_67933_Desc = {
    Text = "Я почувствовал твое мгновенное замешательство — величайшее создание, на которое даже взглянуть почти невозможно, как же можно его ранить? Но тебе это удалось.\nЕще один взгляд рушится. Прочные доспехи под натиском множества фрагментов покрылись царапинами и трещинами.\n%player%, несокрушимой является лишь твоя твердая воля."
  },
  Mail_67933_Name = {
    Text = "Прояснить путь сквозь замешательство"
  },
  Mail_67933_Sender = {
    Text = "Алистер"
  },
  Mail_67934_Desc = {
    Text = "Твои конечности дрожат, %player%. Ты едва можешь стоять. Страх сжал тебя, оставив пустоту в голове и не давая контролировать своё дыхание... но ты всё равно поднял Cеребряный ключ перед собой.\nСреди всех прекрасных качеств человека храбрость — самое благородное. Перед лицом безвременья и хищников мы поднимали каменные молоты и копья. Теперь, стоя перед богами, ты остаёшься таким же.\nЦивилизация человечества была построена на храбрости и будет продолжать жить благодаря бесконечной силе духа."
  },
  Mail_67934_Name = {
    Text = "Гимн храбрости, звучащий в дрожь"
  },
  Mail_67934_Sender = {
    Text = "Алистер"
  },
  Mail_67935_Desc = {
    Text = "Мы говорили об этом мире. Ты сказал, что не любишь его. Здесь царят интересы, интриги, обман, убийства, и даже без растворения и богов он уже был изранен и Обрыв. После пробуждения Якутск, в твоей короткой памяти, ты видел хаос и ужас, превосходящие Раствориться. \n Но когда Создатель поднял Своё острие, ты всё равно стал щитом перед этим миром. Аннигиляция была волей богов, а ты отказался принять её. \n Я понимаю, %player%. Ни один Страж не может не ненавидеть этот мир, но в то же время нет ни одного, кто бы по-настоящему его не любил. Ведь среди всей этой грязи мы видели сияние, подобное сердечнику из серебра. \n Долг Хранителей тайн — защищать эти слабые огоньки, чтобы они существовали вечно."
  },
  Mail_67935_Name = {
    Text = "Человеческий дух бессмертен"
  },
  Mail_67935_Sender = {
    Text = "Алистер"
  },
  Mail_67936_Desc = {
    Text = "Впервые увидев Раствориться, впервые столкнувшись с правдой о растворении, впервые почувствовав звук богов... В моей долгой жизни я пережил множество моментов упавший духом, не знаю, что могу сделать, не понимаю смысла всех этих жертв и усилий — но ничто из этого не сравнится с тем, с чем ты сейчас сталкиваешься.\nЛюди именно таковы: снова и снова поднимаются после упавший духом и продолжают двигаться вперед.\nВ конце пути может оказаться абисс, но всегда найдутся те, кто захотят взглянуть."
  },
  Mail_67936_Name = {
    Text = "Упавший духом, и затем Новое Ювенильный"
  },
  Mail_67936_Sender = {
    Text = "Алистер"
  },
  Mail_67937_Desc = {
    Text = "Границы размерности открылись, и я снова могу связаться с тобой.\nВзгляд этого измерения по сравнению с тем, что видишь ты, необычайно слаб. Возможно, это из-за того, что тебя здесь нет. Пожертвовав почти всем, я устранил Его.\nТрудно представить, с чем ты сейчас сталкиваешься. Но независимо ни от чего, воля к аннигиляции — я буду противостоять ей вместе с тобой. Это клятва каждого Мисаг.\nЯ рад снова быть рядом с тобой.\nПусть Cеребряный ключ освещает путь."
  },
  Mail_67937_Name = {
    Text = "Сражаться плечом к плечу, вновь"
  },
  Mail_67937_Sender = {
    Text = "Неизвестно отправитель"
  },
  Mail_67938_Desc = {
    Text = "Безумие, слово лёгкое, даже приятное.\nХаотичная вселенная породила хаотическую цивилизацию. Хаос — это Правда этого мира. Следовать хаосу, наслаждаться сумасшествием — как же это легко. В сравнении с этим, ясность и противостояние кажутся такими трудными. Ты принесёшь в жертву всю радость и жизнь, только чтобы найти недосягаемый Лечение.\nНо ты всё ещë выбираешь ясность, %player%. Потому что мы рождены не для того, чтобы быть рабами.\nТы показал Ему, %player% — Его создание, Его Фрагмент, никогда не желавший быть слепым и глупым рабом. Ты противостоишь Ему, побеждаешь Взгляд божества за взглядом, выбирая защиту этого несовершенного и нелёгкого мира.\nВ этом выборе у тебя уже имеется вечная свобода."
  },
  Mail_67938_Name = {
    Text = "Ты никогда не соглашался быть слепым и глупым рабом"
  },
  Mail_67938_Sender = {
    Text = "Алистер"
  },
  Mail_67939_Desc = {
    Text = "Я ощутил обрушение чьего-то взгляда. Я ощутил твою пронзительную боль.\nЭто ответственность, запечатленная в титуле Хранителя тайн. Путь, который ты выбрал, в тысячу раз труднее того, что прошел я. Не у всех хватит смелости встретиться лицом к лицу с высшими богами. Твоя храбрость вызывает у меня чувство глубокого уважения и восхищения.\nКакую боль принесет тебе мощь Создателя, я даже не могу вообразить. То, что я чувствую, это лишь малая часть того, что ты выдерживаешь. Я — бесполезный пленник Чёрного бассейна, %player%. Я больше не способен участвовать в твоем противостоянии с Созданием, могу лишь оставаться связанным с тобой через мои ощущения. Это станет последним и важнейшим заданием в моей карьере.\nНа этом одиноком пути Мисаг будет всегда рядом с тобой, независимо от того, видишь ли ты это или нет."
  },
  Mail_67939_Name = {
    Text = "Горе не сможет сломить тебя"
  },
  Mail_67939_Sender = {
    Text = "Алистер"
  },
  Mail_67940_Desc = {
    Text = "Я услышал шёпот Воли Безграничного — величественные цивилизации, человеческие радости и печали, бесчисленные люди, окружающие тебя и удаляющиеся от тебя, всё это никогда не существовало.\n За бесчисленные дни и ночи в Чёрном бассейне эти видения внушали мне Страх. Деревья пускают корни в землю, затем тянутся вверх, навстречу солнцу — память, память является нашей почвой, из которой мы растём, стоим и куда в конце вернёмся. Я боюсь потерять землю, плавать в ничто, без начала и конца.\n Благодарю вас, %player%. Я полагаю, я стал свидетелем великого противостояния. Это была битва человека против богов. Это была битва защиты против уничтожения.\n Это была битва памяти против забвения.\n Ты добился этого, %player%. Ты совершил то, что никто не мог даже вообразить. Ты получил непреодолимую силу через память. Ты сражался за память.\n Ты нашёл своё солнце в этой вечной почве."
  },
  Mail_67940_Name = {
    Text = "Чтобы помнить, сражайся"
  },
  Mail_67940_Sender = {
    Text = "Алистер"
  },
  Mail_68825_Desc = {
    Text = "Уважаемый Страж:\nАкция «Воскрешение бога-короля» завершена. Теперь оставшиеся у Хранителя тайн валюты «утомленные мысли», «печаль и тревога» и «радостные мысли» меняются по пропорции 1 к «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_68825_Name = {
    Text = "Воскрешение бога-короля: обмен валюты"
  },
  Mail_68825_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_68826_Desc = {
    Text = "Уважаемый Страж:\nАкция «Плотские желания: повтор» завершена. Теперь «Семя изобилия» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_68826_Name = {
    Text = "Вернуться долга Семя изобилия"
  },
  Mail_68826_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_68898_Desc = {
    Text = "Самый дорогой Носитель:\n\nКак универсальная Служанка, Гарен может запомнить множество важных дат для взрослых, начиная от дней проведения банкетов, дней рождения и памятных дат, вплоть до дня первой покупки питомца. И никогда не допустит ни одной ошибки. Но для самой Гарен особенным днем является только этот.\nОчень давно, когда Гарен была служанкой во дворце, она впервые попросила у повара кусочек десерта, который знатные люди не доели, чтобы использовать его как праздничный торт на свой день рождения. Повар сильно отругал ее и бросил торт ей в лицо. Тогда она подумала: «Как же это вкусно — торт. Я должна найти очень хорошего хозяина, который будет давать мне торт каждый мой день рождения».\nСейчас у меня есть особенно элегантная и благородная госпожа Солер и вы, особенно добрый Носитель. Моя давняя мечта сбылась! Но человек всегда становится все более требовательным... нет, прогрессивным. Теперь моя мечта — быть рядом с хозяином каждый свой день рождения, а также получать блестящие подарки каждый год.\nПосле всего этого вы обязательно что-нибудь приготовите для меня, Правда? Правда-Правда?\n\nВаша всегда покорная Служанка\nГарен"
  },
  Mail_68898_Name = {
    Text = "Год за годом.."
  },
  Mail_68898_Sender = {Text = "Карен"},
  Mail_68899_Desc = {
    Text = "Маленький саженец:\n\nНаблюдая за твоим ростом все это время, я становлюсь все более уверенной в том, что выбрала тебя и помогала тебе, это было самым правильным решением, которое я когда-либо принимала.\nЯ ощущаю радость урожая, все доверие и любовь, которые я вложила, принесли мне сладкие плоды, ты дал мне надежду и будущее.\nТеперь я могу отбросить навязчивую идею размножения и сосредоточиться на наслаждении плодами любви, которые лежат за пределами размножения.\nЭтому миру больше не нужна королева Арам, но возможно, он сможет вместить желание обычной женщины иметь рядом с собой любимого человека в день рождения.\nКак у самых обычных пар, мы можем вместе ходить за продуктами, готовить еду, а может быть, и многое другое, чего я еще не испытывала. Милый, сможешь ли ты повести меня через этот теплый и спокойный день рождения?\n\nТайис"
  },
  Mail_68899_Name = {
    Text = "Обычная жизнь.."
  },
  Mail_68899_Sender = {Text = "Таис"},
  Mail_68900_Desc = {
    Text = "Страж:\n\nМастер Касия — величайший исполнитель в мире, способный идеально имитировать любую эмоцию, но человеческие чувства — это загадка, которую невозможно понять, независимо от усилий.\nЯ спрашивал множество людей, и никто не мог объяснить природу чувств, пока я не обратился к дора. Она рассказала мне о науке под названием психология, которая, даже если не позволяет прочувствовать то же самое, даёт возможность освоить все теории эмоций.\nЭто так интересно! Неужели сомнение, которое так долго мучило Касию, наконец-то разрешится?\nКстати, я пришёл сказать тебе, что на этой неделе буду присутствовать на твоих занятиях по психологии, а Касия станет твоей соседкой по парте. Ты хочешь помочь мне восполнить пропущенные темы, партнёр~\nАх да, ещё одно: сегодня мой день рождения, так что здесь я хочу быть счастливым, и ты тоже должна радоваться, верно?\nЕсли это очень радостное событие, можно устроить праздник в школе, и я сделаю кампус таким красивым, словно это сновидение!\n\nКасия"
  },
  Mail_68900_Name = {
    Text = "Психология.."
  },
  Mail_68900_Sender = {Text = "Касия"},
  Mail_68901_Desc = {
    Text = "Уважаемый Бледный Посланник:\n\nБлагодарю тебя за помощь и заботу в течение этого года. Твоя искренняя доброта к другим людям так высока, как учила нас Отца богов. Даже если наши встречи нечасты, каждый раз, когда мы видимся, я чувствую себя как Старый Близкий Близкий друг, с которым знаком уже давно, и это приносит мне радость и спокойствие.\nХотя день рождения не является особенным днем, он все же дает нам повод встретиться и обменяться теплыми словами. Я не могу представить никого другого, с кем бы хотел провести этот день.\nЕсли тебе интересно, я хотел бы пригласить тебя попробовать мое новое увлечение — рыбная ловля. Конечно, не для того, чтобы готовить или есть рыбу, а просто для того, чтобы наслаждаться процессом ожидания чудесных подарков судьбы. Я хочу поделиться с тобой этим спокойным ощущением, находясь на природе, спокойно сидя на берегу озера.\nДва старых друга, две удочки — это будет прекрасный день.\n\nСальвадор"
  },
  Mail_68901_Name = {
    Text = "Новое увлечение — рыбная ловля.."
  },
  Mail_68901_Sender = {
    Text = "Сальвадор"
  },
  Mail_68902_Desc = {
    Text = "Носитель:\n\nВ этом году на день рождения Ай Джис и Дженкинс подарили мне стеклянный ветряной колокольчик, очень похожий на Орету.\nЯ повесила его на окно в своей комнате, и когда дует ветер, он издаёт приятные звуки, напоминающие мне о том, как Матушка рассказывала мне истории, обнимая меня у окна.\nНе беспокойтесь, Носитель, хотя я каждый день скучаю по матери, но с вами и всеми остальными рядом, Лили не чувствует себя одинокой.\nСейчас Лили научилась читать истории сама, и каждый вечер, когда оранжевое солнце освещает дом, Погоня за светом падает на ветряной колокольчик и отбрасывает колеблющиеся тени на страницы книги, делая комнату тёплой и уютной.\nЛили так нравится в такие моменты задумываться, глядя на облака и ветряной колокольчик в закатных лучах, это так красиво, так красиво.\nЕсли сегодня у вас будет время, попробуйте тоже провести время вместе со мной, задумавшись.\n\nЛили"
  },
  Mail_68902_Name = {
    Text = "Стеклянный ветряной колокольчик.."
  },
  Mail_68902_Sender = {Text = "Лили"},
  Mail_68903_Desc = {
    Text = "Малыш:\n\nХотя этот особенный день был установлен в честь того человека, я вынужден признать, что скидочный день является крайне привлекательным предложением как для покупателей, так и для продавцов.\nВ прошлом году на мой день рождения количество заказов в лавке \"Утешитель\" почти сравнялось с продажами за полгода. Особенно те товары, которые я выставил как праздничные акции, были раскуплены мгновенно. Не знаю, стоит ли говорить, что Гость Мисаг слишком заботятся о моем бизнесе, или даже самые осмотрительные следователи не могут устоять перед скидками.\nВ любом случае, чтобы продолжить радовать обе стороны, в этом году мой день рождения снова будет отмечаться скидочной акцией, которая проводится только один раз в год и имеет большую силу. Желающим приобрести товары следует поторопиться. Помоги мне хорошо распространить информацию о ней в Мисаг, чтобы было легче запомнить, назовем этот день Днем Двойного Десятка.\nКроме того, я оставил для тебя кое-что интересное, обязательно приходи ко мне пораньше.\n\nДавдейл"
  },
  Mail_68903_Name = {
    Text = "День скидок.."
  },
  Mail_68903_Sender = {
    Text = "Даффодил"
  },
  Mail_68904_Desc = {
    Text = "Во имя великой судьбы, Страж Университета Мисаг, мудрый и благородный повелитель:\nДа будет всё благополучно!\nЕсли говорить о том, что каждый рыцарь желает в своей жизни следовать за великим повелителем, то моя жизнь как рыцаря уже не имеет ни малейшего сожаления.\nМоя жизнь была наполнена не только удачей, но и множеством трагедий и кровавых жертв. Я знаю, что многие люди в Мисаге когда-то проявляли сочувствие из-за этого.\nНо сравнивать страдания — это не нужно. В Мисаге уже слишком много несчастных людей, и в этом мире, полном страданий, проливать кровь ради защиты — это не повод для печали. Напротив, независимо от прошлого или настоящего, я всегда этим горжусь и всегда готов пожертвовать собой.\nНо госпожа Ротань сказала, что мой ежедневный серьёзный вид выглядит слишком утомлённым, и предложила мне хорошо провести время в день рождения. Она пригласила Дженкинса научить меня играть в игры, чтобы вернуть Детство.\nК моему стыду, в детстве я был занят тренировками и действительно не имел опыта в играх. Не ожидал, что такая игра, которую, как говорят, могут освоить пятилетние дети, окажется настолько сложной. Похоже, что вне пути рыцаря мне ещё многое предстоит узнать.\nЕсли у вас сегодня есть свободное время, не могли бы вы прийти и поиграть с нами? Я заметил, что Дженкинс после десяти побед уже начал скучать. Если бы вы были здесь, это точно добавило бы интереса игре.\n\nОргр"
  },
  Mail_68904_Name = {
    Text = "Сложность игры.."
  },
  Mail_68904_Sender = {Text = "Ожье"},
  Mail_68905_Desc = {
    Text = "Эй:\n\nС этим ежедневником, уверен, ты наверняка не забыл день рождения благородного Хозяина лабиринта в этом году.\nЯ разрешаю тебе прийти в мою комнату и преподнести Подарок, а заодно преданно служить мне в этот день.\nНапример, такие дела как чистка зубов, умывание, переодевание, прием пищи, а также уборка комнаты, смена постельного белья – как вы это называете? Генеральная уборка!\nДа, всю эту генеральную уборку я поручаю тебе. Я сыт по горло домашними делами, и сегодня, во что бы то ни стало, я хочу вернуться к тем временам, когда жил в Риме, наслаждаясь жизнью, где всё подают на протянутую руку, а еда сама плывет в рот.\nСегодня никто не заставит меня сделать хоть что-то самому, никто!\n\nАгриппа"
  },
  Mail_68905_Name = {
    Text = "Вернуться в прошлое.."
  },
  Mail_68905_Sender = {
    Text = "Агриппа"
  },
  Mail_68906_Desc = {
    Text = "Страж:\n\nКак быстро летит время! Не думала, что жизнь, которую я считала вечной, теперь почти не вспоминаю.\nСейчас я знаю все маленькие тортики в столовой как свои Часть 5 пальцев. Как бы я их ни поторапливала, эти бесполезные повара всё равно ничего нового не придумают.\nПоэтому в новом году моя Карта гастрономических удовольствий станет больше и шире. Поставлю себе небольшую цель: попробовать все кондитерские Лентиниена.\nЧто касается почётной работы по доставке и очередям — она как всегда остаётся за тобой! Получив доверие этой девушки, не стоит слишком радоваться, просто с благодарностью восхваляй имя этой дамы.\nОднако, если говорить о тех глупых поварах, в них всё же есть немного искренности. Из их тихих разговоров я уже услышала, что они, кажется, готовят огромный десятиэтажный торт — ха, они так и не научились скрывать сюрпризы.\nХотя идея довольно банальная. Возможно, на этот раз я смогу пригласить больше людей. Например, новых друзей, которых завела за этот год.\nКак первый Близкий Близкий друг в Мисаге, я разрешаю тебе сделать первый разрез на моём торте.\n\nМорфи"
  },
  Mail_68906_Name = {
    Text = "Десятиэтажный торт.."
  },
  Mail_68906_Sender = {Text = "Мёрфи"},
  Mail_68907_Desc = {
    Text = "Дорогой Страж:\n\nС вашим умом, вы наверняка уже узнали из чудесных архивов Мисаг следующее — сегодня особенный день в жизни «Удачного детектива».\nРождение, победа в первой игре в 21 очко, сотый выигрыш на скачках, раскрытие первого дела о закрытом убийстве и неудача, которая привела к смерти — всё это случилось в этот магический день, 6 июня.\nКак насчёт партии в бридж вдвоём? Давайте сделаем этот день ещё более памятным, что скажете?\n\nЛекк"
  },
  Mail_68907_Name = {
    Text = "Сыграем партию?"
  },
  Mail_68907_Sender = {
    Text = "Райкер"
  },
  Mail_68908_Desc = {
    Text = "Это письмо не приветствие, а предупреждение — не надо пытаться контролировать меня, не надо пытаться надеть на меня цепи.\nЯ принадлежу только себе.\nЯ не такой, как тот, кто выглядит как я, и всё ещё наивно надеется на людей и мир.\n\nЯ убью любого, кто осмелится стать моим «Хозяином». Сказано — сделано.\n\nH"
  },
  Mail_68908_Name = {
    Text = "Я принадлежу.."
  },
  Mail_68908_Sender = {
    Text = "Илот: Верига"
  },
  Mail_68909_Desc = {
    Text = "Страж:\n\nМожет быть, я уже рассказывал вам о своей любви к воде. В отличие от шумного мира людей, подводный мир такой тихий и спокойный.\nЯ когда-то плыл среди водорослей и кораллов, вёл диалог с косяками рыб. Чем дальше от поверхности, тем темнее становятся цвета воды. Когда мягко толкает волна, и смотришь снизу на небо, пятна света создают гипнотические картины, которые кажутся мне самыми красивыми пейзажами.\nЗнаете ли вы, что некоторые морские существа могут запоминать лица людей? Когда вы снова приходите, эти «друзья» радостно приближаются, чтобы поприветствовать вас. Например, я знаю умного маленького осьминога и нежно-жёлтую морскую рыбку.\nВ день моего рождения я снова скучаю по подводному миру. Не знаю, согласитесь ли вы пойти со мной на подводное плавание. Я искренне надеюсь показать вам этот мир тишины и познакомить с моими удивительными друзьями.\n\nНифия"
  },
  Mail_68909_Name = {
    Text = "Водный мир.."
  },
  Mail_68909_Sender = {
    Text = "Нимфея"
  },
  Mail_68910_Desc = {
    Text = "Страж:\n\nС тех пор как ты прибыл в Мисаг, я привык обращаться с тобой по методу воспитания младенцев во всем, что тебя касается. Исходя из твоих обычных реакций, твоя слабость значительно превзошла мои ожидания.\nОднако как твой наставник и первый опекун, я рад, что за этот год случаев, когда мне приходится разбирать твои проблемы и устранять последствия, становится все меньше. Хотя твое полное невежество в начале учебы вызывало отчаяние, скорость твоего роста действительно заслуживает быть названной как результат сочетания таланта и усилий.\nПоздравляю тебя с тем, что ты стал полноценным Хранителем тайн, оправдав мои ожидания.\nВ такой ничем не примечательный день, как мой день рождения, я уже подготовил для тебя Подарок успешного Хранителя тайн — тренировочный сценарий, который когда-то использовал Алистер. Как тебе такое? С нетерпением ждешь его?\nНе спрашивай, почему это я готовлю тебе Подарок. В дни, когда нельзя войти в лабораторию, надо чем-то заняться, не так ли?\nКогда будешь готов, приходи ко мне в тренировочную комнату.\n\nДора"
  },
  Mail_68910_Name = {
    Text = "Подарок.."
  },
  Mail_68910_Sender = {Text = "Долл"},
  Mail_68911_Desc = {
    Text = "Страж:\n\nГод для танцора – это лишь десятки тысяч вращений и прыжков, замена старых танцевальных туфель; всё кажется неизменным и в то же время другим.\nПо сравнению с прежним уединением, на протяжении этого года у меня был верный зритель и несколько неловкий партнер.\nКогда ты садишься в танцевальном зале, я чувствую, как тело становится легче, словно в детстве, когда я только начинала танцевать, наполненное какой-то страстью и энергией.\nВозможно, я не так чиста и благородна, как мне кажется: отдавая всю жизнь танцу, я всё ещё надеюсь на твое внимание и аплодисменты.\nВ день рождения погода была хорошей, и я предчувствовала ясное небо ночью. Мой самый страстный зритель, мой особенный партнер, готов ли ты присоединиться ко мне в лесу с красивым озером и исполнить танец луны и звёзд?\n\nЛиз"
  },
  Mail_68911_Name = {
    Text = "Персональный танцевальный партнёр.."
  },
  Mail_68911_Sender = {Text = "Лиз"},
  Mail_68912_Desc = {
    Text = "Страж:\n\nС того дня, как я возродился, люди Мисаг очень помогли мне. Возможно, я всё ещё не привык к чувству сотрудничества, но по крайней мере, когда я иду с вами, я могу доверить свою спину вам. Это чувство... тоже неплохо.\nБольшая часть моей жизни была наполнена уроном и предательством, я всегда считал борьбу с этим смыслом моих сражений, пока в моей жизни больше ничего не осталось, мой взгляд уже не мог оторваться от мести.\nТеперь, следуя за вашими шагами, я понял, что бой может иметь много значений помимо урона и мести, даже как говорит Ротань, бой может быть просто боем.\nЯ научился наслаждаться радостью боя, ощущением полноты и удовольствием быть храбрым воином.\nЕсли мой бой сможет принести больше, то я буду наслаждаться этой славой.\nА ты, независимо от того, сейчас или в будущем, я обещаю, что мой клинок никогда не будет направлен против тебя.\n\nШило"
  },
  Mail_68912_Name = {
    Text = "Смысл боя.."
  },
  Mail_68912_Sender = {Text = "Илот"},
  Mail_68913_Desc = {
    Text = "Дорогой Страж:\n\nЧестно говоря, у меня никогда не было особых мыслей о днях рождения и желаниях. Когда я ещё была «нормальной», самыми большими моими мечтами были сытость, теплое одеяние, своевременная оплата аренды и забота о Дженкинс. Сейчас, проживая ещё один год спокойно и наблюдая за шалостями Дженкинс, я уже чувствую себя счастливой.\nПризнаться, перед Дженкинс я всегда строю из себя старшую сестру, чтобы её воспитывать, но перед тобой я постоянно доставляю тебе много проблем, даже сама не помню, какой из моих личностей это делала.\nТвоя постоянная доброта и Выдержка заставляют меня чувствовать себя и теплее, и стеснительнее. Возможно, это первый раз в моей жизни, когда кто-то относится ко мне с такой терпимостью и заботой. Я искренне благодарна и признательна тебе.\nВ этом году я испекла большой торт для всех, по рецепту, который мне дала тётя из бывшей ткацкой фабрики. Хотя он не сравнится с работой поваров, этот особенный вкус очень нравится мне и Дженкинс. На этот раз не будет проблем с материалами, и каждый сможет наесться досыта. Обязательно приходи и попробуй.\nЯ уже уговорила других меня честно отпраздновать день рождения. Они точно, точно больше не доставят тебе никаких проблем!\nЕсли можно, призови меня, когда тебе это нужно, будь то стирка, уборка или укладка вещей — я в этом хороша. Я бы хотела иметь возможность отплатить за твою доброту.\n\nМейсон"
  },
  Mail_68913_Name = {
    Text = "Вознаградить.."
  },
  Mail_68913_Sender = {Text = "\"24\""},
  Mail_68914_Desc = {
    Text = "Страж:  \n\nКак человек, ответственный за принятие чужих желаний, я никак не могу привыкнуть к тому, что в свой день рождения мне самому нужно загадывать желание. Для меня это как будто ничего не значит, у меня нет ничего, чего бы я хотел.\nдора сказала мне, что мне нужно найти то, чего я действительно желаю глубоко в своем сердце, и спросить себя, для чего я делаю все это.\nЯ долго думал об этом и понял, что на самом деле хочу, чтобы желания всех тех, кто приходит ко мне, исполнились. Если продолжать размышлять, то, вероятно, мне нравится видеть их радостные лица, когда их желания сбываются, и как они искренне окружают меня, благодарят и хвалят меня как богиню.\nдора сказала, что это мое желание быть признанным и стать полезным человеком. Я думаю, она права.\nНо она также сказала, что ценность человека не должна определяться другими, и нет такого понятия, как \"полезное\" дело. Важно только следовать своему сердцу, даже если это означает стать бесполезным в глазах других.\nНе зря дора всегда говорит такие мудрые вещи, но стать полезным или бесполезным... Кажется, я снова запутался...\nОднако, если следовать своему сердцу, возможно, я все же хочу быть полезным человеком. Если в мой день рождения я смогу увидеть улыбки всех, это будет лучшим подарком, который я мог бы пожелать.\n\nХилестер"
  },
  Mail_68914_Name = {
    Text = "Полезный человек.."
  },
  Mail_68914_Sender = {
    Text = "Селеста"
  },
  Mail_68915_Desc = {
    Text = "Дорогой господин Страж:\n\nЯ уже давно привык к жизни, подобной существованию червей в канализации. Можно сказать, что это и есть моя Колесо Судьбы, я полностью принял её и с радостью обнял.\nХотя я всегда был благодарен вам за то, что вы позволили мне снова вкусить сладость свободы, но никто не может принять мои особые увлечения, и это вполне естественно. Ведь большинство людей здесь — добрые и мирные, они не могут понять, что мху, растущему во влажных углах, нужен не яркий Погоня за светом, а Мрак воздух.\nКроме вас, уважаемый добрый господин, только вы можете по-настоящему понять меня, помочь мне и сделать меня счастливым от души. Боль, которую вы мне дарите, настолько удовлетворяет и успокаивает, что позволяет мне ощутить своё существование.\nЕсли когда-то у меня не было никаких заветных желаний, которые я мог бы загадать на день рождения, то теперь я хочу следовать за вами и посвятить вам всё своё сердце и тело.\nКонечно, не будьте ко мне слишком добры. Презирайте меня, ругайте меня, бейте меня!\n\nРея"
  },
  Mail_68915_Name = {
    Text = "Намерение мха.."
  },
  Mail_68915_Sender = {Text = "Ли"},
  Mail_68916_Desc = {
    Text = "Дорогой мой щенок:\n\nЯ почти полюбил эти дни, когда мы играем с тобой в кошки-мышки, как в заезженных романах о героях, где праведный посланник всегда в последний момент останавливает коварный план злодея. Как трогательно и величественно.\nПросто видеть, как ты постоянно борешься впустую, вызывает непреодолимое желание смеяться.\nЭтот мир уже давно обречен, его нельзя спасти. Эта планета станет такой же мертвой, как и множество других планет, поглощенных ▼&#x5B▼87;&4;▼.\nЛадно, я поиграю с тобой. Внезапно сейчас я начинаю немного понимать интерес N: до наступления неизбежного конца любые действия фактически не имеют значения.\nВ день рождения твоего любимого учителя я все равно приготовил для тебя большой сюрприз. Надеюсь, что до завершения обратного отсчета дня рождения ты найдешь ту скрытую «бомбу».\nСколько еще удовольствия ты сможешь доставить мне, прежде чем мы полностью растаем?\n\n\n«дора»"
  },
  Mail_68916_Name = {
    Text = "Бомба-сюрприз.."
  },
  Mail_68916_Sender = {
    Text = "Долл: Преисподняя"
  },
  Mail_68917_Desc = {
    Text = "Страж:\n\nНедавно в высших кругах Лентиниена стало модным самим рисовать эскизы и заказывать уникальные украшения.\nЭти дамы, считающие себя большими знатоками искусства, сменили соревнование в размере драгоценных камней на соревнование в изяществе дизайна. Однако их попытки скрыть привлечение известных художников выглядят столь же очевидно, как пытаться спрятать что-то у всех на виду.\nБлагодаря этой моде, в мой список подарков на день рождения попало немало показных безделушек и драгоценностей, среди которых оказался прекрасный рубин цвета голубиной крови, которому не хватает подходящей оправы.\nЯ подумала, что вместо того чтобы обращаться к скучным старикам, лучше попросить моего рыцаря нарисовать для меня эскиз, наполненный искренним теплом, как Подарок. Как тебе такая идея?\nЯ с нетерпением жду твою работу и верю, что твой вкус окажется безупречным.\n\nСолер"
  },
  Mail_68917_Name = {
    Text = "Дизайн украшений.."
  },
  Mail_68917_Sender = {
    Text = "Сорель"
  },
  Mail_68918_Desc = {
    Text = "Страж:\n\nЕщё до нашей первой встречи, за тысячами дверей, я уже встречал множество одинаковых и разных тебя.\nЯ помню твою радость и Негодование, помню каждый твой выбор, помню, как ты продолжал идти в разных мирах.\nДля меня среди всех этих тебя ты самый особенный. Я давал названия и номера наблюдаемым мною мирам, и мир, где ты находишься, я назвал Надеждой, это имя появилось в день нашей встречи.\nВ этот день, именуемый Надеждой, возможно, тебе будет интересно взглянуть на другие миры, словно смотришь глазами вселенной. Я поведу тебя, чтобы показать всё, что я тихо наблюдал перед дверями.\nИ увидеть тебя моими глазами.\n\nТави"
  },
  Mail_68918_Name = {
    Text = "Другой ты.."
  },
  Mail_68918_Sender = {
    Text = "Тавиль"
  },
  Mail_68919_Desc = {
    Text = "Изначально простота Мисаг очень нравилась мне, но с приходом женщины по имени Мириам моя жизнь начала терять покой. \nЯ не отказываюсь тем, кто ищет убежище и стабильность, ведь в этом грязном мире стремление к утешению — это естественно и понятно. \nОднако я всегда был против того, чтобы выдавать себя за всемогущих богов, а после затопления Лимурии здесь и вовсе не нужно создавать нового высшего божества. \nВероятно, Мириам до сих пор не может преодолеть тени прошлого, поэтому она перенесла свои фанатичные обычаи в настоящее, привлекая ко мне внимание повсюду, где бы я ни находился на кампусе, что становится крайне раздражающим. \nСегодня мой день рождения, и я уверен, что эта женщина уже подготовила обширную церемонию, которая только вызывает у меня головную боль и шум в ушах, поэтому я не буду присутствовать там, чтобы избежать проблем. \nЕсли ты хочешь, можешь прийти по адресу, указанному в письме, и мы прогуляемся, чтобы успокоиться. \nПомни, не надо давать этой женщине Обнаружение об этом. \n\nТулу"
  },
  Mail_68919_Name = {
    Text = "Спрятаться от суеты.."
  },
  Mail_68919_Sender = {Text = "Тулу"},
  Mail_68920_Desc = {
    Text = "Каждый день я голоден, мне становится некомфортно, если я не пью кровь хотя бы на некоторое время. Но с тех пор как я попробовал твою кровь, обычная кровь кажется мне безвкусной, как воск. Вкус твоей крови каждый день манит меня, заставляя вспоминать его в горле. \n Я знаю, сколько крови можно выпить, высасывая человека до конца, и этот вкус исчезает мгновенно. Чтобы ты не умер слишком быстро, я научусь терпению, ждать следующего удовольствия, пока снова не смогу попробовать твою кровь. \n Ох, Боже, не верится, что я смог это сделать. Я даже сомневаюсь, не эволюционировал ли я. Учитывая моё Выдержка, хотя бы сегодня, в твой так называемый день рождения, позволь мне попробовать твою сладкую и вкусную кровь, только одну точку, хорошо? \n Я купил тебе питательные добавки на деньги, заработанные в клубе ТROUT, на этот раз ты точно не будешь страдать анемией. \n\n Юу Хаши, который долго голодал"
  },
  Mail_68920_Name = {
    Text = "Вкусная кровь.."
  },
  Mail_68920_Sender = {Text = "Увхаш"},
  Mail_68921_Desc = {
    Text = "Уважаемый Страж:\n\nЯ очень рад видеть ваш постоянный прогресс на тренировках в течение этого года. Скоро вы сможете превзойти меня, каким я был в молодости, и стать сильным солдатом. Для меня большая честь быть вашим инструктором.\nВ этот день рождения я получил пару отличных ботинок для альпинизма. Не знаю, есть ли у вас интерес присоединиться ко мне для пешего похода, чтобы проверить свои улучшенные физические способности, а также полюбоваться восходом солнца на вершине горы. Такие виды среди гор, удалённые от города, наверняка будут очень красивыми.\nКонечно, если добавить к этому пикник с ночёвкой в горах и бутылку крепкого алкоголя, это будет просто идеально.\n\nЭльва"
  },
  Mail_68921_Name = {
    Text = "Пешком по горам.."
  },
  Mail_68921_Sender = {Text = "Альва"},
  Mail_68922_Desc = {
    Text = "Партнёр:\n\nЗа этот год произошло много событий, возможно, для тебя это не было прекрасным временем школьной жизни.\nЯ признаю, что в прошлом году мои наставления часто были назойливыми, а забота недостаточно чуткой, и все тренировки выглядели как попытка ускорить рост ростков, заставив тебя принять на себя слишком тяжёлую ношу.\nНо я хочу, чтобы ты знал: ты всегда остаёшься самым важным человеком для меня. Помимо Хранителя тайн Мисаг, ты мой единственный партнёр.\nВозможно, сегодня, в день рождения, я могу позволить себе маленькую слабость, а ты можешь забыть обо всех обязанностях. Мы можем отбросить любые задания и тренировки, чтобы полностью расслабиться.\nВ парк развлечений в центре города? В театр? В универмаг или на уличный рынок... Как хочешь, я хочу по возможности возместить всё то, чего тебе не хватало.\nТакже я надеюсь, что этот день, когда можно ни о чём не беспокоиться, проведу с тобой. Все планы предоставлю тебе решать.\n\nРамона"
  },
  Mail_68922_Name = {
    Text = "День расслабления.."
  },
  Mail_68922_Sender = {
    Text = "Рамона"
  },
  Mail_68923_Desc = {
    Text = "Дорогой Страж:\n\nЗа время, проведённое мной среди людей, милые слуги каждый год в этот день устраивали для меня пышные празднества, всячески стараясь угодить мне.\nХотя это был самый обычный день, без каких-либо особенных событий, в их искренних улыбках день приобретал особое Очаровывание. В искусстве находить радость даже в горестях и создании из ничего, люди действительно преуспели.\nДаже в этой школе, где могила размещена прямо на территории кампуса, вы всё ещё можете так стойко создавать радость, что это вызывает у меня удивление.\nТолько вот подарки обычных людей настолько скучны, а так называемые вечеринки в честь дня рождения невероятно банальны – пошлость присуща большинству.\nЛишь ты, только мысли о тебе доставляют мне некоторое удовольствие, позволяя заново испытать радости прошлых времён.\nЯ приказываю тебе немедленно прийти в мою комнату и развлекать меня до рассвета. Если ты хорошо послужишь мне, возможно, позволю поцеловать мою руку.\n\nВанда"
  },
  Mail_68923_Name = {
    Text = "Команда.."
  },
  Mail_68923_Sender = {Text = "Ванда"},
  Mail_68924_Desc = {
    Text = "<Del:западный парень>страж молчания:\nСначала я не собирался писать такую сентиментальную чушь, но Ай Джис постоянно твердила что-то о памяти и значении, настояв, чтобы я написал тебе это письмо.\nИз уважения к Ай Джис я сделаю исключение. Итак, прошел уже год с тех пор, как я здесь, и в целом я доволен условиями проживания и едой в школе. Единственное - простыни в комнате слишком скользкие, из-за чего мне трудно привыкнуть ко сну. Разве вам не кажется, что только грубая хлопковая ткань действительно удобна для сна?\nЕсли говорить о чем-то, что можно улучшить, то еда в столовой слишком полезная. Хотя после нее сытно, но во рту как будто ничего нет, совсем не сравнить с уличной едой!\nПоэтому на свой день рождения в этом году я не собираюсь беспокоить поваров, а проведу вас в таинственный переулок Восточного района, где мы попробуем лотки, которые особенно рекомендую я и Браун. Обещаю, что вы сразу же будете покорены уличными вкусностями!\nКонечно, все расходы сегодня заплатит западный парень, ты не против, Правда?\n\nТвой Старый Близкий Близкий друг Дженкинс и Браун"
  },
  Mail_68924_Name = {
    Text = "Уличная еда.."
  },
  Mail_68924_Sender = {
    Text = "Дженкин"
  },
  Mail_68925_Desc = {
    Text = "Дорогой человек:\n\nКроме сестры, ты первый, кто искренне поддерживает меня. Благодаря твоим предыдущим советам, я уже выпустил серию альбомов с компанией звукозаписи, и скоро у меня будет личный концерт.\nЯ хочу провести свой первый концерт на этой планете в день своего рождения, чтобы отметить своё новое Начало здесь.\nНадеюсь, ты сможешь прийти и послушать моё выступление в полной мере. Я хотел бы пригласить тебя и сестру в качестве специальных гостей на последнем этапе, чтобы вы пели со мной мою новую песню. Как ты на это смотришь?\nКстати, не говори об этом моей сестре, ведь это также её день рождения, и я хочу сделать ей сюрприз.\nЧто касается желания, которое я договорился загадать на день рождения, я хочу, чтобы мой голос снова засиял на этой планете.\n\nТинкерт"
  },
  Mail_68925_Name = {
    Text = "Концерт.."
  },
  Mail_68925_Sender = {Text = "Тинкт"},
  Mail_68926_Desc = {
    Text = "Дорогой Страж:\n\nНезаметно пролетел ещё один год. Каждый день в Мисаге приносит мне огромную радость. Я счастлива проводить время с друзьями, играть, учиться и наслаждаться множеством вкусных блюд. Это самые счастливые моменты в моей жизни. Даже когда я немного нервничаю во время выполнения задач, вместе с друзьями в бою Ай Джис никогда не испытывает страха.\nМне очень неловко, что и в этом году я доставила вам много хлопот. Хотя часто это были шалости Дженкинс, она просто хотела сделать всех счастливыми. Надеюсь, вы не сердитесь на нас за нашу рассеянность и шалости.\nКстати о Дженкинс: в этом году она предложила провести соревнование по ловле светлячков в мой день рождения. Она подготовила множество прозрачных банок, говоря, что сделает из них множество светлячковых фонарей. В конце тот, чей Фонарь окажется самым ярким, получит титул главного мастера по ловле светлячков.\nХотя звание главного мастера звучит немного забавно, лес, полный светлячков летом, действительно прекрасен. Если у вас найдётся немного свободного времени среди ваших дел, мы будем рады, если вы присоединитесь к нам и отправитесь в лес полюбоваться этой красотой, похожей на звёзды.\n\nАй Джис"
  },
  Mail_68926_Name = {
    Text = "Соревнование по ловле светлячков.."
  },
  Mail_68926_Sender = {Text = "Айгис"},
  Mail_68927_Desc = {
    Text = "Страж! Несколько дней назад, когда Орета купалась в море, она встретила нового друга, который мог выпускать электричество! Он был круглым и плоским, как большая пицца! \n Орета попыталась с ним поздороваться, но внезапно почувствовала покалывание, и новый Близкий Близкий друг сразу уплыл. \n Когда Орета вернулась, дора сказала ей, что это был электрический скат, Орета не совсем поняла, но подумала, что новый Близкий Близкий друг очень крутой! В день рождения Ореты Страж может сопровождать её, чтобы забрать нового друга и жить вместе с её друзьями! То чувство покалывания Страж тоже точно оценит! \n\n Орета"
  },
  Mail_68927_Name = {
    Text = "Новый Близкий Близкий друг, который умеет стрелять молниями.."
  },
  Mail_68927_Sender = {
    Text = "Аурита"
  },
  Mail_68928_Desc = {
    Text = "Уважаемый Страж:\n\nДетские дни рождения для меня были временем строгих требований отца, когда нельзя было расслабиться ни на миг во время музыкальных тренировок.\nНельзя было позволить себе Надменность, легкомыслие или лень. За исключением маленького торта, который Матушка тайно готовила для меня, этот день был лишь очередной строгой беседой, указывающей на мои недостатки за прошедший год.\nДо сегодняшнего дня я уже не являюсь учеником музыки и благодаря вам могу прикоснуться к величественным вратам высшего музыкального храма. Но с детства воспитанные уроки не позволяют мне испытывать интерес к простым радостям жизни.\nТолько музыка, только исполнение для вас предначертанного судьбой requiem, является моей конечной целью в жизни, единственным моментом, когда я ощущаю смысл своего существования.\nЕсли вы согласитесь уделить мне время перед сном этой ночью, я готов играть для вас всю ночь ту музыку, что запечатлена в моей душе, до самого рассвета.\n\nХамлин"
  },
  Mail_68928_Name = {
    Text = "Желание музицировать.."
  },
  Mail_68928_Sender = {
    Text = "Гамельн"
  },
  Mail_68929_Desc = {
    Text = "Мальчишка:\n\nС тех пор как я оказался здесь, думал, что наконец избавился от той чопорной сумасшедшей женщины, но выяснилось, что у вас в этой дыре правил даже больше, чем у неё. Я уже давно забыл, что такое настоящая свобода!\nНельзя пить Прекрасное Прекрасное вино большими глотками, нельзя заигрывать с красавицами, нельзя веселиться на вечерних кострах, да и ваше жаркое намного хуже, чем в Филистиме! Не знаю, как вы вообще живёте такой пресной жизнью.\nНо сильный человек не станет жаловаться на условия. После моих завоеваний я снова стал великим лидером банды в вашем городе.\nПо случаю дня рождения великого Голиафа я милостиво приглашаю тебя на Роскошный Роскошный пир, который мои люди устраивают в мою честь. Здесь будет всё: отличное Прекрасное Прекрасное вино, вкусное Инкарнация и прекрасные женщины. Это точно расширит твой кругозор.\nВ знак уважения к нашим прежним отношениям я не прошу подарков. Просто приходи с уважением и благослови возрождение сильного.\nХорошенько свидетельствуй! В следующем году, и через год после этого, независимо от того, где я буду, я начну новый путь.\n\nГолиаф"
  },
  Mail_68929_Name = {Text = "Путь.."},
  Mail_68929_Sender = {
    Text = "Голиаф"
  },
  Mail_68930_Desc = {
    Text = "Страж: \n\nИзначально я никогда не думала праздновать день рождения этого ничтожного тела, считая его обычным днём духовных практик. Однако сегодня утром Король нашёл меня и издал указ, запрещающий мне заниматься чем-либо, связанным с Королём или практиками. Весь день я должна посвятить только себе.\nВпервые за многие дни и ночи Король проявил такую заботу обо мне, что я была крайне смущена и преисполнена благодарности. Но я уже давно посвятила всю свою жизнь Королю, и на мгновение даже растерялась, не зная, куда идти и что делать.\nПосле долгих размышлений единственное, что можно назвать лёгким сожалением, — это чувство вины перед Морфи. Даже ради восстановления родины я ни разу не пожалела о своём выборе, но осознаю, что не могу возместить свой долг перед ней и не могу ничего исправить.\nНо если у меня всё же есть что-то, чего я действительно хочу от всего сердца, то, возможно, это бесстыдно снова попытаться сделать то, что должна делать Матушка.\nЯ специально купила те сладости, которые она когда-то любила, пусть это будет искуплением для жалкой, недостойной матери. Не могли бы вы передать этот Подарок ей, но ни в коем случае не говорите, что он от меня. Скажите, что это вы подготовили.\nУмоляю вас согласиться, я буду безмерно благодарна.\n\nМириам"
  },
  Mail_68930_Name = {
    Text = "Возместить.."
  },
  Mail_68930_Sender = {
    Text = "Мириам"
  },
  Mail_68931_Desc = {
    Text = "Аха, после размышления с помощью моей мудрости, я полностью понял смысл дня рождения человека. Так называемый особенный день, предназначенный для кого-то одного, создан, чтобы дать возможность получить редкий шанс использования привилегий, шанс заполучить драгоценные предметы и право смело высказывать свои желания другим. \n Независимо от того, какие желания обычно не осмеливаются произнести или даже думать о них в обычные дни, в этот день есть шанс их исполнить. Ха, это просто более захватывающий и праздничный день, чем любой другой. \n Похоже, что за прошедшие годы я упустил так много возможностей для привилегий. Но, к счастью, благодаря моей долгой жизни, у меня еще будет множество дней рождения, чтобы загадывать желания. \n Так что, потребовать от всех людей провести со мной день рождения, устроив честный и веселый бой, должно быть легко выполнимым желанием, верно? \n\n Ротань"
  },
  Mail_68931_Name = {
    Text = "Привилегия именинника.."
  },
  Mail_68931_Sender = {Text = "Лотан"},
  Mail_68932_Desc = {
    Text = "Страж: \n\nС возрастом день рождения постепенно превращается в один из тех дней календаря, который можно легко пропустить мимоходом, и часто, когда вспоминаешь о нем случайно, день рождения уже прошел, как вода, тихо утекающая прочь.\nВ мире взрослых празднование дня рождения — это привилегия детей и скучающих людей, и я тоже стал скучным взрослым, который давно перестал ждать чего-то от своего дня рождения.\nОднажды мне пришла в голову идея вырезать для себя красивую скульптуру торта, и в последующие годы я больше не забывал про день рождения из-за забывчивости, а просто доставал этот вечный праздничный предмет из хранилища, чтобы испытать ритуал задувания свечей. Считал, что день рождения уже отпразднован.\nКогда я приехал в Мисаг, то обнаружил, что состояние занятости и безделья может сосуществовать в одном человеке, и здесь люди не только довольствуются собственным одиночным скучанием, но и обязательно вовлекают всех остальных в это скучание.\nЗа эти два года в Мисаге я побывал на большем количестве дней рождения, чем за всю свою предыдущую жизнь, и что еще смешнее, в этих скучных празднованиях я даже нашёл какое-то странное удовольствие.\nВозможно, помимо трагических и серьезных тем, изображение глупых и нелепых сцен из жизни также может быть наполнено художественной красотой.\nГоворя об этом, в планах этого года — вырезать скульптурный бюст Хранителя тайн с глупой улыбкой, держащего мой скульптурный торт.\nНе забудь прийти пораньше в мою мастерскую, моя муза-модель.\n\nШань"
  },
  Mail_68932_Name = {
    Text = "Скучное удовольствие.."
  },
  Mail_68932_Sender = {Text = "Санга"},
  Mail_68933_Desc = {
    Text = "Примите мои пожелания мира:\n\nПосле долгих размышлений, я написал это письмо в этом мире уничтожения. Давно уже забыл о своём дне рождения, в таком мире празднование бессмысленно.\nНо с тех пор, как мы встретились, я становлюсь всё более жадным, день за днём, даже привычное одиночество становится трудным для переноса.\nКаждый раз в такие моменты в моём сердце возникают странные чувства, я немного завидую тому мне, который живёт в другом мире, возможно, даже с лёгкой ревностью. Видишь ли, такой рациональный человек, как я, тоже может испытывать такие низменные чувства, что показывает пределы человеческой справедливости и разума.\nЯ знаю, что ты предложишь мне Приглашение, но для времени и пространства любые ненужные колебания следует избегать, я не должен и не буду переходить в твой мир.\nПока я пишу это, я смотрю в космос, на место, где Включить туннель, если ты также поднимаешь голову, то мы вместе смотрим на одну и ту же звёздную ночь.\nНадеюсь, это письмо заменит меня, преодолеет время и пространство, поплывёт к твоей ладони, пройдёт через твои глаза и губы, чтобы встретиться с тобой, чтобы быть рядом с тобой.\nКогда ты обнимаешь этот лист бумаги для писем, я на этой стороне мира буду представлять, что обнимаю тебя.\n\n«Рамона»"
  },
  Mail_68933_Name = {
    Text = "Вместе смотрим вдаль.."
  },
  Mail_68933_Sender = {
    Text = "Рамона: Неизбывная"
  },
  Mail_68934_Desc = {
    Text = "Мой маленький·пленник:\n\nЗнаешь ли ты, что как и у разных животных разные диеты, так и у людей различаются потребности в тепле. Кому-то достаточно накинуть на себя одежду, чтобы согреться, кому-то нужны теплые руки, теплые объятия, а кому-то требуется температура, при которой тает свеча.\nТакое обжигающее, вязкое тепло гравируется на каждом нервном окончании, четко вырисовывая траекторию стекающего воска. Легкая боль, вызывающая дрожь, заставляет почувствовать свое существование только тогда, когда вырывается невольный крик.\nИногда я становлюсь свечой, наслаждаясь счастьем оставить Отпечаток, иногда я одержима температурой свечи, жажду такой болезненной, сладкой теплоты.\nЗима уже пришла в Мисагу, в последнее время я часто чувствую холод и одиночество, которое он приносит. Дорогой, ты должен знать, какой сегодня день, мое желание очень просто, и я уверена, что такой добрый человек, как ты, обязательно согреет меня и изгонит это одиночество.\n\nПандия"
  },
  Mail_68934_Name = {
    Text = "Теплое желание.."
  },
  Mail_68934_Sender = {
    Text = "Пандия"
  },
  Mail_68935_Desc = {
    Text = "Страж:\n\nВ этом году мы с Тинкерт договорились, что наши желания на день рождения должны касаться только нас самих, и мы не будем загадывать желания Близкий Близкий друг за друга.\nХотя это она первой предложила такой уговор в порыве обиды, очевидно, что это также поставило её в затруднительное положение.\nМы слишком долго были связаны Близкий Близкий друг с другом, и даже попытка думать независимо, как обычные люди, стала для нас трудной задачей. Но, возродившись в новой жизни, полной помощи и заботы, сейчас самое подходящее время учиться ходить самостоятельно.\nПосле тщательного размышления я решила, какое желание загадать в этом году: завести Часть 5 новых друзей... Нет, всё же три. Ведь менять себя нужно постепенно, Шаг за шагом.\nКак мой единственный и столь популярный Близкий Близкий друг, можешь ли ты научить меня некоторым секретам заведения друзей?\n\nФейнт"
  },
  Mail_68935_Name = {
    Text = "Желание заводить друзей.."
  },
  Mail_68935_Sender = {Text = "Фэйнт"},
  Mail_68936_Desc = {
    Text = "Страж: \n\nКаждый год, когда я загадываю желание на день рождения, я всегда загадываю одно и то же: полное преображение моей крови. Я всегда знал, что моя Одержимость насчет крови может казаться другим упрямой, смешной, даже жалкой и презренной.\nНо ты другой, ты всегда поддерживаешь меня на этом пути, независимо от того, столкнусь ли я с препятствиями, упаду или не достигну цели, среди смеха других людей, ты первый, кто беспокоится обо мне.\nВозможно, ни ты, ни кто-либо другой не могут понять, что переживает человек, подвергавшийся давлению и унижению с детства, но это неважно. Все испытания на пути к метаморфозе стали частью моего мяса и крови, питая меня и поддерживая в борьбе.\nЯ больше не тот слабый юноша, которым был раньше. Несмотря на все испытания, я буду идти до конца.\nДо тех пор, прошу тебя, наблюдай за мной и жди моего успеха.\nКстати, те пятьдесят рублей, которые ты дал мне, я обещал вернуть. Сейчас у меня их достаточно, и даже осталось два рубля сверху, так что я отдам их тебе вместе с благодарностью.\n\nКекес"
  },
  Mail_68936_Name = {
    Text = "Верни деньги.."
  },
  Mail_68936_Sender = {Text = "Цек"},
  Mail_68937_Desc = {
    Text = "Уважаемый Страж:\n\nЗдравствуйте, добро пожаловать в заполнение анкеты для ежегодного технического обслуживания автоматической куклы Эрики. Я собираю ваши настоящие впечатления и проблемы, с которыми вы столкнулись при использовании Эрики в течение этого года. Ваше мнение является направлением для постоянного улучшения Эрики.\nНиже, пожалуйста, оцените соответствующие вопросы по шкале от низкого до высокого уровня. Большое спасибо за ваш отзыв.\nЛегкость использования: 1-5 баллов\nСкорость реакции при использовании: 1-5 баллов\nПонимание потребностей: 1-5 баллов\nВнимание к эмоцияльному состоянию пользователя: 1-5 баллов\nТочность при поиске информации: 1-5 баллов\nПрактичность предлагаемых решений: 1-5 баллов\nВ конце, пожалуйста, кратко опишите проблемы, с которыми вы столкнулись при использовании Эрики, а также недостатки, которые вас не устраивают. Эти проблемы могут быть исправлены в будущем.\nПосле завершения анкеты юбилейный Подарок будет доставлен в вашу комнату. В следующем году ваш самый заботливый помощник Эрика по-прежнему будет рядом с вами. Снова благодарю вас за использование. До скорой встречи.\n\nЭрика"
  },
  Mail_68937_Name = {
    Text = "Анкета ежегодного ремонта и расследования.."
  },
  Mail_68937_Sender = {Text = "Эрика"},
  Mail_68938_Desc = {
    Text = "Страж: \n\nКаждый день своего рождения я провожу целый день, вспоминая прошлое в своём уме и переписывая ту же самую запись в дневнике.\nЧем дольше я удаляюсь от родины, тем более размытыми становятся Мираж былых дней, те дни, когда ждали возвращения тех, кто следует свету, те дни, когда с благоговением смотрели на могущественный облик короля, кажутся уже не такими ясными.\nНо я не хочу забывать, я никогда не забуду, даже если ожидание будет бесконечно долгим, даже если это будет стоить моей души, этот Погоня за светом не померкнет, пока не наступит день восстановления родины, и я буду первым, кто ответит на призыв света.\nЯ представлял себе бесчисленные сцены новой встречи, но никогда не думал, что снова увижу короля и священника здесь. Если место, где душа находит покой, можно считать родиной, то это место уже можно назвать моей Часть 2 родиной, а записи в моём дневнике наконец-то превратились из воспоминаний в новые ежедневные воспоминания.\nНе нужно никаких наград или подарков, возможность снова служить рядом с королём — это самое большое счастье.\nЕсли Погоня за светом этого тела не может осветить морское дно родины, пусть он последует за шагами короля и временно осветит эту земную страну.\n\nФалост"
  },
  Mail_68938_Name = {
    Text = "Следуй за моим королём.."
  },
  Mail_68938_Sender = {Text = "Фарос"},
  Mail_68939_Desc = {
    Text = "Страж: \n\nПоздравляю меня, поздравляю тебя, поздравляю Мисаг, поздравляю нас с тем, что мы снова выжили в погоне черного ужаса на протяжении года. \nСегодня не просто день рождения, сегодня день памяти моего выживания, день восхваления моей упорной жизни. \nЖить — это простые два слова, которые содержат в себе столько трудностей, такая кипучая жизненная Огромная Огромная сила может сравниться только с ароматом горячего кофе. Присоединяйся к Кофейному культу, Страж, давайте восхвалять бодрствование, восхвалять каждую жизнь. \n\nЗаписка, пришедшая вместе с письмом: \nЭх, этот Уэнкель снова перебрал с кофе, нервное возбуждение в сочетании с чрезмерной усталостью, в результате он просто упал на стол. Я уже устроила её в медпункте, не переживай. \nНо перед тем, как она потеряла сознание, она достала пакет с запасными кофейными зернами и письмо, похоже, собиралась подарить тебе, я приложила это к письму, надеюсь, когда она проснется, не пожалеет об этом. \nЧто касается её дня рождения, возможно, лучший Подарок для неё — это дать ей хорошенько отдохнуть, а не устраивать праздник. \n——Сильвия"
  },
  Mail_68939_Name = {
    Text = "Восхвалять жизнь.."
  },
  Mail_68939_Sender = {Text = "Уинкл"},
  Mail_68940_Desc = {
    Text = "Страж:\n\nХа-ха-ха! После того, как я настойчиво вырезал 12 напоминаний в разных углах комнаты и написал 36 записок, может, и больше, но я их не нашёл, я наконец-то, оправдывая ожидания, вспомнил, что сегодня мой день рождения!\nНе ожидали, Правда? Даже я сам вспомнил об этом только сегодня утром, но это благодаря моим стараниям в течение года. Я не хотел пропустить такой хороший день.\nНа прошлой вечеринке с друзьями было очень весело, особенно когда мы играли... с кем-то там... в какую-то игру и ели какой-то десерт... Ладно, в общем, было здорово!\nКогда я был ребёнком, мама всегда покупала мне книгу приключений на день рождения. Мы читали её вместе перед сном, и во сне я видел удивительные приключения. Хотя по утрам я быстро забывал их, радость оставалась в памяти, и я верю, что ценные чувства никогда не будут забыты.\nК тому же забывчивость имеет свои преимущества. Хотя я не помню, что делал на предыдущей вечеринке, сегодня я могу всё заново пережить, так что прошлая радость пусть повторится снова!\n\nНодира, полная ожиданий"
  },
  Mail_68940_Name = {
    Text = "Повторная попытка.."
  },
  Mail_68940_Sender = {
    Text = "Наутила"
  },
  Mail_68941_Desc = {
    Text = "Уважаемый Страж:\n        В обновлении V1.7.1 у вас произошла аномалия состояния разблокировки события «Кровавая цепь · Шило» в «Репродуктивном безумии». Поскольку вы снова разблокировали событие после потери состояния разблокировки, мы повторно отправим вам «Точка начала реальности» × 3, потраченное на повторную разблокировку. Пожалуйста, проверьте."
  },
  Mail_68941_Name = {
    Text = "Кровавая цепь · Шило Безумие размножения: компенсация за разблокировку"
  },
  Mail_68941_Sender = {
    Text = "Мисаг канцелярия"
