  Mail_71332_Desc = {
    Text = "Уважаемый Страж:\n Акция «Перед тем как весна увянет» завершена, теперь оставшиеся у Хранителя тайн «Весёлые стихи», «Меланхоличная поэзия» и «Поэма сожаления» будут конвертированы по пропорции «Купон розового золота» × 40 за каждую, пожалуйста, примите к сведению."
