  },
  Mail_71848_Desc = {
    Text = "Уважаемый Страж: \n Акция «Послание розы» завершена. Теперь «Веер из перьев духовной птицы» меняется на каждую по «Купон розового золота» × 40. Пожалуйста, Страж, проверьте."
