    Text = "Мисаг Школьный комитет"
  },
  Mail_74020_Desc = {
    Text = "Уважаемый Страж:\nАкция «Звёзды на своих местах: повтор» завершена. Теперь «бездушный зародыш», «безжелательный эмбрион» и «безграничное зародышевое ядро» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, проверьте."
  },
  Mail_74020_Name = {
    Text = "Восстановление эмбриона"
  },
  Mail_74020_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_74347_Desc = {
    Text = "Уважаемый Страж:\nАкция «Пастырь душ: повтор» завершена. Теперь «билеты на благотворительную распродажу» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_74347_Name = {
    Text = "Сбор билетов на благотворительную распродажу"
  },
  Mail_74347_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_74841_Desc = {
    Text = "Партнёр:\n\nВ прошлом году в этот день я и не думал, что спустя год отправлю это письмо в пустую почту.\nТогда ты недавно поступил в Мисаг и был таким же упрямым и ленивым студентом. Сейчас я часто думаю, что был слишком строг с тобой и слишком заботился о своей рациональной и сдержанной маске.\nВ тот день год назад я купил букет цветов. Я стоял перед библиотекой и долго смотрел на розы, завернутые в красную ленту и темно-зеленую бумагу, а потом поставил их у своей кровати.\nЦветы давно увяли, но я сохранил ту ярко-красную ленту, привязав ее к серебряному ключу K-0617. Она все еще такая же яркая и новая.\nКак же мне хочется снова купить букет роз, но теперь они только завянут у меня на тумбочке, и у них больше нет другого места.\nПривыкнув планировать все дела заранее, я испытываю чувство сожаления как нечто новое и горькое.\nНо я продолжаю хранить почти слепую веру в то, что твоя душа не покинула нас. Возможно, ты временно путешествуешь где-то во Вселенной, но в конце концов обязательно вернешься сюда, ко мне.\nЯ не считаю это безумной мечтой. Каждый раз, приходя в Чёрный бассейн и глядя на твое лицо, я чувствую в своем сердце тепло, которое связывает нас и вызывает Резонанс.\nЯ буду продолжать верить и ждать встречи снова. Когда наши руки снова соприкоснутся, я лично вручу тебе те розы, которые должен был подарить сегодня.\n\nРамона"
  },
  Mail_74841_Name = {Text = "Роза.."},
  Mail_74841_Sender = {
    Text = "Рамона"
  },
  Mail_76410_Desc = {
    Text = "Уважаемый Страж:\nАкция «Призрак дождливого города» завершена. Теперь оставшиеся у Хранителя тайн «Череп бледного зверя», «Череп теневой твари» и «Череп монстра алого цвета» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
