    Text = "Восстановление памяти через пазлы"
  },
  Mail_78653_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_78792_Desc = {
    Text = "Уважаемый Страж:\nАкция «Когда растает снег: повтор» завершена. Теперь мы будем возвращать оставшуюся у Хранителя тайн валюту акции «замороженный бутон», «серебряный бутон» и «солнечный бутон» по курсу «Купон розового золота» × 40 за каждый. Пожалуйста, не забудьте получить."
  },
  Mail_78792_Name = {
    Text = "Восстановление почки цветка"
  },
  Mail_78792_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_79390_Desc = {
    Text = "Уважаемый Страж:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы обеспечить Хранителям тайн лучший игровой опыт в Университете Мисагард, приглашаем вас заполнить анкету. В благодарность за участие мы подготовили награду — «Серебряные ядра» × 200, которую можно получить после заполнения анкеты. Срок заполнения анкеты — до 17 марта, 9:00. Пожалуйста, заполните вовремя.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя тайн. Ваши отзывы обязательно сделают Университет Мисагард ещё лучше!\n        — Да укажет Серебряный ключ путь."
  },
  Mail_79390_Name = {
    Text = "Анкета для оценки версии V2.1.0"
  },
  Mail_79390_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_79646_Desc = {
    Text = "Уважаемый Страж:\nАкция «Погребённое воспоминание» завершена. Теперь «диагностический отчёт» меняется на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_79646_Name = {
    Text = "Валюта, погребённая под воспоминаниями"
  },
  Mail_79646_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_80091_Desc = {
    Text = "Страж:\n\n Когда ты откроешь это письмо, значит, подсказка, которую я заложил в твоём сердце, начала действовать.\nХа, не переживай. Это всего лишь незначительное гипнотическое заклинание, чтобы обеспечить успешное проведение моего дня рождения, которое не окажет на тебя никакого влияния.\nВ дальнейшем ты от всей души почувствуешь импульс пойти по магазинам, следуй этому порыву и выйди на улицу, выбери из витрин самый подходящий для меня Подарок и передай его мне.\nЯ знаю о твоих сомнениях в данный момент и признаю их разумность, но разве у именинника не должно быть немного привилегий? Я делаю это лишь потому, что боюсь, ты забудешь об этом особом дне. В конце концов, ты же тот, о ком я всё время думаю.\nНаконец, я буду с нетерпением ждать твоего визита — не забудь о подарке.\n\nКлементина"
  },
  Mail_80091_Name = {
    Text = "Подарок, выбранный «лично»"
  },
  Mail_80091_Sender = {
    Text = "Клементина"
  },
  Mail_81288_Desc = {
    Text = "Уважаемый Страж:\n        Благодарим вас за поддержку и признание «Кануна забвения». Чтобы обеспечить Хранителям тайн лучший игровой опыт в Университете Мисагард, приглашаем вас заполнить анкету. В благодарность за участие мы подготовили награду — «Серебряные ядра» × 200, которую можно получить после заполнения анкеты. Срок заполнения анкеты — до 14 апреля, 9:00. Пожалуйста, заполните вовремя.\n        <SurveyLink:【Нажмите, чтобы заполнить】>\n        Мы внимательно выслушаем каждого Хранителя тайн. Ваши отзывы обязательно сделают Университет Мисагард ещё лучше!\n        — Да укажет Серебряный ключ путь."
  },
  Mail_81288_Name = {
    Text = "Анкетное исследование V2.2.0"
  },
  Mail_81288_Sender = {
    Text = "Мисаг канцелярия"
  },
  Mail_81326_Desc = {
    Text = "Милостивый государь:\n\nСегодня для меня и Полюкса единственный праздник в году. В церкви нам не позволено чрезмерно сосредотачиваться на собственном смысле, все наши ценности существуют лишь в служении тому, кто несет Погоня за светом, этой вечной вещи, и перед такой верой другие праздники кажутся бессмысленными иллюзиями.\nНо в день рождения я и Полюкс все равно тайком отмечаем его, мы готовим Близкий Близкий друг другу как можно меньшие подарки и секретно ожидаем этого дня.\nМоменты празднования дня рождения часто происходят в глубокую ночь — это единственное время, когда у нас есть свобода, ловкие руки Полюкса и его идеи всегда делают его подарки лучше моих, однажды он даже сплел цветок из собранных перьев.\nНа самом деле, мне не очень хорошо удается готовить сюрпризы, Полюкс всегда говорит, что мои обычные выражения выдают все, и все, что у меня есть, вероятно, понимается вами как более скудное и скучное, но сегодня я придумал отличный способ поделиться радостью с вами.\nКогда вы услышите, как в окно стучат три раза вечером, не бойтесь, откройте окно, я уведу вас ощутить прикосновение облаков и ночного ветерка.\n\nКастор"
  },
  Mail_81326_Name = {
    Text = "Ночные путешествия..."
  },
  Mail_81326_Sender = {
    Text = "Кастор"
  },
  Mail_84142_Desc = {
    Text = "Страж: \n\nПеред нашей встречей я написала это письмо, чтобы официально пригласить вас и представить моё«День Рождения в плавании». \nПервой остановкой в этом плавании будет река Темза. Мы поднимемся на грузовое судно, превращенное в передвижной ресторан, чтобы поплавать и попробовать консервированные ананасы и ром. Это вкусный деликатес, который предоставляется только на дни рождения моряков, надеюсь, вам понравится. \nВторой остановкой будет смотровая площадка порта. Не переживайте, у меня уже есть разрешение от ассоциации воздушных шаров. Когда воздушные шары поднимутся в небо и мы сможем посмотреть на весь лондонский канал, мы вместе разрежем торт в честь праздника. \nРаньше условия для плавания были ограничены, и так называемый торт на день рождения был просто моделью, созданной плотником из дуба и карамели, поэтому я не знаю, как он на вкус; но в этот раз мы можем поделиться впечатлениями, я думаю, кроме удовольствия от еды, я получу больше. \nТретья остановка, или, должно быть, названная третьим этапом, это индивидуальная звёздная Карта. Я отметил на навигационной карте положение небесных тел в момент моего рождения, и если вы не против, я хотел бы отметить вашу тоже; такая уникальная навигационная звёздная Карта будет самым ценным подарком. \nНа самом деле, когда я писала это письмо, у меня были сомнения. Эти действия, безусловно, выходят за рамки обычного, но сегодня особенный день, и вы для меня тоже особенный человек, стоящий того, чтобы я нарушила правила. \nПоэтому, пожалуйста, не отказывайтесь и приходите в назначенное время. \n\nКеппершант"
  },
  Mail_84142_Name = {
    Text = "«Проход» Приглашение"
  },
  Mail_84142_Sender = {
    Text = "Корпосант"
  },
  Mail_84355_Desc = {
    Text = "Уважаемый Страж:\nАкция «Колеблясь под ливнем» завершена. Теперь оставшиеся у Хранителя тайн игровые деньги «Сигнальный флаг» будут обменены по курсу «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
