  },
  Mail_89744_Desc = {
    Text = "Уважаемый хранитель:\n        В обновлении V2.2.2 мы увеличили награду за «Пожертвование источника - Фонд пожертвований выпускников». Для хранителей, которые уже собрали дополнительную награду перед обновлением, мы возместим соответствующую награду. Пожалуйста, проверьте."
