  Mail_89903_Desc = {
    Text = "Уважаемый Хранитель:\n        Благодарим вас за поддержку и признание «Канун забвения». Чтобы Хранители могли получить лучший игровой опыт в Университете Мисаг, мы приглашаем вас заполнить следующую анкету об игровом опыте. В знак благодарности за ваше участие мы подготовили «Серебро» × 200 в качестве награды — её можно получить после заполнения анкеты. Срок заполнения анкеты истекает 9 ноября в 9:00. Пожалуйста, не забудьте заполнить её вовремя.\n        <SurveyLink:[Нажмите, чтобы перейти к заполнению]>\n        Мы внимательно выслушаем предложения каждого Хранителя, и ваши отзывы обязательно помогут Университету Мисаг становиться лучше!\n        —Да осветит твой путь Серебряный ключ."
