  },
  Mail_90015_Desc = {
    Text = "Уважаемый Страж:\n1.5-летие мероприятия завершено. Теперь оставшиеся у Хранителя тайн «Ваучер базового наряда (первый выпуск)» обмениваются на каждую «Приглашение бесформенного» × 1. Пожалуйста, не забудьте проверить."
