  },
  Mail_90231_Desc = {
    Text = "Уважаемый Страж:\nАкция «Узник зеркал» завершена. Теперь «Книга общих знаний», «Книга математики», «Книга литературы» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
