  },
  Mail_91725_Desc = {
    Text = "Уважаемый Страж:\nАкция «Жертвоприношение бездне: повтор» завершена. Теперь «Слеза жреца», «Кровь жреца» и «Мозг жреца» меняются на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_91725_Name = {
    Text = "Валюта акции \"Жертвоприношение бездне\"восстановление"
  },
  Mail_91725_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_94424_Desc = {
    Text = "Уважаемый Страж:\nАкция «Великое завоевание» завершена. Теперь «Барбекю по-леонски» меняется на каждую по «Купон розового золота» × 40. Пожалуйста, не забудьте проверить."
  },
  Mail_94424_Name = {
    Text = "Вкусное Инкарнация на решетке Лео для утилизации валюты"
  },
  Mail_94424_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_94425_Desc = {
    Text = "Уважаемый Страж:\nАкция «Великое завоевание» завершена. Теперь оставшиеся у Хранителя тайн «Скидочные купоны на простую фантастическую одежду (второе издание)» меняются на каждую по «Приглашение бесформенного» × 1. Пожалуйста, не забудьте проверить."
  },
  Mail_94425_Name = {
    Text = "Талон нарядов с иллюзиями (Часть 2 этап) для утилизации"
  },
  Mail_94425_Sender = {
    Text = "Мисаг Школьный комитет"
  },
  Mail_94503_Desc = {
    Text = "Мой маяк:\n\nС тех пор как я и Кастор пришли сюда, ваше внимание к нам можно сравнить с подарком новой жизни. Спасибо вам за прекрасно приготовленный для нас торт ко дню рождения. Извините, что перепутали двух маленьких птичек, изображенных на торте, с бабочками, но нам действительно очень понравился этот Подарок — это был наш первый Подарок ко дню рождения от кого-то другого.\nМы также получили открытку с поздравлениями от декана Чорта. На белом конверте была приклеена золотая красивая печать, а внутри было много хороших пожеланий. Это действительно теплое место, и в нашей жизни не было таких счастливых моментов, как сейчас.\nПожалуйста, придите, чтобы отпраздновать день рождения с Кастором и мной. Это ритуал, который мы придерживались с детства. В качестве нашего благодетеля мы подготовили для вас взаимные подарки — корону, которую я сплёл из перьев, выпавших у Кастора.\nЯ посвящаю эту простой корону вам, чтобы выразить нашу искреннюю благодарность. Я готов следовать за вами в течение оставшейся жизни, исполняя великое видение этой школы, устраняя истинные злодеяния и тьму.\nПосле долгого времени без этих вещей Кастор даже посмеивался над тем, что моё мастерство не такое, как в детстве. Надеюсь, вы не будете недовольны.\n\nПоллукс"
  },
  Mail_94503_Name = {
    Text = "Перья в короне…"
  },
  Mail_94503_Sender = {
    Text = "Поллукс"
  },
  Mail_95382_Desc = {
    Text = "Милый маленький Близкий Близкий друг:\n\nМаленький Близкий Близкий друг, сегодня день моего прибытия.\nНе как постоянно горящая огненная сфера, а день рождения девочки по имени Кэтигла.\nПо привычке из прошлого, в этот день мы будем устраивать грандиозный банкет, безудержно наслаждаясь вином и жареным мясом.\nКонечно, всегда найдутся задиры, которые будут дразнить меня за то, что я снова на год старше, поэтому я поприветствовал их своими кулаками.\nТеперь этот банкет получил новую функцию, чтобы вспоминать времена, проведенные вместе.\nВ этом году я планирую добавить еще одно мероприятие, а именно — охота на наших милых друзей!\nЗнаешь, я уже не могу дождаться, когда схвачу тебя на своем банкете, украсив всю ночь твоими стесненными милыми выражениями, полусонными глазами, исходящими слащавыми ароматами — это будет мой лучший день рождения с момента рождения!\nСейчас уже поздно готовить планы по побегу, ведь когда ты читаешь это письмо... я уже пришел к твоей двери.\nНе бойся, маленький Близкий Близкий друг, если всё пройдет нормально, ты только услышишь здесь самые лучшие истории, попробуешь самые вкусные блюда.\nКонечно, пойманным зверям могут случиться несколько неожиданностей, верно?\nО, просто Иди со мной, маленький Близкий Близкий друг, эта прекрасная ночь предназначена для того, чтобы провести её вместе со мной.\n\nКэтигла"
