  Mail_96323_Desc = {
    Text = "Страж:\n\nЖивые празднуют дни рождения, чтобы в оставшиеся дни найти смысл. А я лишь использую эту ночь, чтобы сделать аромат смерти более насыщенным.\nТем, кто больше не борется и не имеет привязанностей, мытьё всего их прежнего нечистого уйдёт, а их сожаления станут похожи на тонкую соль, которая плавится в мясных жилах в нужный момент, создавая влажный и покорный аромат. Их кости издают тихий треск, выделяющееся из кожи масло остается лёгким, как мята, а незавершённые слова их душ будут выходит в процессе варки, оставляя тонкий сладкий запах. Я уже начала фантазировать о том, как ты станешь спокойным — хруст кожи перед огнём, чувства, поднимающиеся между костями и мясом, сладкий вкус, как твоя чистая душа постепенно съедается... \nНо ты другая. \nТы все еще светишься, все еще пульсируешь, обладая ароматом, с которым ни одна душа не может сравниться, intoxicating. Ты то, чего я готова ждать, и я даже надеюсь, что это ожидание сможет длиться дольше, чем вечность.\nВ этом бесконечном круге лет, твое появление наделило смыслом мой день рождения. Это не просто прекрасное угощение, но и ради твоей продолжающейся жизни.\n\nДуллсейн"
